--
-- Name: admin_cleanup_gaming_sessions(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_cleanup_gaming_sessions() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
v_deleted int := 0;
BEGIN
WITH to_keep AS (
SELECT id FROM (
SELECT id, ROW_NUMBER() OVER (PARTITION BY casino_id ORDER BY start_time DESC) AS rn
FROM gaming_sessions WHERE is_active = false
) r WHERE rn <= 3000
)
DELETE FROM gaming_sessions
WHERE is_active = false AND id NOT IN (SELECT id FROM to_keep);
GET DIAGNOSTICS v_deleted = ROW_COUNT;

DELETE FROM live_kpi_snapshots WHERE snapshot_at < NOW() - INTERVAL '24 hours';
DELETE FROM live_events WHERE created_at < NOW() - INTERVAL '2 hours';
DELETE FROM cron.job_run_details
WHERE runid NOT IN (SELECT runid FROM cron.job_run_details ORDER BY start_time DESC LIMIT 30);

RETURN jsonb_build_object('sessions_deleted', v_deleted);
END;
$$;


ALTER FUNCTION public.admin_cleanup_gaming_sessions() OWNER TO postgres;

--
-- Name: app_visible_casinos(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.app_visible_casinos() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.id
  from casinos c
  cross join (
    select u.role::text as role, u.casino_id, u.jurisdiction, u.province
    from users u
    where u.id = auth.uid() and u.is_active = true
  ) me
  where
    me.role = 'super_admin'
    or (me.role in ('casino_admin', 'compliance_officer') and c.id = me.casino_id)
    or (me.role in ('regulator', 'national_regulator')
        and me.jurisdiction is not null and c.jurisdiction = me.jurisdiction)
    or (me.role = 'provincial_regulator'
        and me.jurisdiction is not null and c.jurisdiction = me.jurisdiction
        and me.province is not null and c.province = me.province)
$$;


