-- Name: award_training_credits(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.award_training_credits() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE 
v_staff_id uuid; 
v_module_id uuid; 
v_credits int;
v_exists boolean;
BEGIN 
IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN
SELECT staff_id, module_id INTO v_staff_id, v_module_id 
FROM training_enrollments 
WHERE id = NEW.id;

SELECT credits_awarded INTO v_credits 
FROM training_modules 
WHERE id = v_module_id;

-- Check if credits already exist
SELECT EXISTS(
SELECT 1 FROM training_credits WHERE enrollment_id = NEW.id
) INTO v_exists;

IF NOT v_exists THEN
INSERT INTO training_credits (
staff_id, 
enrollment_id, 
module_id, 
credits_earned,
earned_at
) VALUES (
v_staff_id, 
NEW.id, 
v_module_id, 
v_credits,
NOW()
);
END IF;
END IF;

RETURN NEW; 
END; 
$$;


