--
-- Name: calculate_rpi_roi(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_rpi_roi(p_casino_id uuid, p_month date) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_total_protected numeric;
  v_platform_cost   numeric := 50000;
BEGIN
  SELECT total_protected_zar INTO v_total_protected
  FROM public.revenue_protection_monthly
  WHERE casino_id = p_casino_id AND month = p_month;

  IF v_total_protected IS NULL OR v_total_protected = 0 THEN
    RETURN 0;
  END IF;

  RETURN ROUND(v_total_protected / v_platform_cost, 2);
END;
$$;


ALTER FUNCTION public.calculate_rpi_roi(p_casino_id uuid, p_month date) OWNER TO postgres;

--
-- Name: calculate_rpi_roi(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_rpi_roi(p_casino_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone) RETURNS TABLE(total_revenue_protected numeric, total_intervention_cost numeric, roi_percentage numeric, interventions_count bigint, avg_intervention_value numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
RETURN QUERY
SELECT 
COALESCE(SUM(rpe.revenue_protected), 0) as total_revenue_protected,
COALESCE(SUM(rpe.intervention_cost), 0) as total_intervention_cost,
CASE 
WHEN COALESCE(SUM(rpe.intervention_cost), 0) > 0 
THEN (COALESCE(SUM(rpe.revenue_protected), 0) / COALESCE(SUM(rpe.intervention_cost), 1) * 100)
ELSE 0
END as roi_percentage,
COUNT(*) as interventions_count,
AVG(rpe.revenue_protected) as avg_intervention_value
FROM public.revenue_protection_events rpe
WHERE rpe.casino_id = p_casino_id
AND rpe.created_at >= p_start_date
AND rpe.created_at <= p_end_date;
END;
$$;


ALTER FUNCTION public.calculate_rpi_roi(p_casino_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone) OWNER TO postgres;

--
-- Name: call_risk_engine(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.call_risk_engine() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  _url       text;
  _hmac_key  text;
  _payload   jsonb;
  _payload_t text;
  _ts        text;
  _sig       text;
BEGIN
  -- Resolve URL from per-database GUC — no hardcoded constant.
  -- Returns NULL if the GUC has never been set (missing = misconfiguration).
  _url := current_setting('app.risk_engine_url', true);

  IF _url IS NULL OR _url = '' THEN
    RAISE WARNING '[risk-engine] app.risk_engine_url not configured — trigger skipped. '
                  'Set via: ALTER DATABASE postgres SET app.risk_engine_url = ''<url>''';
    RETURN NEW;
  END IF;

  -- Access vault through SECURITY DEFINER wrapper — never directly
  _hmac_key := public.fn_get_active_hmac_secret();

  IF _hmac_key IS NULL THEN
    RAISE WARNING '[risk-engine] active HMAC secret unavailable — skipping';
    RETURN NEW;
  END IF;

  _payload := jsonb_build_object(
    'player_id',        NEW.player_id,
    'casino_id',        NEW.casino_id::text,
    'event_id',         NEW.id::text,
    'bet_amount',       NEW.bet_amount,
    'win_amount',       NEW.win_amount,
    'duration_seconds', NEW.duration_seconds,
    'event_type',       NEW.event_type,
    'session_id',       NEW.session_id,
    'game_type',        NEW.game_type,
    'created_at',       NEW.created_at
  );
  _payload_t := _payload::text;
  _ts        := extract(epoch FROM clock_timestamp())::bigint::text;

  -- HMAC-SHA256: message = "<unix_ts>.<payload_json>"
  _sig := encode(hmac((_ts || '.' || _payload_t)::bytea, _hmac_key::bytea, 'sha256'), 'hex');

  -- Async POST — no API key, no anon key, HMAC signature only
  PERFORM net.http_post(
    url     := _url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'X-Timestamp',  _ts,
      'X-Signature',  _sig
    ),
    body := _payload
  );

  RETURN NEW;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[risk-engine] trigger error suppressed: %', SQLERRM;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.call_risk_engine() OWNER TO postgres;

