--
-- Name: check_distributed_rate_limit(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_distributed_rate_limit(p_key text, p_limit integer, p_window_seconds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  _window_start timestamptz;
  _count        int;
BEGIN
  _window_start := now() - (p_window_seconds || ' seconds')::interval;

  INSERT INTO public.distributed_rate_limits (key, hits, window_start, expires_at)
  VALUES (
    p_key,
    1,
    now(),
    now() + (p_window_seconds || ' seconds')::interval
  )
  ON CONFLICT (key) DO UPDATE
    SET
      hits = CASE
        WHEN distributed_rate_limits.window_start <= _window_start
        THEN 1           -- Expired window: reset counter
        ELSE distributed_rate_limits.hits + 1
      END,
      window_start = CASE
        WHEN distributed_rate_limits.window_start <= _window_start
        THEN now()
        ELSE distributed_rate_limits.window_start
      END,
      expires_at = CASE
        WHEN distributed_rate_limits.window_start <= _window_start
        THEN now() + (p_window_seconds || ' seconds')::interval
        ELSE distributed_rate_limits.expires_at
      END
  RETURNING hits INTO _count;

  RETURN jsonb_build_object(
    'allowed', _count <= p_limit,
    'count',   _count,
    'limit',   p_limit
  );
END;
$$;


ALTER FUNCTION public.check_distributed_rate_limit(p_key text, p_limit integer, p_window_seconds integer) OWNER TO postgres;

--
-- Name: check_player_self_exclusion(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_player_self_exclusion(p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_id_number text DEFAULT NULL::text) RETURNS TABLE(global_identity_id uuid, is_self_excluded boolean, exclusion_reason text, exclusion_ends_at timestamp with time zone, sen_active boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_global_id      UUID;
  v_email_hash     TEXT;
  v_phone_hash     TEXT;
  v_id_number_hash TEXT;
BEGIN
  v_email_hash     := CASE WHEN p_email     IS NOT NULL THEN hash_identity(p_email)     ELSE NULL END;
  v_phone_hash     := CASE WHEN p_phone     IS NOT NULL THEN hash_identity(p_phone)     ELSE NULL END;
  v_id_number_hash := CASE WHEN p_id_number IS NOT NULL THEN hash_identity(p_id_number) ELSE NULL END;

  SELECT gi.id INTO v_global_id
  FROM global_identities gi
  WHERE
    (v_email_hash     IS NOT NULL AND gi.email_hash     = v_email_hash)
    OR (v_phone_hash  IS NOT NULL AND gi.phone_hash     = v_phone_hash)
    OR (v_id_number_hash IS NOT NULL AND gi.id_number_hash = v_id_number_hash)
  ORDER BY (
    CASE WHEN v_id_number_hash IS NOT NULL AND gi.id_number_hash = v_id_number_hash THEN 2 ELSE 0 END
    + CASE WHEN v_email_hash   IS NOT NULL AND gi.email_hash     = v_email_hash     THEN 1 ELSE 0 END
  ) DESC
  LIMIT 1;

  IF v_global_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    gi.id,
    gi.is_self_excluded,
    gi.exclusion_reason,
    gi.exclusion_ends_at,
    EXISTS (
      SELECT 1
      FROM player_identity_map pim
      JOIN player_pseudonym_tokens ppt ON ppt.player_id = pim.player_id
      JOIN sen_protection_broadcasts spb ON spb.pseudonym_token = ppt.token
      WHERE pim.global_identity_id = gi.id
        AND spb.expires_at > now()
    ) AS sen_active
  FROM global_identities gi
  WHERE gi.id = v_global_id;
END;
$$;


ALTER FUNCTION public.check_player_self_exclusion(p_email text, p_phone text, p_id_number text) OWNER TO postgres;

--
-- Name: check_rate_limit_sliding(text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_rate_limit_sliding(p_token_id text, p_endpoint text, p_casino_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
v_tier record;
v_window_start timestamptz := now() - interval '1 minute';
v_burst_window_start timestamptz;
v_minute_count int := 0;
v_burst_count int := 0;
v_cb_state text := 'closed';
v_allowed boolean := true;
v_reason text := null;
BEGIN
-- Get tier for this endpoint
SELECT * INTO v_tier FROM get_rate_limit_tier(p_casino_id, p_endpoint);

IF NOT FOUND THEN
-- Default tier
v_tier.tier_name := 'standard';
v_tier.requests_per_minute := 100;
v_tier.burst_limit := 150;
v_tier.burst_window_seconds := 10;
END IF;

v_burst_window_start := now() - (v_tier.burst_window_seconds || ' seconds')::interval;

-- Check circuit breaker state
SELECT cb.state INTO v_cb_state
FROM circuit_breaker_state cb
WHERE (p_casino_id IS NULL OR cb.casino_id = p_casino_id)
AND cb.endpoint = p_endpoint
AND cb.state = 'open'
AND (cb.auto_close_at IS NULL OR cb.auto_close_at > now())
LIMIT 1;

IF v_cb_state = 'open' THEN
RETURN jsonb_build_object(
'allowed', false,
'reason', 'circuit_breaker_open',
'tier', v_tier.tier_name,
'retry_after_seconds', 60,
'remaining', 0
);
END IF;

-- Count requests in sliding 1-minute window
SELECT COALESCE(SUM(request_count), 0) INTO v_minute_count
FROM api_rate_limits
WHERE token_id = p_token_id
AND endpoint = p_endpoint
AND window_start >= v_window_start;

-- Count requests in burst window
SELECT COALESCE(SUM(request_count), 0) INTO v_burst_count
FROM api_rate_limits
WHERE token_id = p_token_id
AND endpoint = p_endpoint
AND window_start >= v_burst_window_start;

-- Check burst limit first
IF v_burst_count >= v_tier.burst_limit THEN
v_allowed := false;
v_reason := 'burst_exceeded';
-- Then check per-minute limit
ELSIF v_minute_count >= v_tier.requests_per_minute THEN
v_allowed := false;
v_reason := 'per_minute_exceeded';
END IF;

-- Update the rate limit counter
IF v_allowed THEN
INSERT INTO api_rate_limits (token_id, endpoint, window_start, request_count)
VALUES (p_token_id, p_endpoint, date_trunc('minute', now()), 1)
ON CONFLICT (token_id, endpoint, window_start)
DO UPDATE SET request_count = api_rate_limits.request_count + 1;
END IF;

RETURN jsonb_build_object(
'allowed', v_allowed,
'reason', v_reason,
'tier', v_tier.tier_name,
'remaining_per_minute', GREATEST(0, v_tier.requests_per_minute - v_minute_count - CASE WHEN v_allowed THEN 1 ELSE 0 END),
'remaining_burst', GREATEST(0, v_tier.burst_limit - v_burst_count - CASE WHEN v_allowed THEN 1 ELSE 0 END),
'retry_after_seconds', CASE WHEN NOT v_allowed THEN
CEIL(EXTRACT(EPOCH FROM (date_trunc('minute', now()) + interval '1 minute' - now())))
ELSE NULL END
);
END;
$$;


ALTER FUNCTION public.check_rate_limit_sliding(p_token_id text, p_endpoint text, p_casino_id uuid) OWNER TO postgres;

