--
-- Name: detect_binge_sessions(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detect_binge_sessions(p_grpi_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_long_count    INTEGER := 0;
  v_max_dur       INTEGER := 0;
  v_binge_windows INTEGER := 0;
  v_severity      TEXT;
  v_score         NUMERIC;
  v_pattern_id    UUID;
  v_casino_id     UUID;
BEGIN
  DELETE FROM behavioural_patterns WHERE grpi_id = p_grpi_id AND pattern_type = 'binge_session';

  SELECT count(*), COALESCE(max(duration_minutes), 0)
  INTO v_long_count, v_max_dur
  FROM player_sessions
  WHERE grpi_id = p_grpi_id AND duration_minutes > 120
    AND session_start >= now() - '30 days'::interval;

  SELECT count(*) INTO v_binge_windows
  FROM player_sessions ps1
  WHERE ps1.grpi_id = p_grpi_id
    AND ps1.session_start >= now() - '30 days'::interval
    AND 3 <= (
      SELECT count(*) FROM player_sessions ps2
      WHERE ps2.grpi_id = p_grpi_id
        AND ps2.session_start BETWEEN ps1.session_start AND ps1.session_start + '4 hours'::interval
    );

  IF v_long_count >= 1 OR v_binge_windows >= 1 THEN
    v_score := LEAST(
      35.0
      + CASE WHEN v_max_dur > 240 THEN 30 WHEN v_max_dur > 180 THEN 20 WHEN v_max_dur > 120 THEN 10 ELSE 0 END
      + v_binge_windows * 8.0 + v_long_count * 5.0, 100.0);
    v_severity := CASE WHEN v_score >= 80 THEN 'critical' WHEN v_score >= 65 THEN 'high'
                       WHEN v_score >= 45 THEN 'medium' ELSE 'low' END;
    SELECT casino_id INTO v_casino_id FROM player_sessions WHERE grpi_id = p_grpi_id ORDER BY session_start DESC LIMIT 1;
    INSERT INTO behavioural_patterns (grpi_id, primary_casino_id, pattern_type, severity, score, evidence)
    VALUES (p_grpi_id, v_casino_id, 'binge_session', v_severity, v_score,
      jsonb_build_object('long_sessions_count', v_long_count, 'max_duration_minutes', v_max_dur,
                         'binge_windows', v_binge_windows, 'window_days', 30))
    RETURNING id INTO v_pattern_id;
    RETURN v_pattern_id;
  END IF;
  RETURN NULL;
END; $$;


ALTER FUNCTION public.detect_binge_sessions(p_grpi_id uuid) OWNER TO postgres;

--
-- Name: detect_cross_casino_chasing(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detect_cross_casino_chasing(p_grpi_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_multi_days   INTEGER := 0;
  v_max_casinos  INTEGER := 0;
  v_total_loss   NUMERIC := 0;
  v_severity     TEXT;
  v_score        NUMERIC;
  v_pattern_id   UUID;
  v_casino_id    UUID;
BEGIN
  DELETE FROM behavioural_patterns WHERE grpi_id = p_grpi_id AND pattern_type = 'cross_casino_chasing';

  SELECT count(*), COALESCE(max(casino_count), 0), COALESCE(sum(day_net), 0)
  INTO v_multi_days, v_max_casinos, v_total_loss
  FROM (
    SELECT date_trunc('day', session_start) AS day,
           count(DISTINCT casino_id) AS casino_count,
           sum(net_result)           AS day_net
    FROM player_sessions
    WHERE grpi_id = p_grpi_id AND session_start >= now() - '30 days'::interval
    GROUP BY 1
    HAVING count(DISTINCT casino_id) >= 2
  ) sub WHERE sub.day_net < 0;

  IF v_multi_days >= 1 THEN
    v_score := LEAST(45.0 + v_multi_days * 10.0 + (v_max_casinos - 2) * 15.0
                     + LEAST(abs(v_total_loss) / 1000.0, 15.0), 100.0);
    v_severity := CASE WHEN v_score >= 80 THEN 'critical' WHEN v_score >= 65 THEN 'high'
                       WHEN v_score >= 50 THEN 'medium' ELSE 'low' END;
    SELECT casino_id INTO v_casino_id FROM player_sessions WHERE grpi_id = p_grpi_id ORDER BY session_start DESC LIMIT 1;
    INSERT INTO behavioural_patterns (grpi_id, primary_casino_id, pattern_type, severity, score, evidence)
    VALUES (p_grpi_id, v_casino_id, 'cross_casino_chasing', v_severity, v_score,
      jsonb_build_object('multi_casino_days', v_multi_days, 'max_casinos_per_day', v_max_casinos,
                         'total_net_loss', round(abs(v_total_loss), 2), 'window_days', 30))
    RETURNING id INTO v_pattern_id;
    RETURN v_pattern_id;
  END IF;
  RETURN NULL;
END; $$;


ALTER FUNCTION public.detect_cross_casino_chasing(p_grpi_id uuid) OWNER TO postgres;

--
-- Name: detect_late_night_activity(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detect_late_night_activity(p_grpi_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_late_sess    INTEGER := 0;
  v_late_events  INTEGER := 0;
  v_total_late   INTEGER := 0;
  v_severity     TEXT;
  v_score        NUMERIC;
  v_pattern_id   UUID;
  v_casino_id    UUID;
BEGIN
  DELETE FROM behavioural_patterns WHERE grpi_id = p_grpi_id AND pattern_type = 'late_night_gambling';

  SELECT count(*) INTO v_late_sess FROM player_sessions
  WHERE grpi_id = p_grpi_id AND is_late_night = true
    AND session_start >= now() - '30 days'::interval;

  SELECT count(*) INTO v_late_events FROM behavioural_events
  WHERE grpi_id = p_grpi_id
    AND event_type IN ('session_start','bet','deposit')
    AND extract(hour FROM occurred_at) < 5
    AND occurred_at >= now() - '30 days'::interval;

  v_total_late := greatest(v_late_sess, v_late_events);

  IF v_total_late >= 3 THEN
    v_score    := LEAST(30.0 + v_total_late * 7.0, 100.0);
    v_severity := CASE WHEN v_score >= 80 THEN 'critical' WHEN v_score >= 60 THEN 'high'
                       WHEN v_score >= 44 THEN 'medium' ELSE 'low' END;
    SELECT casino_id INTO v_casino_id FROM player_sessions WHERE grpi_id = p_grpi_id ORDER BY session_start DESC LIMIT 1;
    INSERT INTO behavioural_patterns (grpi_id, primary_casino_id, pattern_type, severity, score, evidence)
    VALUES (p_grpi_id, v_casino_id, 'late_night_gambling', v_severity, v_score,
      jsonb_build_object('late_night_sessions', v_late_sess, 'late_night_events', v_late_events,
                         'threshold_hour', 5, 'window_days', 30))
    RETURNING id INTO v_pattern_id;
    RETURN v_pattern_id;
  END IF;
  RETURN NULL;
END; $$;


ALTER FUNCTION public.detect_late_night_activity(p_grpi_id uuid) OWNER TO postgres;

--
-- Name: detect_loss_chasing(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detect_loss_chasing(p_grpi_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_prev_wagered  NUMERIC  := 0;
  v_consec        INTEGER  := 0;
  v_max_consec    INTEGER  := 0;
  v_escalations   INTEGER  := 0;
  v_total_sess    INTEGER  := 0;
  v_sess          RECORD;
  v_severity      TEXT;
  v_score         NUMERIC;
  v_pattern_id    UUID;
  v_casino_id     UUID;
BEGIN
  DELETE FROM behavioural_patterns WHERE grpi_id = p_grpi_id AND pattern_type = 'loss_chasing';

  FOR v_sess IN
    SELECT session_start, total_wagered, net_result
    FROM player_sessions
    WHERE grpi_id = p_grpi_id AND session_start >= now() - '30 days'::interval
    ORDER BY session_start ASC
  LOOP
    v_total_sess := v_total_sess + 1;
    IF v_sess.net_result < 0 THEN
      v_consec := v_consec + 1;
      IF v_sess.total_wagered > v_prev_wagered AND v_prev_wagered > 0 THEN
        v_escalations := v_escalations + 1;
      END IF;
    ELSE
      v_max_consec := greatest(v_max_consec, v_consec);
      v_consec := 0;
    END IF;
    v_prev_wagered := v_sess.total_wagered;
  END LOOP;
  v_max_consec := greatest(v_max_consec, v_consec);

  IF v_max_consec >= 3 AND v_escalations >= 2 THEN
    v_score    := LEAST(40.0 + v_max_consec * 8.0 + v_escalations * 5.0, 100.0);
    v_severity := CASE WHEN v_score >= 80 THEN 'critical' WHEN v_score >= 65 THEN 'high' ELSE 'medium' END;
    SELECT casino_id INTO v_casino_id FROM player_sessions WHERE grpi_id = p_grpi_id ORDER BY session_start DESC LIMIT 1;
    INSERT INTO behavioural_patterns (grpi_id, primary_casino_id, pattern_type, severity, score, evidence)
    VALUES (p_grpi_id, v_casino_id, 'loss_chasing', v_severity, v_score,
      jsonb_build_object('max_consecutive_losses', v_max_consec, 'bet_escalations', v_escalations,
                         'sessions_analysed', v_total_sess, 'window_days', 30))
    RETURNING id INTO v_pattern_id;
    RETURN v_pattern_id;
  END IF;
  RETURN NULL;
END; $$;


ALTER FUNCTION public.detect_loss_chasing(p_grpi_id uuid) OWNER TO postgres;

--
-- Name: detect_rapid_deposits(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detect_rapid_deposits(p_grpi_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_rapid_wins   INTEGER := 0;
  v_max_deps     INTEGER := 0;
  v_total_amt    NUMERIC := 0;
  v_severity     TEXT;
  v_score        NUMERIC;
  v_pattern_id   UUID;
  v_casino_id    UUID;
BEGIN
  DELETE FROM behavioural_patterns WHERE grpi_id = p_grpi_id AND pattern_type = 'rapid_deposit';

  SELECT count(*), COALESCE(max(win_count), 0), COALESCE(sum(win_amount), 0)
  INTO v_rapid_wins, v_max_deps, v_total_amt
  FROM (
    SELECT be1.id,
      (SELECT count(*) FROM behavioural_events be2
       WHERE be2.grpi_id = p_grpi_id AND be2.event_type = 'deposit'
         AND be2.occurred_at BETWEEN be1.occurred_at AND be1.occurred_at + '60 minutes'::interval
      ) AS win_count,
      (SELECT COALESCE(sum(amount), 0) FROM behavioural_events be2
       WHERE be2.grpi_id = p_grpi_id AND be2.event_type = 'deposit'
         AND be2.occurred_at BETWEEN be1.occurred_at AND be1.occurred_at + '60 minutes'::interval
      ) AS win_amount
    FROM behavioural_events be1
    WHERE be1.grpi_id = p_grpi_id AND be1.event_type = 'deposit'
      AND be1.occurred_at >= now() - '30 days'::interval
  ) sub WHERE sub.win_count >= 3;

  IF v_rapid_wins >= 1 THEN
    v_score    := LEAST(40.0 + v_rapid_wins * 12.0 + (v_max_deps - 3) * 8.0, 100.0);
    v_severity := CASE WHEN v_score >= 80 THEN 'critical' WHEN v_score >= 65 THEN 'high'
                       WHEN v_score >= 52 THEN 'medium' ELSE 'low' END;
    SELECT casino_id INTO v_casino_id FROM behavioural_events
    WHERE grpi_id = p_grpi_id AND event_type = 'deposit' ORDER BY occurred_at DESC LIMIT 1;
    INSERT INTO behavioural_patterns (grpi_id, primary_casino_id, pattern_type, severity, score, evidence)
    VALUES (p_grpi_id, v_casino_id, 'rapid_deposit', v_severity, v_score,
      jsonb_build_object('rapid_windows', v_rapid_wins, 'max_deposits_per_hour', v_max_deps,
                         'total_deposit_amount', round(v_total_amt, 2), 'window_days', 30))
    RETURNING id INTO v_pattern_id;
    RETURN v_pattern_id;
  END IF;
  RETURN NULL;
END; $$;


ALTER FUNCTION public.detect_rapid_deposits(p_grpi_id uuid) OWNER TO postgres;

--
-- Name: ensure_future_partitions(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ensure_future_partitions(p_months_ahead integer DEFAULT 3) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
v_current_date date := date_trunc('month', now())::date;
v_target_date date;
i int;
BEGIN
FOR i IN 0..p_months_ahead LOOP
v_target_date := v_current_date + (i || ' months')::interval;
PERFORM create_monthly_partition('sessions_archive', 
EXTRACT(year FROM v_target_date)::int,
EXTRACT(month FROM v_target_date)::int);
PERFORM create_monthly_partition('transactions_archive', 
EXTRACT(year FROM v_target_date)::int,
EXTRACT(month FROM v_target_date)::int);
PERFORM create_monthly_partition('behaviour_events_archive', 
EXTRACT(year FROM v_target_date)::int,
EXTRACT(month FROM v_target_date)::int);
END LOOP;
END;
$$;


ALTER FUNCTION public.ensure_future_partitions(p_months_ahead integer) OWNER TO postgres;

