--
-- Name: fn_contact_submission_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_contact_submission_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  _recent_count int;
BEGIN
  -- Rate limit: same email address, last 24 hours
  SELECT COUNT(*) INTO _recent_count
  FROM public.contact_submissions
  WHERE email = NEW.email
    AND created_at > now() - interval '24 hours';

  IF _recent_count >= 3 THEN
    RAISE EXCEPTION 'submission_rate_limited'
      USING HINT = 'Maximum 3 submissions per email per 24 hours',
            ERRCODE = 'P0001';
  END IF;

  -- Sanitise: strip leading/trailing whitespace from text fields
  NEW.name    := trim(NEW.name);
  NEW.message := trim(NEW.message);
  NEW.email   := lower(trim(NEW.email));

  RETURN NEW;
END;
$$;


