-- Name: fn_security_events_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_security_events_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION
    'security_events rows are immutable. '
    'This table is an append-only audit log. '
    'Attempted operation: % on row id=%', TG_OP, OLD.id;
END;
$$;


