--
-- Name: generate_alerts_for_grpi(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_alerts_for_grpi(p_grpi_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_pattern    RECORD;
  v_casino_id  UUID;
  v_prev_score NUMERIC;
  v_new_score  NUMERIC := 0;
  v_patterns   JSONB   := '[]';
  v_desc       TEXT;
BEGIN
  SELECT p.casino_id INTO v_casino_id
  FROM player_identity_map pim
  JOIN players p ON p.id = pim.player_id
  WHERE pim.global_identity_id = p_grpi_id
  ORDER BY p.last_active DESC NULLS LAST LIMIT 1;

  PERFORM detect_loss_chasing(p_grpi_id);
  PERFORM detect_binge_sessions(p_grpi_id);
  PERFORM detect_cross_casino_chasing(p_grpi_id);
  PERFORM detect_late_night_activity(p_grpi_id);
  PERFORM detect_rapid_deposits(p_grpi_id);

  DELETE FROM alerts
  WHERE grpi_id = p_grpi_id AND is_resolved = false
    AND created_at >= now() - '1 day'::interval;

  FOR v_pattern IN
    SELECT id, pattern_type, severity, score, evidence, primary_casino_id
    FROM behavioural_patterns
    WHERE grpi_id = p_grpi_id AND severity IN ('medium','high','critical')
    ORDER BY score DESC
  LOOP
    v_desc := CASE v_pattern.pattern_type
      WHEN 'loss_chasing'         THEN format('Loss-chasing: %s consecutive losing sessions with escalating bets',
                                              v_pattern.evidence->>'max_consecutive_losses')
      WHEN 'binge_session'        THEN format('Binge gambling: up to %s min session; %s binge windows detected',
                                              v_pattern.evidence->>'max_duration_minutes', v_pattern.evidence->>'binge_windows')
      WHEN 'cross_casino_chasing' THEN format('Cross-casino chasing: %s days active at %s+ operators with net losses',
                                              v_pattern.evidence->>'multi_casino_days', v_pattern.evidence->>'max_casinos_per_day')
      WHEN 'late_night_gambling'  THEN format('Late-night gambling: %s sessions after midnight in 30 days',
                                              v_pattern.evidence->>'late_night_sessions')
      WHEN 'rapid_deposit'        THEN format('Rapid deposits: %s instances of 3+ deposits within 60 min',
                                              v_pattern.evidence->>'rapid_windows')
      ELSE v_pattern.pattern_type || ' detected'
    END;

    INSERT INTO alerts (grpi_id, casino_id, pattern_id, alert_type, severity, description)
    VALUES (p_grpi_id,
            COALESCE(v_pattern.primary_casino_id, v_casino_id),
            v_pattern.id, v_pattern.pattern_type, v_pattern.severity, v_desc);

    v_patterns := v_patterns || jsonb_build_object(
      'pattern_type', v_pattern.pattern_type, 'severity', v_pattern.severity, 'score', v_pattern.score);
    IF v_pattern.score > v_new_score THEN v_new_score := v_pattern.score; END IF;
  END LOOP;

  SELECT current_score INTO v_prev_score FROM bie_risk_scores WHERE grpi_id = p_grpi_id;

  INSERT INTO bie_risk_scores (grpi_id, current_score, previous_score, contributing_patterns, last_updated)
  VALUES (p_grpi_id, v_new_score, v_prev_score, v_patterns, now())
  ON CONFLICT (grpi_id) DO UPDATE
    SET current_score         = EXCLUDED.current_score,
        previous_score        = bie_risk_scores.current_score,
        contributing_patterns = EXCLUDED.contributing_patterns,
        last_updated          = now();

  IF v_new_score > 0 THEN
    INSERT INTO grpi_audit_logs (global_identity_id, action, candidate_count, below_threshold, details)
    VALUES (p_grpi_id, 'bie_risk_assessment', jsonb_array_length(v_patterns), false,
            jsonb_build_object('bie_score', v_new_score, 'patterns', v_patterns, 'casino_id', v_casino_id));
  END IF;
END; $$;


ALTER FUNCTION public.generate_alerts_for_grpi(p_grpi_id uuid) OWNER TO postgres;

--
-- Name: generate_certificate_on_pass(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_certificate_on_pass() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_enrollment record; v_module record; v_verification_code text;
BEGIN IF NEW.passed = true AND NEW.score >= 80 THEN
SELECT * INTO v_enrollment FROM training_enrollments WHERE id = NEW.enrollment_id;
SELECT * INTO v_module FROM training_modules WHERE id = v_enrollment.module_id;
v_verification_code := 'CERT-' || UPPER(SUBSTRING(MD5(RANDOM()::text) FROM 1 FOR 8));
INSERT INTO training_certificates (staff_id, module_id, enrollment_id, quiz_attempt_id, certificate_name, issued_date, expiry_date, verification_code, credits_earned)
VALUES (v_enrollment.staff_id, v_enrollment.module_id, NEW.enrollment_id, NEW.id, v_module.title, NOW(),
CASE WHEN v_module.validity_period_months IS NOT NULL THEN NOW() + (v_module.validity_period_months || ' months')::interval ELSE NULL END,
v_verification_code, v_module.credit_hours) ON CONFLICT (enrollment_id) DO NOTHING; END IF; RETURN NEW; END; $$;


ALTER FUNCTION public.generate_certificate_on_pass() OWNER TO postgres;

--
-- Name: generate_grpi(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_grpi(p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_id_number text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_email_hash     TEXT;
  v_phone_hash     TEXT;
  v_id_number_hash TEXT;
  v_lock_key       BIGINT;
  v_lock_hash      TEXT;
  v_identity_id    UUID;
  v_match_count    INTEGER;
  v_candidate      RECORD;
  v_best_score     INTEGER := 0;
  v_best_id        UUID;
BEGIN
  IF p_email IS NULL AND p_phone IS NULL AND p_id_number IS NULL THEN
    RAISE EXCEPTION 'generate_grpi: at least one of email, phone, id_number is required';
  END IF;

  v_email_hash     := CASE WHEN p_email     IS NOT NULL THEN hash_identity(p_email)     ELSE NULL END;
  v_phone_hash     := CASE WHEN p_phone     IS NOT NULL THEN hash_identity(p_phone)     ELSE NULL END;
  v_id_number_hash := CASE WHEN p_id_number IS NOT NULL THEN hash_identity(p_id_number) ELSE NULL END;

  -- 64-bit advisory lock key from SHA-256 (avoids INT4 overflow)
  v_lock_hash := coalesce(v_id_number_hash, v_email_hash, v_phone_hash);
  v_lock_key  := ('x' || substr(v_lock_hash, 1, 16))::bit(64)::bigint;
  PERFORM pg_advisory_xact_lock(v_lock_key);

  FOR v_candidate IN
    SELECT
      id,
      (CASE WHEN v_email_hash       IS NOT NULL AND email_hash     = v_email_hash     THEN 1 ELSE 0 END
       + CASE WHEN v_phone_hash     IS NOT NULL AND phone_hash     = v_phone_hash     THEN 1 ELSE 0 END
       + CASE WHEN v_id_number_hash IS NOT NULL AND id_number_hash = v_id_number_hash THEN 1 ELSE 0 END
      ) AS match_score
    FROM global_identities
    WHERE
      (v_email_hash     IS NOT NULL AND email_hash     = v_email_hash)
      OR (v_phone_hash  IS NOT NULL AND phone_hash     = v_phone_hash)
      OR (v_id_number_hash IS NOT NULL AND id_number_hash = v_id_number_hash)
  LOOP
    IF v_candidate.match_score > v_best_score THEN
      v_best_score := v_candidate.match_score;
      v_best_id    := v_candidate.id;
    END IF;
  END LOOP;

  SELECT count(*) INTO v_match_count
  FROM global_identities
  WHERE
    (v_email_hash     IS NOT NULL AND email_hash     = v_email_hash)
    OR (v_phone_hash  IS NOT NULL AND phone_hash     = v_phone_hash)
    OR (v_id_number_hash IS NOT NULL AND id_number_hash = v_id_number_hash);

  -- Soft-link threshold: score < 2 = new identity + flag for review
  IF v_best_id IS NOT NULL AND v_best_score < 2 THEN
    INSERT INTO grpi_audit_logs (
      global_identity_id, action, match_score, candidate_count, below_threshold, details
    ) VALUES (
      v_best_id, 'grpi_below_threshold_new_identity', v_best_score, v_match_count, true,
      jsonb_build_object('reason', 'Single-signal match insufficient for auto-link',
                         'nearest_match_id', v_best_id, 'nearest_score', v_best_score)
    );
    v_best_id := NULL;
  END IF;

  IF v_best_id IS NOT NULL AND v_match_count > 1 THEN
    INSERT INTO grpi_audit_logs (
      global_identity_id, action, match_score, candidate_count, below_threshold, details
    ) VALUES (
      v_best_id, 'grpi_ambiguous_match', v_best_score, v_match_count, false,
      jsonb_build_object('resolved_id', v_best_id, 'match_count', v_match_count, 'best_score', v_best_score)
    );
    -- Cross-system compliance trace: audit_logs uses `payload` not `details`
    INSERT INTO audit_logs (log_type, payload)
    VALUES (
      'compliance_action',
      jsonb_build_object('action', 'grpi_ambiguous_match', 'match_count', v_match_count,
                         'best_score', v_best_score, 'resolved_id', v_best_id)
    );
  END IF;

  IF v_best_id IS NOT NULL THEN
    UPDATE global_identities
    SET
      email_hash     = coalesce(email_hash,     v_email_hash),
      phone_hash     = coalesce(phone_hash,     v_phone_hash),
      id_number_hash = coalesce(id_number_hash, v_id_number_hash)
    WHERE id = v_best_id;
    RETURN v_best_id;
  END IF;

  INSERT INTO global_identities (email_hash, phone_hash, id_number_hash)
  VALUES (v_email_hash, v_phone_hash, v_id_number_hash)
  RETURNING id INTO v_identity_id;

  INSERT INTO grpi_audit_logs (
    global_identity_id, action, match_score, candidate_count, below_threshold, details
  ) VALUES (v_identity_id, 'grpi_new_identity_created', 0, v_match_count, false, '{}'::jsonb);

  INSERT INTO global_player_metrics (global_identity_id)
  VALUES (v_identity_id)
  ON CONFLICT (global_identity_id) DO NOTHING;

  RETURN v_identity_id;
END;
$$;


ALTER FUNCTION public.generate_grpi(p_email text, p_phone text, p_id_number text) OWNER TO postgres;

--
-- Name: generate_player_id_for_casino(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_player_id_for_casino(p_casino_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
casino_code text;
next_num integer;
new_player_id text;
BEGIN
SELECT 
CASE 
WHEN id = '11111111-1111-1111-1111-111111111111' THEN 'CA1'
WHEN id = '22222222-2222-2222-2222-222222222222' THEN 'CA2'
WHEN id = '33333333-3333-3333-3333-333333333333' THEN 'CA3'
ELSE 'CA' || ROW_NUMBER() OVER (ORDER BY created_at)::text
END INTO casino_code
FROM casinos
WHERE id = p_casino_id;

IF casino_code IS NULL THEN
casino_code := 'CA0';
END IF;

SELECT COALESCE(MAX(
CAST(SUBSTRING(player_id FROM 9) AS integer)
), 0) + 1 INTO next_num
FROM players
WHERE casino_id = p_casino_id
AND player_id LIKE 'SBQ-' || casino_code || '-%';

new_player_id := 'SBQ-' || casino_code || '-' || LPAD(next_num::text, 5, '0');

RETURN new_player_id;
END;
$$;


ALTER FUNCTION public.generate_player_id_for_casino(p_casino_id uuid) OWNER TO postgres;

--
-- Name: get_alerts_by_pattern(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_alerts_by_pattern() RETURNS TABLE(alert_type text, total_alerts bigint, critical_count bigint, high_count bigint, medium_count bigint, avg_score numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT (is_super_admin() OR is_regulator()) THEN
    RAISE EXCEPTION 'get_alerts_by_pattern: insufficient privileges — role: %',
      coalesce(get_user_context()->>'role', 'unknown');
  END IF;
  RAISE NOTICE 'get_alerts_by_pattern: role check passed for %', get_user_context()->>'role';
  RETURN QUERY
  SELECT
    a.alert_type,
    count(*)::BIGINT,
    count(*) FILTER (WHERE a.severity = 'critical')::BIGINT,
    count(*) FILTER (WHERE a.severity = 'high')::BIGINT,
    count(*) FILTER (WHERE a.severity = 'medium')::BIGINT,
    round(COALESCE(avg(bp.score), 0), 1)
  FROM alerts a
  LEFT JOIN behavioural_patterns bp ON bp.id = a.pattern_id
  WHERE a.is_resolved = false
  GROUP BY a.alert_type
  ORDER BY count(*) DESC;
END;
$$;


ALTER FUNCTION public.get_alerts_by_pattern() OWNER TO postgres;

--
-- Name: get_assessment_stats(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_assessment_stats(p_casino_id uuid DEFAULT NULL::uuid) RETURNS TABLE(total_assessments bigint, high_risk_assessments bigint, critical_assessments bigint, avg_nova_iq_score numeric, avg_risk_delta numeric, assessments_last_30_days bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    COUNT(*)::bigint,
    COUNT(*) FILTER (WHERE nova_iq_risk_level = 'high')::bigint,
    COUNT(*) FILTER (WHERE nova_iq_risk_level = 'critical')::bigint,
    ROUND(AVG(nova_iq_risk_score), 1),
    ROUND(AVG(risk_score_delta), 1),
    COUNT(*) FILTER (WHERE completed_at > NOW() - INTERVAL '30 days')::bigint
  FROM wellbeing_assessments
  WHERE (p_casino_id IS NULL OR casino_id = p_casino_id)
    AND completed_at IS NOT NULL;
$$;


