--
-- Name: get_bie_grpi_profiles(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_bie_grpi_profiles(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(grpi_id uuid, bie_score numeric, casino_count bigint, active_patterns bigint, active_alerts bigint, top_pattern text, top_severity text, is_self_excluded boolean, last_activity timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT (is_super_admin() OR is_regulator()) THEN
    RAISE EXCEPTION 'get_bie_grpi_profiles: insufficient privileges — role: %',
      coalesce(get_user_context()->>'role', 'unknown');
  END IF;
  RAISE NOTICE 'get_bie_grpi_profiles: role check passed for %', get_user_context()->>'role';
  RETURN QUERY
  SELECT
    gi.id,
    COALESCE(brs.current_score, 0),
    COALESCE(gpm.casino_count, 1)::BIGINT,
    (SELECT count(*) FROM behavioural_patterns bp WHERE bp.grpi_id = gi.id)::BIGINT,
    (SELECT count(*) FROM alerts a WHERE a.grpi_id = gi.id AND NOT a.is_resolved)::BIGINT,
    (SELECT bp2.pattern_type FROM behavioural_patterns bp2 WHERE bp2.grpi_id = gi.id ORDER BY bp2.score DESC LIMIT 1),
    (SELECT bp3.severity    FROM behavioural_patterns bp3 WHERE bp3.grpi_id = gi.id ORDER BY bp3.score DESC LIMIT 1),
    gi.is_self_excluded,
    gpm.last_activity_at
  FROM global_identities gi
  LEFT JOIN bie_risk_scores       brs ON brs.grpi_id           = gi.id
  LEFT JOIN global_player_metrics gpm ON gpm.global_identity_id = gi.id
  WHERE brs.current_score > 0 OR gi.is_self_excluded
  ORDER BY COALESCE(brs.current_score, 0) DESC
  LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.get_bie_grpi_profiles(p_limit integer, p_offset integer) OWNER TO postgres;

