-- Name: get_casino_modules(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_casino_modules(p_casino_id uuid) RETURNS TABLE(module_id uuid, name text, slug text, description text, category text, enabled_at timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
RETURN QUERY
SELECT 
sm.id,
sm.name,
sm.slug,
sm.description,
sm.category,
cm.enabled_at,
cm.expires_at
FROM casino_modules cm
JOIN software_modules sm ON sm.id = cm.module_id
WHERE cm.casino_id = p_casino_id
AND sm.is_active = true
AND (cm.expires_at IS NULL OR cm.expires_at > now())
ORDER BY sm.category, sm.sort_order, sm.name;
END;
$$;


