--
-- Name: get_casino_training_stats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_casino_training_stats() RETURNS TABLE(casino_id uuid, casino_name text, license_number text, staff_count bigint, total_enrollments bigint, completed_courses bigint, avg_progress numeric, completion_rate numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
RETURN QUERY
SELECT 
c.id AS casino_id,
c.name AS casino_name,
c.license_number,
COUNT(DISTINCT s.id) AS staff_count,
COUNT(te.id) AS total_enrollments,
COUNT(te.id) FILTER (WHERE te.completed_at IS NOT NULL) AS completed_courses,
COALESCE(AVG(te.progress_percentage), 0) AS avg_progress,
CASE 
WHEN COUNT(te.id) > 0 THEN 
(COUNT(te.id) FILTER (WHERE te.completed_at IS NOT NULL)::numeric / COUNT(te.id)::numeric) * 100
ELSE 0
END AS completion_rate
FROM casinos c
LEFT JOIN staff s ON s.casino_id = c.id
LEFT JOIN training_enrollments te ON te.staff_id = s.id
WHERE c.is_active = true
GROUP BY c.id, c.name, c.license_number
ORDER BY c.name;
END;
$$;


ALTER FUNCTION public.get_casino_training_stats() OWNER TO postgres;

--
-- Name: get_cross_operator_metrics(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_cross_operator_metrics() RETURNS TABLE(total_alerts bigint, critical_alerts bigint, exclusion_breaches bigint, avg_cross_operator_score numeric, active_grpis bigint, high_risk_grpis bigint, patterns_detected bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT (is_super_admin() OR is_regulator()) THEN
    RAISE EXCEPTION 'get_cross_operator_metrics: insufficient privileges — role: %',
      coalesce(get_user_context()->>'role', 'unknown');
  END IF;
  RAISE NOTICE 'get_cross_operator_metrics: role check passed for %', get_user_context()->>'role';
  RETURN QUERY SELECT
    (SELECT count(*)                FROM alerts WHERE is_resolved = false)::BIGINT,
    (SELECT count(*)                FROM alerts WHERE severity = 'critical' AND is_resolved = false)::BIGINT,
    (SELECT count(*)                FROM global_identities WHERE is_self_excluded = true)::BIGINT,
    (SELECT round(COALESCE(avg(current_score),0),1) FROM bie_risk_scores WHERE current_score > 0)::NUMERIC,
    (SELECT count(DISTINCT grpi_id) FROM player_sessions)::BIGINT,
    (SELECT count(*)                FROM bie_risk_scores WHERE current_score >= 70)::BIGINT,
    (SELECT count(*)                FROM behavioural_patterns)::BIGINT;
END;
$$;


