--
-- Name: get_grpi_compliance_queue(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_grpi_compliance_queue(p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, global_identity_id uuid, grpi text, action text, match_score integer, candidate_count integer, casino_id uuid, player_id uuid, details jsonb, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT (is_regulator() OR is_super_admin()) THEN
    RAISE EXCEPTION 'get_grpi_compliance_queue: insufficient privileges';
  END IF;

  RETURN QUERY
  SELECT
    gal.id,
    gal.global_identity_id,
    gi.grpi,
    gal.action,
    gal.match_score,
    gal.candidate_count,
    gal.casino_id,
    gal.player_id,
    gal.details,
    gal.created_at
  FROM grpi_audit_logs    gal
  LEFT JOIN global_identities gi ON gi.id = gal.global_identity_id
  WHERE gal.below_threshold = true
  ORDER BY gal.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.get_grpi_compliance_queue(p_limit integer) OWNER TO postgres;

--
-- Name: get_grpi_cross_casino_alerts(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_grpi_cross_casino_alerts(p_limit integer DEFAULT 50) RETURNS TABLE(global_identity_id uuid, grpi text, risk_score numeric, casino_count integer, is_self_excluded boolean, last_activity_at timestamp with time zone, casino_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT (is_regulator() OR is_super_admin()) THEN
    RAISE EXCEPTION 'get_grpi_cross_casino_alerts: insufficient privileges';
  END IF;

  RETURN QUERY
  SELECT
    gpm.global_identity_id,
    gi.grpi,
    gpm.risk_score,
    gpm.casino_count,
    gi.is_self_excluded,
    gpm.last_activity_at,
    array_agg(pim.casino_id ORDER BY pim.linked_at) AS casino_ids
  FROM global_player_metrics gpm
  JOIN global_identities    gi  ON gi.id  = gpm.global_identity_id
  JOIN player_identity_map  pim ON pim.global_identity_id = gpm.global_identity_id
  WHERE gpm.casino_count > 1
  GROUP BY gpm.global_identity_id, gi.grpi, gpm.risk_score,
           gpm.casino_count, gi.is_self_excluded, gpm.last_activity_at
  ORDER BY gpm.casino_count DESC, gpm.risk_score DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.get_grpi_cross_casino_alerts(p_limit integer) OWNER TO postgres;

