--
-- Name: get_rate_limit_analytics(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_rate_limit_analytics(p_casino_id uuid DEFAULT NULL::uuid, p_hours_back integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
v_cutoff timestamptz := now() - (p_hours_back || ' hours')::interval;
BEGIN
RETURN jsonb_build_object(
'total_violations', (
SELECT COUNT(*) FROM rate_limit_violations
WHERE created_at >= v_cutoff
AND (p_casino_id IS NULL OR casino_id = p_casino_id)
),
'violations_by_type', (
SELECT jsonb_object_agg(violation_type, cnt)
FROM (
SELECT violation_type, COUNT(*) AS cnt
FROM rate_limit_violations
WHERE created_at >= v_cutoff
AND (p_casino_id IS NULL OR casino_id = p_casino_id)
GROUP BY violation_type
) t
),
'top_violated_endpoints', (
SELECT jsonb_agg(jsonb_build_object('endpoint', endpoint, 'violations', cnt) ORDER BY cnt DESC)
FROM (
SELECT endpoint, COUNT(*) AS cnt
FROM rate_limit_violations
WHERE created_at >= v_cutoff
AND (p_casino_id IS NULL OR casino_id = p_casino_id)
GROUP BY endpoint
ORDER BY cnt DESC
LIMIT 5
) t
),
'open_circuit_breakers', (
SELECT COUNT(*) FROM circuit_breaker_state
WHERE state = 'open'
AND (p_casino_id IS NULL OR casino_id = p_casino_id)
),
'generated_at', now()
);
END;
$$;


ALTER FUNCTION public.get_rate_limit_analytics(p_casino_id uuid, p_hours_back integer) OWNER TO postgres;

--
-- Name: get_rate_limit_tier(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_rate_limit_tier(p_casino_id uuid, p_endpoint text) RETURNS TABLE(tier_name text, requests_per_minute integer, requests_per_hour integer, burst_limit integer, burst_window_seconds integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
-- Check for endpoint-specific tier first, then fall back to standard
RETURN QUERY
SELECT 
t.tier_name,
t.requests_per_minute,
t.requests_per_hour,
t.burst_limit,
t.burst_window_seconds
FROM rate_limit_tiers t
WHERE t.is_active = true
AND (
p_endpoint = ANY(t.applies_to_endpoints)
OR '*' = ANY(t.applies_to_endpoints)
)
ORDER BY
CASE WHEN p_endpoint = ANY(t.applies_to_endpoints) THEN 0 ELSE 1 END,
t.requests_per_minute DESC
LIMIT 1;
END;
$$;


ALTER FUNCTION public.get_rate_limit_tier(p_casino_id uuid, p_endpoint text) OWNER TO postgres;

