--
-- Name: get_severity_distribution(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_severity_distribution() RETURNS TABLE(severity text, alert_count bigint, grpi_count bigint, pct numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_total BIGINT;
BEGIN
  IF NOT (is_super_admin() OR is_regulator()) THEN
    RAISE EXCEPTION 'get_severity_distribution: insufficient privileges — role: %',
      coalesce(get_user_context()->>'role', 'unknown');
  END IF;
  RAISE NOTICE 'get_severity_distribution: role check passed for %', get_user_context()->>'role';
  SELECT count(*) INTO v_total FROM alerts WHERE is_resolved = false;
  RETURN QUERY
  SELECT
    sev.severity,
    count(a.id)::BIGINT,
    count(DISTINCT a.grpi_id)::BIGINT,
    CASE WHEN v_total > 0 THEN round(count(a.id) * 100.0 / v_total, 1) ELSE 0 END
  FROM (VALUES ('critical'),('high'),('medium'),('low')) AS sev(severity)
  LEFT JOIN alerts a ON a.severity = sev.severity AND a.is_resolved = false
  GROUP BY sev.severity
  ORDER BY CASE sev.severity WHEN 'critical' THEN 1 WHEN 'high' THEN 2 WHEN 'medium' THEN 3 ELSE 4 END;
END;
$$;


ALTER FUNCTION public.get_severity_distribution() OWNER TO postgres;

