--
-- Name: get_user_by_email_fast(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_by_email_fast(p_email text) RETURNS TABLE(id uuid, email text, full_name text, role text, user_role text, casino_id uuid, is_active boolean, source text, force_password_reset boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user RECORD;
BEGIN
  SELECT u.id, u.email, u.full_name, u.role::text, u.casino_id, u.is_active, u.force_password_reset
  INTO v_user
  FROM public.users u
  WHERE u.email = p_email
  LIMIT 1;

  IF FOUND THEN
    RETURN QUERY SELECT
      v_user.id, v_user.email, v_user.full_name, v_user.role,
      NULL::text, v_user.casino_id, v_user.is_active, 'users'::text,
      v_user.force_password_reset;
    RETURN;
  END IF;

  SELECT
    s.id, s.email,
    (s.first_name || ' ' || s.last_name) AS full_name,
    'staff'::text AS role, s.user_role::text,
    s.casino_id, (s.status = 'active') AS is_active
  INTO v_user
  FROM public.staff s
  WHERE s.email = p_email
  LIMIT 1;

  IF FOUND THEN
    RETURN QUERY SELECT
      v_user.id, v_user.email, v_user.full_name, v_user.role,
      v_user.user_role, v_user.casino_id, v_user.is_active, 'staff'::text, false;
    RETURN;
  END IF;
END;
$$;


ALTER FUNCTION public.get_user_by_email_fast(p_email text) OWNER TO postgres;

