--
-- Name: get_user_context(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_context() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
SELECT COALESCE(
  (SELECT jsonb_build_object(
    'user_id',        u.id,
    'role',           u.role::text,
    'casino_id',      u.casino_id,
    'is_super_admin', (u.role = 'super_admin'),
    'is_regulator',   (u.role IN ('regulator', 'national_regulator', 'provincial_regulator')),
    'is_casino_admin',(u.role = 'casino_admin')
  )
  FROM users u
  WHERE u.id = auth.uid()
  LIMIT 1),
  (SELECT jsonb_build_object(
    'user_id',        s.auth_user_id,
    'role',           'staff',
    'casino_id',      s.casino_id,
    'is_super_admin', false,
    'is_regulator',   false,
    'is_casino_admin',false
  )
  FROM staff s
  WHERE s.auth_user_id = auth.uid()
  LIMIT 1),
  jsonb_build_object(
    'user_id',        null,
    'role',           null,
    'casino_id',      null,
    'is_super_admin', false,
    'is_regulator',   false,
    'is_casino_admin',false
  )
);
$$;


ALTER FUNCTION public.get_user_context() OWNER TO postgres;

--
-- Name: FUNCTION get_user_context(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_user_context() IS 'Optimized single-query function to retrieve all user context information. 
Used by other helper functions to avoid multiple table scans. 
Returns JSONB with user_id, role, casino_id, and permission flags.';


