--
-- Name: handle_new_auth_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_auth_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.users (
    id,
    email,
    full_name,
    role,
    casino_id,
    is_active,
    password_hash,
    created_at,
    updated_at
  )
  VALUES (
    new.id,
    new.email,
    COALESCE(
      new.raw_user_meta_data->>'full_name',
      split_part(new.email, '@', 1)
    ),
    COALESCE(
      new.raw_user_meta_data->>'role',
      'casino_admin'
    )::user_role,
    CASE
      WHEN (new.raw_user_meta_data->>'casino_id') IS NOT NULL
        AND (new.raw_user_meta_data->>'casino_id') <> ''
      THEN (new.raw_user_meta_data->>'casino_id')::uuid
      ELSE NULL
    END,
    true,
    -- unusable stub hash — real auth handled by auth.users.encrypted_password
    -- Static non-matchable stub. public.users.password_hash is never
    -- checked during login — auth is handled by auth.users.encrypted_password.
    -- Avoids a pgcrypto dependency (gen_salt not guaranteed in search_path).
    '__no_password_set__',
    now(),
    now()
  )
  ON CONFLICT (id) DO NOTHING;

  RETURN new;
END;
$$;


ALTER FUNCTION public.handle_new_auth_user() OWNER TO postgres;

--
-- Name: hash_identity(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.hash_identity(p_value text) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_pepper TEXT;
BEGIN
  v_pepper := coalesce(
    current_setting('app.settings.grpi_pepper', true),
    'grpi-dev-pepper-change-in-production'
  );
  RETURN encode(
    digest(lower(trim(p_value)) || v_pepper, 'sha256'),
    'hex'
  );
END;
$$;


