--
-- Name: link_player_to_grpi(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.link_player_to_grpi(p_player_id uuid, p_casino_id uuid, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_id_number text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_global_id      UUID;
  v_caller_casino  UUID;
BEGIN
  IF NOT is_super_admin() THEN
    v_caller_casino := get_user_casino_id();
    IF v_caller_casino IS NULL OR v_caller_casino <> p_casino_id THEN
      RAISE EXCEPTION 'link_player_to_grpi: caller casino_id % does not match target casino_id %',
        v_caller_casino, p_casino_id;
    END IF;
  END IF;

  v_global_id := generate_grpi(p_email, p_phone, p_id_number);

  INSERT INTO player_identity_map (player_id, casino_id, global_identity_id, linked_by)
  VALUES (p_player_id, p_casino_id, v_global_id, (SELECT auth.uid()))
  ON CONFLICT (player_id)
    DO UPDATE SET
      global_identity_id = excluded.global_identity_id,
      linked_at          = now(),
      linked_by          = excluded.linked_by;

  INSERT INTO global_player_metrics (global_identity_id)
  VALUES (v_global_id)
  ON CONFLICT (global_identity_id) DO NOTHING;

  UPDATE global_player_metrics
  SET casino_count = (
    SELECT count(DISTINCT casino_id) FROM player_identity_map WHERE global_identity_id = v_global_id
  )
  WHERE global_identity_id = v_global_id;

  -- audit_logs uses `payload` not `details`
  INSERT INTO audit_logs (log_type, player_id, casino_id, payload)
  VALUES (
    'compliance_action', p_player_id, p_casino_id,
    jsonb_build_object('action', 'player_linked_to_grpi', 'global_identity_id', v_global_id)
  );

  INSERT INTO grpi_audit_logs (global_identity_id, action, casino_id, player_id, details)
  VALUES (v_global_id, 'player_linked_to_grpi', p_casino_id, p_player_id, '{}'::jsonb);

  RETURN v_global_id;
END;
$$;


ALTER FUNCTION public.link_player_to_grpi(p_player_id uuid, p_casino_id uuid, p_email text, p_phone text, p_id_number text) OWNER TO postgres;

