CREATE FUNCTION public.log_auth_event(p_user_email text, p_outcome text, p_user_agent text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb, p_user_id uuid DEFAULT NULL::uuid, p_user_role text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.audit_events (
    id, event_id, event_type, event_category,
    user_id, user_email, user_role,
    action, description,
    user_agent, severity, outcome,
    metadata, ntp_timestamp, created_at
  ) VALUES (
    gen_random_uuid(), gen_random_uuid()::text,
    'user_login', 'authentication',
    p_user_id, p_user_email, p_user_role,
    'login',
    CASE p_outcome WHEN 'success' THEN 'User login succeeded' ELSE 'User login failed' END,
    p_user_agent,
    CASE p_outcome WHEN 'success' THEN 'info' ELSE 'warning' END,
    p_outcome, p_metadata, now(), now()
  );
END;
$$;


