--
-- Name: purge_old_ingest_requests(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.purge_old_ingest_requests(retention_days integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  deleted_count INT;
BEGIN
  DELETE FROM public.ingest_requests
  WHERE (
    -- Honour explicit expires_at (key-level TTL)
    expires_at < NOW()
    OR
    -- Hard retention ceiling regardless of expires_at
    created_at < NOW() - (retention_days || ' days')::INTERVAL
  )
  AND status IN ('completed', 'failed');

  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION public.purge_old_ingest_requests(retention_days integer) OWNER TO postgres;

--
-- Name: FUNCTION purge_old_ingest_requests(retention_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.purge_old_ingest_requests(retention_days integer) IS 'Removes completed/failed idempotency records older than retention_days (default 30). Pending rows are never purged to prevent phantom re-processing.';


--
-- Name: recalculate_grpi_risk_score(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recalculate_grpi_risk_score(p_global_identity_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_metrics    RECORD;
  v_loss_ratio NUMERIC;
  v_casino_cmp NUMERIC;
  v_bet_cmp    NUMERIC;
  v_score      NUMERIC;
BEGIN
  SELECT * INTO v_metrics
  FROM global_player_metrics
  WHERE global_identity_id = p_global_identity_id;

  IF NOT FOUND THEN RETURN 0; END IF;

  v_loss_ratio := CASE
    WHEN v_metrics.total_deposits > 0
      THEN least((v_metrics.total_losses / v_metrics.total_deposits) * 100, 100)
    ELSE 0
  END;

  v_casino_cmp := least(v_metrics.casino_count * 20.0, 100);
  v_bet_cmp := least(v_metrics.total_bets / 5.0, 100);

  v_score := (v_loss_ratio * 0.4) + (v_casino_cmp * 0.3) + (v_bet_cmp * 0.3);
  v_score := round(least(greatest(v_score, 0), 100), 2);

  UPDATE global_player_metrics
  SET risk_score = v_score
  WHERE global_identity_id = p_global_identity_id;

  RETURN v_score;
END;
$$;


ALTER FUNCTION public.recalculate_grpi_risk_score(p_global_identity_id uuid) OWNER TO postgres;

