--
-- Name: resolve_player_identity(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_player_identity(p_casino_id uuid, p_ref_hash text, p_safebet_id text) RETURNS TABLE(out_safebet_player_id text, out_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_existing text;
begin
  update safebet_identity_map
     set last_seen_at = now()
   where casino_id = p_casino_id
     and casino_ref_hash = p_ref_hash
  returning safebet_player_id into v_existing;

  if v_existing is not null then
    return query select v_existing, 'existing'::text;
    return;
  end if;

  begin
    insert into safebet_identity_map (casino_id, casino_ref_hash, safebet_player_id)
    values (p_casino_id, p_ref_hash, p_safebet_id);
    return query select p_safebet_id, 'created'::text;
    return;
  exception when unique_violation then
    select safebet_player_id into v_existing
      from safebet_identity_map
     where casino_id = p_casino_id
       and casino_ref_hash = p_ref_hash;

    if v_existing is not null then
      return query select v_existing, 'existing'::text;
      return;
    end if;

    return query select null::text, 'collision'::text;
    return;
  end;
end;
$$;


ALTER FUNCTION public.resolve_player_identity(p_casino_id uuid, p_ref_hash text, p_safebet_id text) OWNER TO postgres;

--
-- Name: rotate_risk_engine_secret(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rotate_risk_engine_secret() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  _active_id  uuid;
  _active_val text;
  _prev_id    uuid;
  _new_secret text;
  _token_id   uuid;
BEGIN
  SELECT s.id, d.decrypted_secret
    INTO _active_id, _active_val
  FROM vault.secrets s
  JOIN vault.decrypted_secrets d ON d.name = s.name
  WHERE s.name = 'risk_engine_hmac_secret'
  LIMIT 1;

  IF _active_val IS NULL THEN
    RAISE EXCEPTION 'Active HMAC secret not found in vault';
  END IF;

  SELECT id INTO _prev_id FROM vault.secrets
  WHERE name = 'risk_engine_hmac_secret_prev' LIMIT 1;

  IF _prev_id IS NULL THEN
    PERFORM vault.create_secret(_active_val, 'risk_engine_hmac_secret_prev',
      'Previous HMAC secret — rotation window slot');
  ELSE
    PERFORM vault.update_secret(_prev_id, _active_val, 'risk_engine_hmac_secret_prev',
      'Previous HMAC secret — rotation window slot');
  END IF;

  _new_secret := encode(gen_random_bytes(32), 'hex');
  PERFORM vault.update_secret(_active_id, _new_secret, 'risk_engine_hmac_secret',
    'HMAC-SHA256 signing secret — active (rotated ' || now()::date::text || ')');

  -- Issue one-time retrieval token instead of returning plaintext
  _token_id := public.issue_secret_retrieval_token('risk_engine_hmac_secret');

  INSERT INTO public.security_rotation_log (event_type, notes)
  VALUES ('secret_rotation',
    'HMAC secret rotated. Token issued for single-use retrieval. ' ||
    'Token expires 15 minutes from: ' || now()::text);

  RAISE NOTICE 'Rotation complete. Retrieve new secret ONCE with: SELECT public.consume_secret_retrieval_token(''%'');', _token_id;

  RETURN _token_id;
END;
$$;


ALTER FUNCTION public.rotate_risk_engine_secret() OWNER TO postgres;

--
-- Name: run_full_detection_scan(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.run_full_detection_scan() RETURNS TABLE(grpi_id uuid, bie_score numeric, patterns_found integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_grpi RECORD;
BEGIN
  IF NOT is_super_admin() THEN
    RAISE EXCEPTION 'run_full_detection_scan: super_admin only';
  END IF;
  FOR v_grpi IN SELECT DISTINCT ps.grpi_id FROM player_sessions ps LOOP
    PERFORM generate_alerts_for_grpi(v_grpi.grpi_id);
  END LOOP;
  RETURN QUERY
    SELECT brs.grpi_id, brs.current_score, jsonb_array_length(brs.contributing_patterns)::INTEGER
    FROM bie_risk_scores brs WHERE brs.current_score > 0 ORDER BY brs.current_score DESC;
END; $$;


ALTER FUNCTION public.run_full_detection_scan() OWNER TO postgres;

--
-- Name: sbiq_activate_policy_set(integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_activate_policy_set(p_version integer, p_actor text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_from integer;
begin
  if not exists (select 1 from policy_sets where version = p_version) then
    raise exception 'policy set version % does not exist', p_version;
  end if;
  select version into v_from from policy_sets where status = 'active';
  update policy_sets set status = 'archived' where status = 'active' and version <> p_version;
  update policy_sets set status = 'active', activated_at = now(), activated_by = p_actor where version = p_version;
  insert into policy_change_log (actor, action, from_version, to_version, reason)
  values (p_actor,
          case when v_from is null then 'seed'
               when p_version < coalesce(v_from, p_version) then 'rollback'
               else 'activate' end,
          v_from, p_version, p_reason);
  return jsonb_build_object('active_version', p_version, 'previous_version', v_from);
end; $$;


ALTER FUNCTION public.sbiq_activate_policy_set(p_version integer, p_actor text, p_reason text) OWNER TO postgres;

--
-- Name: sbiq_active_policy_rules(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_active_policy_rules() RETURNS SETOF jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select r.definition
  from policy_rules r
  join policy_sets s on s.version = r.policy_set_version
  where s.status = 'active'
    and (s.effective_from is null or s.effective_from <= now())
    and (s.effective_to   is null or s.effective_to   >  now())
  order by r.policy_id;
$$;


ALTER FUNCTION public.sbiq_active_policy_rules() OWNER TO postgres;

--
-- Name: sbiq_admin_financial_section(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_admin_financial_section(p_as_of timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  use_rollup boolean := (select value='true' from sbiq_demo_sim_flags where key='ENABLE_FINANCIAL_ROLLUP');
  cp record; v_fin jsonb; lag_s numeric; src_occ timestamptz; src_recv timestamptz; freshness text;
begin
  select last_success_at, last_source_max_received_at, rollup_version, last_failed_at
    into cp from sbiq_financial_rollup_checkpoint where id=1;

  if use_rollup is true then
    select jsonb_build_object(
      'currency', max(financial_currency), 'timezone', max(financial_timezone),
      'ggr_today', coalesce(sum(ggr_today),0), 'ggr_current_shift', coalesce(sum(ggr_current_shift),0),
      'ggr_last_24_hours', coalesce(sum(ggr_last_24_hours),0), 'ggr_month_to_date', coalesce(sum(ggr_month_to_date),0),
      'stakes_today', coalesce(sum(stakes_today),0), 'player_winnings_today', coalesce(sum(player_winnings_today),0),
      'settled_bets_today', coalesce(sum(settled_bets_today),0),
      'status', max(financial_data_status), 'mode', max(financial_data_mode),
      'is_simulated', bool_or(contains_synthetic_data), 'capability_status', max(financial_data_status),
      'snapshot_at', max(financial_snapshot_at),
      'by_casino', (select jsonb_object_agg(casino_id::text, jsonb_build_object('ggr_today',ggr_today,'stakes_today',stakes_today,'winnings_today',player_winnings_today,'status',financial_data_status)) from sbiq_certified_financial_posture_v2(null, p_as_of))
    )
    into v_fin
    from sbiq_certified_financial_posture_v2(null, p_as_of);
    select max(source_max_occurred_at) into src_occ from sbiq_financial_rollup_hourly;
    v_fin := v_fin || jsonb_build_object('source_max_occurred_at', src_occ);
    src_recv := cp.last_source_max_received_at;
    lag_s := round(extract(epoch from now() - coalesce(cp.last_success_at, now())));
    freshness := case when cp.last_success_at is null then 'Unknown'
                      when cp.last_success_at < now() - interval '15 minutes' then 'Stale'
                      when cp.last_success_at < now() - interval '5 minutes' then 'Delayed'
                      else 'Current' end;
    return v_fin || jsonb_build_object('source','rollup','fallback',false,
      'rollup_computed_at', cp.last_success_at, 'source_max_ingested_at', src_recv,
      'rollup_lag_seconds', lag_s, 'rollup_version', cp.rollup_version,
      'freshness', freshness, 'reconciles', true);
  else
    -- Fallback to the certified source view (marked as fallback; not a false Healthy).
    select jsonb_build_object(
      'currency', max(financial_currency), 'timezone', max(financial_timezone),
      'ggr_today', coalesce(sum(ggr_today),0), 'ggr_current_shift', coalesce(sum(ggr_current_shift),0),
      'ggr_last_24_hours', coalesce(sum(ggr_last_24_hours),0), 'ggr_month_to_date', coalesce(sum(ggr_month_to_date),0),
      'stakes_today', coalesce(sum(stakes_today),0), 'player_winnings_today', coalesce(sum(player_winnings_today),0),
      'settled_bets_today', coalesce(sum(settled_bets_today),0),
      'status', max(financial_data_status), 'mode', max(financial_data_mode),
      'is_simulated', bool_or(contains_synthetic_data), 'capability_status', max(financial_data_status),
      'snapshot_at', max(financial_snapshot_at),
      'by_casino', (select jsonb_object_agg(casino_id::text, jsonb_build_object('ggr_today',ggr_today,'stakes_today',stakes_today,'winnings_today',player_winnings_today,'status',financial_data_status)) from projection_financial_posture)
    ) into v_fin from projection_financial_posture;
    return v_fin || jsonb_build_object('source','fallback_certified_view','fallback',true,'freshness','Current','reconciles',true,
      'fallback_reason','ENABLE_FINANCIAL_ROLLUP=false');
  end if;
end; $$;


ALTER FUNCTION public.sbiq_admin_financial_section(p_as_of timestamp with time zone) OWNER TO postgres;

--
-- Name: sbiq_admin_overview_snapshot(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_admin_overview_snapshot(p_include_financial boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  prod constant text := 'safebet-demo-live-simulator-v2';
  now_ts timestamptz := now();
  day_warn numeric := sbiq_demo_limit('SIM_EVENTS_PER_DAY_WARNING');
  day_hard numeric := sbiq_demo_limit('SIM_EVENTS_PER_DAY_HARDSTOP');
  late_min int := coalesce(sbiq_demo_limit('LATE_TICK_MINUTES')::int, 8);
  v_platform jsonb; v_risk jsonb; v_gov jsonb; v_sim jsonb; v_alerts jsonb; v_casinos jsonb;
  v_financial jsonb := null; v_run record; sim_enabled boolean; events_today int;
  chains_total int := 7; chains_ok int; open_ct int; crit_ct int; warn_ct int;
  reg_stale boolean;
begin
  -- Refresh the registered cache only if empty or stale (>6h) — static population.
  select bool_or(refreshed_at < now_ts - interval '6 hours') or count(*)=0 into reg_stale
    from sbiq_admin_registered_counts;
  if reg_stale is not false then perform public.sbiq_admin_refresh_registered(); end if;

  -- projection_casino_state ONCE (certified per-casino metrics).
  drop table if exists _ov;
  create temporary table _ov on commit drop as
    select cs.*, rc.registered, c.name casino_name, c.province, c.license_number, c.is_active
    from projection_casino_state cs
    join casinos c on c.id = cs.casino_id
    left join sbiq_admin_registered_counts rc on rc.casino_id = cs.casino_id;

  -- Simulator summary (cheap; producer index makes events_today fast).
  select value='true' from sbiq_demo_sim_flags where key='ENABLE_DEMO_LIVE_SIMULATOR' into sim_enabled;
  events_today := (select count(*) from casino_event_log where producer=prod and occurred_at >= date_trunc('day', now_ts));
  select max(finished_at) filter (where outcome='ok') last_ok into v_run from sbiq_demo_sim_run_log;

  -- Governance: audit chains (bounded), alerts, partitions, projection freshness.
  chains_ok := (select count(*) from (values
    ('a1b2c3d4-0000-0000-0000-000000000001'),('cc000001-0000-0000-0000-000000000001'),
    ('cc000002-0000-0000-0000-000000000002'),('cc000003-0000-0000-0000-000000000003'),
    ('cc000004-0000-0000-0000-000000000004'),('cc000005-0000-0000-0000-000000000005'),('platform')) v(s)
    where (sbiq_verify_audit_chain(s)->>'status')='verified');
  open_ct := (select count(*) from sbiq_demo_sim_alerts where not resolved);
  crit_ct := (select count(*) from sbiq_demo_sim_alerts where not resolved and severity='critical');
  warn_ct := (select count(*) from sbiq_demo_sim_alerts where not resolved and severity='warning');

  v_platform := (select jsonb_build_object(
    'status', case when chains_ok=chains_total and bool_and(active_players=players_active_now+players_idle+players_stale) then 'Healthy' else 'Attention' end,
    'casinos_monitored', count(*),
    'regulators', 1,
    'platform_users', (select count(*) from public.users),
    'registered_players', coalesce(sum(registered),0),
    'observed_players', coalesce(sum(active_players),0),
    'active_now', coalesce(sum(players_active_now),0),
    'idle', coalesce(sum(players_idle),0),
    'stale', coalesce(sum(players_stale),0),
    'open_sessions', coalesce(sum(open_sessions),0),
    'registered_endpoints', coalesce(sum(registered_machines),0),
    'endpoints_in_play', coalesce(sum(machines_in_play),0),
    'endpoints_stale', coalesce(sum(machines_stale),0)
  ) from _ov);

  v_risk := (select jsonb_build_object(
    'critical', coalesce(sum(risk_critical),0), 'high', coalesce(sum(risk_high),0),
    'medium', coalesce(sum(risk_medium),0), 'low', coalesce(sum(risk_low),0),
    'unclassified', coalesce(sum(risk_unclassified),0),
    'reconciles', bool_and(active_players = risk_critical+risk_high+risk_medium+risk_low+coalesce(risk_unclassified,0))
  ) from _ov);

  v_gov := jsonb_build_object(
    'audit_chains_total', chains_total, 'audit_chains_verified', chains_ok,
    'open_integrity_alerts', open_ct,
    'projection_status', 'Current',
    'partition_status', case when (public.sbiq_demo_partition_readiness(false)->>'ok')::boolean then 'Ready' else 'Attention' end);

  v_sim := jsonb_build_object(
    'status', case when sim_enabled is not true then 'Disabled'
                   when v_run.last_ok is null then 'Unknown'
                   when v_run.last_ok < now_ts - make_interval(mins=>late_min) then 'Warning'
                   else 'Healthy' end,
    'enabled', coalesce(sim_enabled,false), 'last_successful_tick', v_run.last_ok,
    'events_today', events_today, 'daily_warning_limit', day_warn, 'daily_hard_limit', day_hard);

  v_alerts := jsonb_build_object('open', open_ct, 'critical', crit_ct, 'warning', warn_ct);

  v_casinos := (select coalesce(jsonb_agg(row_to_json(x) order by x.casino_name),'[]'::jsonb) from (
    select casino_id, casino_name, province, license_number, is_active,
      registered as registered_players, active_players as observed_players,
      players_active_now as active_now, players_idle as idle, players_stale as stale,
      open_sessions, active_machines as allocated_endpoints, machines_in_play as endpoints_in_play,
      case when players_active_now=0 then 'Attention'
           when active_players is distinct from (players_active_now+players_idle+players_stale) then 'Attention'
           else 'Healthy' end as health
    from _ov) x);

  -- Financial is OPTIONAL (projection_financial_posture ~5s over 130k events).
  if p_include_financial then
    v_financial := (select jsonb_build_object(
      'currency', max(financial_currency), 'timezone', max(financial_timezone),
      'ggr_today', coalesce(sum(ggr_today),0), 'stakes_today', coalesce(sum(stakes_today),0),
      'player_winnings_today', coalesce(sum(player_winnings_today),0),
      'status', max(financial_data_status), 'mode', max(financial_data_mode),
      'is_simulated', bool_or(contains_synthetic_data),
      'snapshot_at', max(financial_snapshot_at),
      'by_casino', (select jsonb_object_agg(casino_id::text, ggr_today) from projection_financial_posture)
    ) from projection_financial_posture);
  end if;

  return jsonb_build_object(
    'schema_version', 'admin-overview-v1', 'as_of', now_ts,
    'environment', jsonb_build_object('name','demo','non_production',true,'synthetic_data',true),
    'platform', v_platform, 'risk', v_risk, 'governance', v_gov, 'simulator', v_sim,
    'alerts', v_alerts, 'casinos', v_casinos, 'financial', v_financial);
end; $$;


ALTER FUNCTION public.sbiq_admin_overview_snapshot(p_include_financial boolean) OWNER TO postgres;

--
-- Name: sbiq_admin_refresh_registered(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_admin_refresh_registered() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n int; t0 timestamptz := clock_timestamp(); as_of timestamptz := now();
begin
  insert into sbiq_admin_registered_counts(casino_id, registered, refreshed_at, source_as_of, last_refresh_duration_ms, last_refresh_status)
  select casino_id, count(*), now(), as_of, 0, 'ok' from projection_player_state group by casino_id
  on conflict (casino_id) do update set registered=excluded.registered, refreshed_at=now(),
    source_as_of=as_of, last_refresh_status='ok', last_refresh_error=null;
  get diagnostics n = row_count;
  update sbiq_admin_registered_counts set last_refresh_duration_ms = extract(ms from clock_timestamp()-t0)::int
    where casino_id is not null;
  return n;
exception when others then
  update sbiq_admin_registered_counts set last_refresh_status='error', last_refresh_error=sqlstate
    where casino_id is not null;
  return -1;
end; $$;


ALTER FUNCTION public.sbiq_admin_refresh_registered() OWNER TO postgres;

--
-- Name: sbiq_admin_refresh_registered_manual(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_admin_refresh_registered_manual(p_account uuid DEFAULT NULL::uuid, p_correlation uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare last_at timestamptz; n int;
begin
  if not pg_try_advisory_xact_lock(hashtext('sbiq_admin_refresh_registered_manual')) then
    return jsonb_build_object('ok', false, 'reason','locked');
  end if;
  select max(created_at) into last_at from sbiq_admin_registered_refresh_log where decision='accepted';
  if last_at is not null and last_at > now() - interval '30 seconds' then
    insert into sbiq_admin_registered_refresh_log(account_id,correlation_id,decision) values (p_account,p_correlation,'rate_limited');
    return jsonb_build_object('ok', true, 'reason','rate_limited', 'refreshed_at', (select max(refreshed_at) from sbiq_admin_registered_counts));
  end if;
  n := public.sbiq_admin_refresh_registered();
  insert into sbiq_admin_registered_refresh_log(account_id,correlation_id,decision) values (p_account,p_correlation,'accepted');
  return jsonb_build_object('ok', true, 'reason','accepted', 'casinos', n, 'status', (select public.sbiq_admin_registered_status()));
end; $$;


ALTER FUNCTION public.sbiq_admin_refresh_registered_manual(p_account uuid, p_correlation uuid) OWNER TO postgres;

--
-- Name: sbiq_admin_registered_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_admin_registered_status() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'registered_count_total', coalesce(sum(registered),0),
    'registered_count_by_casino', (select jsonb_object_agg(casino_id::text, registered) from sbiq_admin_registered_counts),
    'refreshed_at', max(refreshed_at), 'source_as_of', max(source_as_of),
    'age_seconds', round(extract(epoch from now()-max(refreshed_at)))::int,
    'stale_after_seconds', 21600,
    'is_stale', (max(refreshed_at) < now() - interval '6 hours'),
    'last_refresh_duration_ms', max(last_refresh_duration_ms),
    'last_refresh_status', max(last_refresh_status),
    'last_refresh_error_category', max(last_refresh_error))
  from sbiq_admin_registered_counts;
$$;


ALTER FUNCTION public.sbiq_admin_registered_status() OWNER TO postgres;

--
-- Name: sbiq_archive_event_partitions_before(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_archive_event_partitions_before(p_cutoff date) RETURNS SETOF text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  part text; bound text; m_start date;
begin
  for part in
    select c.relname from pg_inherits i
    join pg_class c on c.oid = i.inhrelid
    join pg_class p on p.oid = i.inhparent
    where p.relname = 'casino_event_log'
  loop
    bound := pg_get_expr((select relpartbound from pg_class where relname = part),
                         (select oid from pg_class where relname = part));
    m_start := (substring(bound from 'FROM \(''([0-9-]+)'))::date;
    if m_start < date_trunc('month', p_cutoff) then
      execute format('alter table casino_event_log detach partition %I', part);
      execute format('alter table %I rename to %I', part, 'archive_' || part);
      return next 'archive_' || part;
    end if;
  end loop;
end; $$;


ALTER FUNCTION public.sbiq_archive_event_partitions_before(p_cutoff date) OWNER TO postgres;

--
-- Name: sbiq_audit_benchmark(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_audit_benchmark(p_n integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
declare i int; v_prev text := repeat('0',64); v_hash text; t0 timestamptz; build_ms int; verify_ms int; v_seq int; ok boolean := true; r record;
begin
  create temp table _bench(seq bigint, prev text, hash text, event_id text, created timestamptz, metadata jsonb) on commit drop;
  t0 := clock_timestamp();
  for i in 1..p_n loop
    v_hash := sbiq_audit_event_hash('v1','bench',i,v_prev,'evt-'||i,'BENCH','system','','','','','success', now(), '', jsonb_build_object('i',i));
    insert into _bench values (i, v_prev, v_hash, 'evt-'||i, now(), jsonb_build_object('i',i));
    v_prev := v_hash;
  end loop;
  build_ms := round(extract(milliseconds from clock_timestamp()-t0));
  t0 := clock_timestamp(); v_prev := repeat('0',64); v_seq := 0;
  for r in select * from _bench order by seq loop
    v_seq := v_seq+1;
    if r.prev <> v_prev then ok := false; exit; end if;
    if r.hash <> sbiq_audit_event_hash('v1','bench',r.seq,r.prev,r.event_id,'BENCH','system','','','','','success', r.created, '', r.metadata) then ok := false; exit; end if;
    v_prev := r.hash;
  end loop;
  verify_ms := round(extract(milliseconds from clock_timestamp()-t0));
  return jsonb_build_object('events',p_n,'build_ms',build_ms,'verify_ms',verify_ms,'verified',ok,'verify_us_per_event', round((verify_ms*1000.0)/p_n,1));
end $$;


ALTER FUNCTION public.sbiq_audit_benchmark(p_n integer) OWNER TO postgres;

--
-- Name: sbiq_audit_chain_backfill(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_audit_chain_backfill() RETURNS TABLE(scope text, chained bigint, head text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare r record; v_scope text; v_seq bigint; v_prev text; v_hash text;
begin
  perform set_config('sbiq.audit_breakglass', 'on', true);
  delete from audit_chain_head;
  for v_scope in select distinct coalesce(casino_id::text,'platform') from audit_events order by 1 loop
    v_seq := 0; v_prev := repeat('0',64);
    for r in select * from audit_events where coalesce(casino_id::text,'platform') = v_scope
             order by created_at asc, event_id asc loop
      v_seq := v_seq + 1;
      v_hash := sbiq_audit_event_hash('v1', v_scope, v_seq, v_prev, r.event_id, r.event_type,
        r.user_id::text, r.user_role, r.casino_id::text, r.resource_type, r.resource_id,
        r.outcome, r.created_at, r.correlation_id, r.metadata);
      update audit_events set chain_scope=v_scope, chain_sequence=v_seq, previous_hash=v_prev, hash=v_hash where id = r.id;
      v_prev := v_hash;
    end loop;
    insert into audit_chain_head(chain_scope, chain_sequence, head_hash, schema_version, updated_at)
      values (v_scope, v_seq, v_prev, 'v1', now())
      on conflict (chain_scope) do update set chain_sequence=excluded.chain_sequence, head_hash=excluded.head_hash, updated_at=now();
    scope := v_scope; chained := v_seq; head := v_prev; return next;
  end loop;
end $$;


ALTER FUNCTION public.sbiq_audit_chain_backfill() OWNER TO postgres;

--
-- Name: sbiq_audit_chain_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_audit_chain_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_scope text; v_seq bigint; v_prev text; v_hash text;
begin
  if exists (select 1 from audit_events where event_id = NEW.event_id) then return null; end if;
  v_scope := coalesce(NEW.casino_id::text, 'platform');
  perform pg_advisory_xact_lock(hashtext('audit_chain:'||v_scope));
  select chain_sequence, head_hash into v_seq, v_prev from audit_chain_head where chain_scope = v_scope for update;
  if not found then v_seq := 0; v_prev := repeat('0',64); end if;
  v_seq := v_seq + 1;
  if NEW.created_at is null then NEW.created_at := now(); end if;
  if NEW.ntp_timestamp is null then NEW.ntp_timestamp := now(); end if;
  NEW.chain_scope := v_scope; NEW.chain_sequence := v_seq; NEW.previous_hash := v_prev;
  v_hash := sbiq_audit_event_hash('v1', v_scope, v_seq, v_prev, NEW.event_id, NEW.event_type,
    NEW.user_id::text, NEW.user_role, NEW.casino_id::text, NEW.resource_type, NEW.resource_id,
    NEW.outcome, NEW.created_at, NEW.correlation_id, NEW.metadata);
  NEW.hash := v_hash;
  insert into audit_chain_head (chain_scope, chain_sequence, head_hash, last_event_id, last_event_at, schema_version, updated_at)
    values (v_scope, v_seq, v_hash, NEW.event_id, NEW.created_at, 'v1', now())
    on conflict (chain_scope) do update set chain_sequence=excluded.chain_sequence, head_hash=excluded.head_hash,
      last_event_id=excluded.last_event_id, last_event_at=excluded.last_event_at, updated_at=now();
  return NEW;
end $$;


ALTER FUNCTION public.sbiq_audit_chain_insert() OWNER TO postgres;

--
-- Name: sbiq_audit_config_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_audit_config_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into audit_events (
    event_id, event_type, event_category, action, resource_type, resource_id,
    casino_id, description, old_value, new_value, severity, outcome, metadata)
  values (
    'cfg:'||TG_TABLE_NAME||':'||gen_random_uuid()::text,
    upper(TG_TABLE_NAME)||'_'||TG_OP,
    'governance', lower(TG_OP), TG_TABLE_NAME,
    coalesce(NEW.casino_id::text, 'platform'), NEW.casino_id,
    TG_TABLE_NAME||' '||lower(TG_OP),
    case when TG_OP='UPDATE' then to_jsonb(OLD) else null end,
    to_jsonb(NEW), 'info', 'success',
    jsonb_build_object('table', TG_TABLE_NAME, 'scope', NEW.scope));
  return NEW;
end $$;


ALTER FUNCTION public.sbiq_audit_config_change() OWNER TO postgres;

--
-- Name: sbiq_audit_event_hash(text, text, bigint, text, text, text, text, text, text, text, text, text, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_audit_event_hash(p_schema text, p_scope text, p_seq bigint, p_prev text, p_event_id text, p_event_type text, p_user_id text, p_user_role text, p_casino text, p_res_type text, p_res_id text, p_outcome text, p_created timestamp with time zone, p_corr text, p_metadata jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select encode(digest(array_to_string(array[
    p_schema, p_scope, p_seq::text, p_prev, p_event_id, p_event_type,
    coalesce(p_user_id,'system'), coalesce(p_user_role,''), coalesce(p_casino,''),
    coalesce(p_res_type,''), coalesce(p_res_id,''), coalesce(p_outcome,''),
    to_char(p_created at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    coalesce(p_corr,''),
    encode(digest(sbiq_canonical_json(coalesce(p_metadata,'{}'::jsonb)),'sha256'),'hex')
  ], chr(31)), 'sha256'),'hex');
$$;


ALTER FUNCTION public.sbiq_audit_event_hash(p_schema text, p_scope text, p_seq bigint, p_prev text, p_event_id text, p_event_type text, p_user_id text, p_user_role text, p_casino text, p_res_type text, p_res_id text, p_outcome text, p_created timestamp with time zone, p_corr text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: sbiq_audit_events_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_audit_events_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(current_setting('sbiq.audit_breakglass', true), '') = 'on'
     and current_user in ('postgres','service_role','supabase_admin','supabase_storage_admin') then
    return case when TG_OP = 'DELETE' then OLD else NEW end;
  end if;
  raise exception 'audit_events is append-only (op %, event %)', TG_OP, coalesce(OLD.event_id, NEW.event_id)
    using errcode = 'check_violation';
end $$;


ALTER FUNCTION public.sbiq_audit_events_immutable() OWNER TO postgres;

--
-- Name: sbiq_b10_record_follow_up_occurrence(uuid, uuid, uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_b10_record_follow_up_occurrence(p_intervention_id uuid, p_casino_id uuid, p_actor_id uuid, p_idempotency_key uuid, p_occurred_on date) RETURNS TABLE(status text, occurrence_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_role         text;
  v_actor_casino uuid;
  v_player       uuid;
  v_follow_req   boolean;
  v_follow_date  date;
  v_iv_sast      date;
  v_today        date;
  v_fp           text;
  v_id           uuid;
  v_existing     public.intervention_follow_up_events%rowtype;
begin
  if p_idempotency_key is null then raise exception 'B10: idempotency key required'; end if;
  if p_occurred_on is null     then raise exception 'B10: occurred_on required'; end if;

  -- Actor (defence-in-depth; server already authorised). Role from authoritative users.
  select u.role::text, u.casino_id into v_role, v_actor_casino from public.users u where u.id = p_actor_id;
  if v_role is null then raise exception 'B10: actor not found'; end if;
  if v_role not in ('casino_admin','compliance_officer','super_admin') then
    raise exception 'B10: actor role % not permitted', v_role;
  end if;
  if v_role in ('casino_admin','compliance_officer') and v_actor_casino is distinct from p_casino_id then
    raise exception 'B10: actor not governed for casino';
  end if;

  -- Immutable canonical fingerprint of the ORIGINAL logical request (DB-computed; never a
  -- caller argument). Excludes DB state/provenance (schedule, requirement, recorded_at, id)
  -- so a genuine retry stays replayable after later B8 / eligibility changes.
  v_fp := encode(extensions.digest(convert_to(
    'b10v1' || chr(31) || p_casino_id::text || chr(31) || p_intervention_id::text
            || chr(31) || p_actor_id::text || chr(31) || p_occurred_on::text,
    'UTF8'), 'sha256'), 'hex');

  -- Existing idempotency key? Replay/conflict resolve by the IMMUTABLE fingerprint and do
  -- NOT re-evaluate current eligibility (a later legitimate B8/eligibility change must not
  -- break a genuine retry). Current actor authorisation was already enforced above.
  select * into v_existing from public.intervention_follow_up_events
    where casino_id = p_casino_id and b10_idempotency_key = p_idempotency_key;
  if found then
    if v_existing.b10_request_fingerprint is distinct from v_fp then
      return query select 'IDEMPOTENCY_CONFLICT'::text, null::uuid; return;
    end if;
    return query select 'REPLAYED'::text, v_existing.id; return;
  end if;

  -- NEW occurrence: resolve the governed intervention with a share lock so eligibility +
  -- schedule snapshot are consistent against a concurrent B8 UPDATE (which needs a
  -- conflicting row lock and therefore serialises after this transaction).
  select i.player_id, i.follow_up_required, i.follow_up_date,
         (i.intervention_date at time zone 'Africa/Johannesburg')::date
    into v_player, v_follow_req, v_follow_date, v_iv_sast
    from public.player_protection_interventions i
    where i.id = p_intervention_id and i.casino_id = p_casino_id
    for share;
  if not found then
    return query select 'NOT_FOUND'::text, null::uuid; return;
  end if;

  -- Eligibility: a required (scheduled OR unscheduled) follow-up may occur. Never mutate it.
  if v_follow_req is not true then
    return query select 'INVALID_STATE'::text, null::uuid; return;
  end if;

  -- occurred_on bounds (SAST): between the intervention's SAST date and today; no invented
  -- retrospective threshold. Future is also defended here (route rejects it as 400 first).
  v_today := (now() at time zone 'Africa/Johannesburg')::date;
  if p_occurred_on > v_today or p_occurred_on < v_iv_sast then
    return query select 'INVALID_STATE'::text, null::uuid; return;
  end if;

  -- Race-safe first-writer append. scheduled_follow_up_date is the immutable snapshot.
  insert into public.intervention_follow_up_events (
    casino_id, intervention_id, player_id, scheduled_follow_up_date, occurred_on,
    recorded_at, recorded_by, b10_idempotency_key, b10_request_fingerprint)
  values (
    p_casino_id, p_intervention_id, v_player, v_follow_date, p_occurred_on,
    now(), p_actor_id, p_idempotency_key, v_fp)
  on conflict (casino_id, b10_idempotency_key) do nothing
  returning id into v_id;

  if v_id is not null then
    -- Same-transaction audit (trg_audit_chain hashes it; failure rolls the occurrence back).
    -- Safe structured metadata only — no PII, no recorded_by, no key, no fingerprint.
    insert into public.audit_events (
      event_id, event_type, event_category, action, resource_type, resource_id,
      user_id, user_role, casino_id, severity, outcome, metadata)
    values (
      'b10:intervention.follow_up_recorded:' || v_id::text,
      'intervention.follow_up_recorded', 'responsible_gambling', 'intervention.follow_up_recorded',
      'intervention_follow_up_event', v_id::text, p_actor_id, v_role, p_casino_id, 'info', 'success',
      jsonb_build_object(
        'intervention_id', p_intervention_id,
        'scheduled_date_present', (v_follow_date is not null),
        'timing_classification',
          case when v_follow_date is null       then 'NOT_APPLICABLE'
               when p_occurred_on < v_follow_date then 'EARLY'
               when p_occurred_on = v_follow_date then 'ON_DATE'
               else 'LATE' end,
        'occurred_on', p_occurred_on));
    return query select 'CREATED'::text, v_id; return;
  end if;

  -- Lost the insert race to a concurrent identical key: load the winner, equality by the
  -- IMMUTABLE fingerprint. Uniqueness — not the pre-read — is the concurrency authority.
  select * into v_existing from public.intervention_follow_up_events
    where casino_id = p_casino_id and b10_idempotency_key = p_idempotency_key;
  if not found then raise exception 'B10: idempotency conflict resolution failed'; end if;
  if v_existing.b10_request_fingerprint is distinct from v_fp then
    return query select 'IDEMPOTENCY_CONFLICT'::text, null::uuid; return;
  end if;
  return query select 'REPLAYED'::text, v_existing.id; return;
end $$;


ALTER FUNCTION public.sbiq_b10_record_follow_up_occurrence(p_intervention_id uuid, p_casino_id uuid, p_actor_id uuid, p_idempotency_key uuid, p_occurred_on date) OWNER TO postgres;

--
-- Name: sbiq_b11_close_follow_up_requirement(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_b11_close_follow_up_requirement(p_intervention_id uuid, p_casino_id uuid, p_actor_id uuid, p_idempotency_key uuid) RETURNS TABLE(status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_role        text;
  v_actor_casino uuid;
  v_req         boolean;
  v_date        date;
  v_event_id    text;
  v_fp          text;
  v_existing_fp text;
begin
  if p_idempotency_key is null then raise exception 'B11: idempotency key required'; end if;

  -- Actor (authoritative; server already authorised). No caller role; no staff mapping.
  select u.role::text, u.casino_id into v_role, v_actor_casino from public.users u where u.id = p_actor_id;
  if v_role is null then raise exception 'B11: actor not found'; end if;
  if v_role not in ('casino_admin','compliance_officer','super_admin') then
    raise exception 'B11: actor role % not permitted', v_role;
  end if;
  if v_role in ('casino_admin','compliance_officer') and v_actor_casino is distinct from p_casino_id then
    raise exception 'B11: actor not governed for casino';
  end if;

  -- Deterministic durable idempotency identity (casino + key; intervention-independent so a
  -- key reused for a different intervention collides and is resolved by fingerprint).
  v_event_id := 'b11:follow-up-close:' || p_casino_id::text || ':' || p_idempotency_key::text;

  -- Immutable canonical fingerprint of the ORIGINAL request only (DB-computed; never caller
  -- input; excludes mutable DB state so a genuine retry stays replayable).
  v_fp := encode(extensions.digest(convert_to(
    'b11v1' || chr(31) || p_casino_id::text || chr(31) || p_intervention_id::text || chr(31) || p_actor_id::text,
    'UTF8'), 'sha256'), 'hex');

  -- Resolve + LOCK the intervention (serialises against B8 UPDATE and B10 FOR SHARE).
  select i.follow_up_required, i.follow_up_date into v_req, v_date
    from public.player_protection_interventions i
    where i.id = p_intervention_id and i.casino_id = p_casino_id
    for update;
  if not found then
    return query select 'NOT_FOUND'::text; return;
  end if;

  -- Authoritative post-lock durable idempotency lookup. A prior successful CLOSED wrote this
  -- immutable audit row; a concurrent same-intervention winner committed it before we got the
  -- lock — so this read (not current false state) decides REPLAYED vs CONFLICT vs NOOP.
  select ae.metadata->>'request_fingerprint' into v_existing_fp
    from public.audit_events ae where ae.event_id = v_event_id;
  if found then
    if v_existing_fp is not distinct from v_fp then
      return query select 'REPLAYED'::text; return;
    end if;
    return query select 'IDEMPOTENCY_CONFLICT'::text; return;
  end if;

  -- No prior B11 closure for this key. Only a genuine true→false transition writes evidence.
  if v_req is not true then
    return query select 'NOOP'::text; return;     -- already not-required (or null); no audit, key NOT reserved
  end if;

  -- Atomic close + audit in ONE exception-scoped subtransaction: if the audit INSERT hits the
  -- event_id UNIQUE (a cross-intervention same-key simultaneous race), the UPDATE below is
  -- rolled back with the subtransaction, so the losing intervention is left untouched.
  begin
    update public.player_protection_interventions
       set follow_up_required = false, follow_up_date = null
     where id = p_intervention_id and casino_id = p_casino_id;

    insert into public.audit_events (
      event_id, event_type, event_category, action, resource_type, resource_id,
      user_id, user_role, casino_id, severity, outcome, metadata)
    values (
      v_event_id,
      'intervention.follow_up_requirement_closed', 'responsible_gambling', 'intervention.follow_up_requirement_closed',
      'player_protection_intervention', p_intervention_id::text, p_actor_id, v_role, p_casino_id, 'info', 'success',
      jsonb_build_object(
        'old_follow_up_required', true,
        'new_follow_up_required', false,
        'old_follow_up_date', v_date,
        'old_follow_up_date_present', (v_date is not null),
        'new_follow_up_date_present', false,
        'request_fingerprint', v_fp));

    return query select 'CLOSED'::text; return;
  exception when unique_violation then
    -- Lost the deterministic event_id race; this subtransaction's UPDATE is rolled back.
    select ae.metadata->>'request_fingerprint' into v_existing_fp
      from public.audit_events ae where ae.event_id = v_event_id;
    if v_existing_fp is not distinct from v_fp then
      return query select 'REPLAYED'::text; return;
    end if;
    return query select 'IDEMPOTENCY_CONFLICT'::text; return;
  end;
end $$;


ALTER FUNCTION public.sbiq_b11_close_follow_up_requirement(p_intervention_id uuid, p_casino_id uuid, p_actor_id uuid, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: sbiq_b12_mark_operator_notification_read(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_b12_mark_operator_notification_read(p_casino_id uuid, p_actor_id uuid, p_notification_id text) RETURNS TABLE(status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_role         text;
  v_actor_casino uuid;
  v_id           text;
begin
  if p_notification_id is null or p_notification_id !~ '^[0-9a-f]{64}$' then
    raise exception 'B12: invalid notification id';
  end if;

  -- Actor (defence-in-depth; the server already authorised). Role from authoritative users.
  select u.role::text, u.casino_id into v_role, v_actor_casino from public.users u where u.id = p_actor_id;
  if v_role is null then raise exception 'B12: actor not found'; end if;
  if v_role not in ('casino_admin','compliance_officer','super_admin') then
    raise exception 'B12: actor role % not permitted', v_role;
  end if;
  if v_role in ('casino_admin','compliance_officer') and v_actor_casino is distinct from p_casino_id then
    raise exception 'B12: actor not governed for casino';
  end if;

  insert into public.operator_notification_reads (casino_id, user_id, notification_id)
  values (p_casino_id, p_actor_id, p_notification_id)
  on conflict (casino_id, user_id, notification_id) do nothing
  returning notification_id into v_id;

  if v_id is not null then
    return query select 'READ'::text; return;
  end if;
  return query select 'NOOP'::text; return;   -- already read (first read_at retained)
end $_$;


ALTER FUNCTION public.sbiq_b12_mark_operator_notification_read(p_casino_id uuid, p_actor_id uuid, p_notification_id text) OWNER TO postgres;

--
-- Name: sbiq_b13_begin_player_communication_send(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_b13_begin_player_communication_send(p_casino_id uuid, p_actor_id uuid, p_communication_id uuid, p_send_idempotency_key uuid) RETURNS TABLE(status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_role     text;
  v_actor_casino uuid;
  v_c        public.intervention_player_communications%rowtype;
  v_fp       text;
  v_existing public.intervention_player_communications%rowtype;
  v_con      text;
begin
  if p_send_idempotency_key is null then raise exception 'B13: send idempotency key required'; end if;
  select u.role::text, u.casino_id into v_role, v_actor_casino from public.users u where u.id = p_actor_id;
  if v_role is null then raise exception 'B13: actor not found'; end if;
  if v_role not in ('casino_admin','compliance_officer','super_admin') then raise exception 'B13: actor role % not permitted', v_role; end if;
  if v_role in ('casino_admin','compliance_officer') and v_actor_casino is distinct from p_casino_id then raise exception 'B13: actor not governed for casino'; end if;

  select * into v_c from public.intervention_player_communications
    where id = p_communication_id and casino_id = p_casino_id for update;
  if not found then return query select 'NOT_FOUND'::text; return; end if;

  v_fp := encode(extensions.digest(convert_to(
    'b13-send-v1' || chr(31) || p_casino_id::text || chr(31) || p_communication_id::text || chr(31) || p_actor_id::text || chr(31) || 'SANDBOX',
    'UTF8'), 'sha256'), 'hex');

  -- durable send-key arbitration (post-lock)
  select * into v_existing from public.intervention_player_communications
    where casino_id = p_casino_id and send_idempotency_key = p_send_idempotency_key;
  if found then
    if v_existing.id = p_communication_id and v_existing.send_fingerprint is not distinct from v_fp then
      return query select 'REPLAYED'::text; return;
    end if;
    return query select 'IDEMPOTENCY_CONFLICT'::text; return;
  end if;

  if v_c.status <> 'PENDING' then return query select 'INVALID_STATE'::text; return; end if;
  if v_c.delivery_mode <> 'SANDBOX' then raise exception 'B13: delivery_mode not SANDBOX'; end if;

  begin
    update public.intervention_player_communications
       set status = 'SUBMITTING', send_idempotency_key = p_send_idempotency_key, send_fingerprint = v_fp,
           send_requested_by = p_actor_id, send_requested_at = now()
     where id = p_communication_id and casino_id = p_casino_id;

    insert into public.audit_events (
      event_id, event_type, event_category, action, resource_type, resource_id,
      user_id, user_role, casino_id, severity, outcome, metadata)
    values (
      'b13:player-communication:' || p_communication_id::text || ':send-requested',
      'intervention.player_communication_send_requested', 'responsible_gambling', 'intervention.player_communication_send_requested',
      'intervention_player_communication', p_communication_id::text, p_actor_id, v_role, p_casino_id, 'info', 'success',
      jsonb_build_object('intervention_id', v_c.intervention_id, 'communication_type', v_c.communication_type,
        'purpose', v_c.purpose, 'template_key', v_c.template_key, 'template_version', v_c.template_version,
        'delivery_mode', v_c.delivery_mode, 'channel_class', v_c.channel_class, 'sequence', v_c.sequence, 'sandbox', true));

    return query select 'BEGUN'::text; return;
  exception when unique_violation then
    get stacked diagnostics v_con = constraint_name;
    if v_con = 'iplc_send_idem_uq' then
      select * into v_existing from public.intervention_player_communications
        where casino_id = p_casino_id and send_idempotency_key = p_send_idempotency_key;
      if found and v_existing.id = p_communication_id and v_existing.send_fingerprint is not distinct from v_fp then
        return query select 'REPLAYED'::text; return;
      end if;
      return query select 'IDEMPOTENCY_CONFLICT'::text; return;
    end if;
    raise;   -- any other constraint → fail closed (loser mutation + audit rolled back)
  end;
end $$;


ALTER FUNCTION public.sbiq_b13_begin_player_communication_send(p_casino_id uuid, p_actor_id uuid, p_communication_id uuid, p_send_idempotency_key uuid) OWNER TO postgres;

--
-- Name: sbiq_b13_create_player_communication(uuid, uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_b13_create_player_communication(p_casino_id uuid, p_actor_id uuid, p_intervention_id uuid, p_communication_type text, p_template_key text, p_idempotency_key uuid) RETURNS TABLE(status text, communication_id uuid, sequence integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_role        text;
  v_actor_casino uuid;
  v_iv_casino   uuid;
  v_iv_type     text;
  v_fp          text;
  v_existing    public.intervention_player_communications%rowtype;
  v_seq         integer;
  v_id          uuid;
  v_expected_type text;
  v_expected_key  text;
begin
  if p_idempotency_key is null then raise exception 'B13: idempotency key required'; end if;

  -- actor
  select u.role::text, u.casino_id into v_role, v_actor_casino from public.users u where u.id = p_actor_id;
  if v_role is null then raise exception 'B13: actor not found'; end if;
  if v_role not in ('casino_admin','compliance_officer','super_admin') then raise exception 'B13: actor role % not permitted', v_role; end if;
  if v_role in ('casino_admin','compliance_officer') and v_actor_casino is distinct from p_casino_id then raise exception 'B13: actor not governed for casino'; end if;

  -- resolve + lock intervention; derive casino + type (player identity intentionally NOT stored)
  select i.casino_id, i.intervention_type into v_iv_casino, v_iv_type
    from public.player_protection_interventions i where i.id = p_intervention_id for update;
  if not found or v_iv_casino is distinct from p_casino_id then
    return query select 'NOT_FOUND'::text, null::uuid, null::integer; return;
  end if;

  -- immutable fingerprint of the ORIGINAL request (server-governed version/purpose/mode/channel)
  v_fp := encode(extensions.digest(convert_to(
    'b13-request-v1' || chr(31) || p_casino_id::text || chr(31) || p_intervention_id::text || chr(31) || p_communication_type
      || chr(31) || p_template_key || chr(31) || '1' || chr(31) || 'RESPONSIBLE_GAMBLING' || chr(31) || 'SANDBOX'
      || chr(31) || 'OPERATOR_MANAGED' || chr(31) || p_actor_id::text, 'UTF8'), 'sha256'), 'hex');

  -- replay BEFORE mutable policy rejection (a prior request stays replayable)
  select * into v_existing from public.intervention_player_communications
    where casino_id = p_casino_id and request_idempotency_key = p_idempotency_key;
  if found then
    if v_existing.request_fingerprint is not distinct from v_fp then
      return query select 'REPLAYED'::text, v_existing.id, v_existing.sequence; return;
    end if;
    return query select 'IDEMPOTENCY_CONFLICT'::text, null::uuid, null::integer; return;
  end if;

  -- eligibility + exact type↔communication_type↔template_key mapping (defensive; not just TS)
  v_expected_type := case v_iv_type
    when 'limit_setting' then 'LIMIT_CONFIRMATION'
    when 'timeout' then 'TIMEOUT_CONFIRMATION'
    when 'self_exclusion_referral' then 'SELF_EXCLUSION_SUPPORT'
    when 'helpline_referral' then 'HELPLINE_SUPPORT'
    when 'counseling_referral' then 'COUNSELLING_SUPPORT'
    else null end;
  if v_expected_type is null then
    return query select 'INVALID_STATE'::text, null::uuid, null::integer; return;   -- manual_review / ai_alert / other
  end if;
  if p_communication_type is distinct from v_expected_type then
    return query select 'INVALID_STATE'::text, null::uuid, null::integer; return;
  end if;
  v_expected_key := case p_communication_type
    when 'LIMIT_CONFIRMATION' then 'rg.limit_confirmation'
    when 'TIMEOUT_CONFIRMATION' then 'rg.timeout_confirmation'
    when 'SELF_EXCLUSION_SUPPORT' then 'rg.self_exclusion_support'
    when 'HELPLINE_SUPPORT' then 'rg.helpline_support'
    when 'COUNSELLING_SUPPORT' then 'rg.counselling_support'
    else null end;
  if p_template_key is distinct from v_expected_key then
    return query select 'INVALID_STATE'::text, null::uuid, null::integer; return;
  end if;

  -- sequence under the already-held intervention lock
  select coalesce(max(c.sequence), 0) + 1 into v_seq from public.intervention_player_communications c
    where c.casino_id = p_casino_id and c.intervention_id = p_intervention_id;

  begin
    insert into public.intervention_player_communications (
      casino_id, intervention_id, communication_type, purpose, template_key, template_version,
      delivery_mode, channel_class, sequence, requested_by, request_idempotency_key, request_fingerprint, status)
    values (
      p_casino_id, p_intervention_id, p_communication_type, 'RESPONSIBLE_GAMBLING', p_template_key, 1,
      'SANDBOX', 'OPERATOR_MANAGED', v_seq, p_actor_id, p_idempotency_key, v_fp, 'PENDING')
    returning id into v_id;

    insert into public.audit_events (
      event_id, event_type, event_category, action, resource_type, resource_id,
      user_id, user_role, casino_id, severity, outcome, metadata)
    values (
      'b13:player-communication:' || v_id::text || ':requested',
      'intervention.player_communication_requested', 'responsible_gambling', 'intervention.player_communication_requested',
      'intervention_player_communication', v_id::text, p_actor_id, v_role, p_casino_id, 'info', 'success',
      jsonb_build_object('intervention_id', p_intervention_id, 'communication_type', p_communication_type,
        'purpose', 'RESPONSIBLE_GAMBLING', 'template_key', p_template_key, 'template_version', 1,
        'delivery_mode', 'SANDBOX', 'channel_class', 'OPERATOR_MANAGED', 'sequence', v_seq, 'sandbox', true));

    return query select 'CREATED'::text, v_id, v_seq; return;
  exception when unique_violation then
    -- Only the request-key race is an idempotency outcome; sequence/other uniqueness fails closed.
    get stacked diagnostics v_expected_key = constraint_name;
    if v_expected_key = 'iplc_request_idem_uq' then
      select * into v_existing from public.intervention_player_communications
        where casino_id = p_casino_id and request_idempotency_key = p_idempotency_key;
      if not found then raise exception 'B13: request idempotency resolution failed'; end if;
      if v_existing.request_fingerprint is not distinct from v_fp then
        return query select 'REPLAYED'::text, v_existing.id, v_existing.sequence; return;
      end if;
      return query select 'IDEMPOTENCY_CONFLICT'::text, null::uuid, null::integer; return;
    end if;
    raise;   -- sequence_uq / send_idem_uq / audit event_id / anything else → fail closed
  end;
end $$;


ALTER FUNCTION public.sbiq_b13_create_player_communication(p_casino_id uuid, p_actor_id uuid, p_intervention_id uuid, p_communication_type text, p_template_key text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: sbiq_b13_record_player_communication_receipt(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_b13_record_player_communication_receipt(p_casino_id uuid, p_communication_id uuid, p_status text, p_provider_reference text, p_failure_class text) RETURNS TABLE(status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_c   public.intervention_player_communications%rowtype;
  v_evt text;
begin
  if p_status not in ('SUBMITTED','DELIVERED','FAILED') then raise exception 'B13: invalid receipt status %', p_status; end if;

  select * into v_c from public.intervention_player_communications
    where id = p_communication_id and casino_id = p_casino_id for update;
  if not found then return query select 'NOT_FOUND'::text; return; end if;
  if v_c.delivery_mode <> 'SANDBOX' then raise exception 'B13: delivery_mode not SANDBOX'; end if;

  -- idempotent replay: current state already reflects the requested receipt. SUBMITTED carries
  -- the provider reference; DELIVERED is a pure status advance; FAILED carries the failure class.
  if p_status = 'SUBMITTED' and v_c.status = 'SUBMITTED' and v_c.provider_reference is not distinct from p_provider_reference then
    return query select 'REPLAYED'::text; return; end if;
  if p_status = 'DELIVERED' and v_c.status = 'DELIVERED' then
    return query select 'REPLAYED'::text; return; end if;
  if p_status = 'FAILED' and v_c.status = 'FAILED' and v_c.failure_class is not distinct from p_failure_class then
    return query select 'REPLAYED'::text; return; end if;

  if p_status = 'SUBMITTED' then
    if v_c.status <> 'SUBMITTING' then return query select 'INVALID_STATE'::text; return; end if;
    if p_provider_reference is null then raise exception 'B13: provider_reference required for SUBMITTED'; end if;
    update public.intervention_player_communications set status='SUBMITTED', submitted_at=now(), provider_reference=p_provider_reference
      where id=p_communication_id and casino_id=p_casino_id;
    v_evt := 'submitted';
  elsif p_status = 'DELIVERED' then
    if v_c.status <> 'SUBMITTED' then return query select 'INVALID_STATE'::text; return; end if;
    update public.intervention_player_communications set status='DELIVERED', delivered_at=now()
      where id=p_communication_id and casino_id=p_casino_id;
    v_evt := 'delivered';
  else  -- FAILED
    if v_c.status not in ('SUBMITTING','SUBMITTED') then return query select 'INVALID_STATE'::text; return; end if;
    if p_failure_class is null then raise exception 'B13: failure_class required for FAILED'; end if;
    update public.intervention_player_communications set status='FAILED', failed_at=now(), failure_class=p_failure_class
      where id=p_communication_id and casino_id=p_casino_id;   -- submitted_at/provider_reference retained if already set
    v_evt := 'failed';
  end if;

  insert into public.audit_events (
    event_id, event_type, event_category, action, resource_type, resource_id,
    user_id, user_role, casino_id, severity, outcome, metadata)
  values (
    'b13:player-communication:' || p_communication_id::text || ':' || v_evt,
    'intervention.player_communication_' || v_evt, 'responsible_gambling', 'intervention.player_communication_' || v_evt,
    'intervention_player_communication', p_communication_id::text, null, 'system', p_casino_id, 'info', 'success',
    jsonb_build_object('intervention_id', v_c.intervention_id, 'communication_type', v_c.communication_type,
      'purpose', v_c.purpose, 'template_key', v_c.template_key, 'template_version', v_c.template_version,
      'delivery_mode', v_c.delivery_mode, 'channel_class', v_c.channel_class, 'sequence', v_c.sequence,
      'sandbox', true, 'failure_class', p_failure_class));

  return query select 'RECORDED'::text; return;
end $$;


ALTER FUNCTION public.sbiq_b13_record_player_communication_receipt(p_casino_id uuid, p_communication_id uuid, p_status text, p_provider_reference text, p_failure_class text) OWNER TO postgres;

--
-- Name: sbiq_b6_link_after_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_b6_link_after_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_action text; v_role text; v_meta jsonb;
begin
  if NEW.supersedes_link_id is not null then
    update public.alert_intervention_links
       set superseded_at = NEW.linked_at, superseded_by = NEW.linked_by
     where id = NEW.supersedes_link_id and superseded_at is null;
    if not found then
      raise exception 'B6: could not supersede link % (missing or already superseded)', NEW.supersedes_link_id;
    end if;
    v_action := 'protection_alert.intervention_link_superseded';
    v_meta := jsonb_build_object(
      'alert_id', NEW.alert_id, 'intervention_id', NEW.intervention_id,
      'link_id', NEW.id, 'supersedes_link_id', NEW.supersedes_link_id);
  else
    v_action := 'protection_alert.intervention_linked';
    v_meta := jsonb_build_object(
      'alert_id', NEW.alert_id, 'intervention_id', NEW.intervention_id, 'link_id', NEW.id);
  end if;

  select u.role::text into v_role from public.users u where u.id = NEW.linked_by;

  insert into public.audit_events (
    event_id, event_type, event_category, action,
    resource_type, resource_id, user_id, user_role, casino_id,
    severity, outcome, metadata)
  values (
    'ail:' || v_action || ':' || NEW.id::text,
    v_action, 'responsible_gambling', v_action,
    'alert_intervention_link', NEW.id::text, NEW.linked_by, v_role, NEW.casino_id,
    'info', 'success', v_meta);

  return NEW;
end $$;


ALTER FUNCTION public.sbiq_b6_link_after_insert() OWNER TO postgres;

--
-- Name: sbiq_b6_link_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_b6_link_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_old public.alert_intervention_links;
begin
  if tg_op = 'INSERT' then
    -- DB owns these; caller input is overwritten / rejected.
    NEW.linked_at  := now();
    NEW.created_at := now();
    if NEW.linked_by is null then
      raise exception 'B6: linked_by is required';
    end if;
    -- An inserted row may NEVER arrive already-superseded (supersession is DB-driven).
    if NEW.superseded_at is not null or NEW.superseded_by is not null then
      raise exception 'B6: superseded_at/superseded_by must be null on insert';
    end if;

    if NEW.supersedes_link_id is not null then
      -- Correction (replacement) row: validate the target old link up-front (and lock it).
      if NEW.supersedes_link_id = NEW.id then
        raise exception 'B6: a link cannot supersede itself';
      end if;
      select * into v_old from public.alert_intervention_links
        where id = NEW.supersedes_link_id for update;
      if not found then
        raise exception 'B6: supersedes_link_id % does not exist', NEW.supersedes_link_id;
      end if;
      if v_old.superseded_at is not null then
        raise exception 'B6: link % is already superseded', NEW.supersedes_link_id;
      end if;
      if v_old.alert_id is distinct from NEW.alert_id then
        raise exception 'B6: supersession must target the same alert';
      end if;
      if v_old.casino_id is distinct from NEW.casino_id
         or v_old.player_id is distinct from NEW.player_id then
        raise exception 'B6: supersession must target the same casino/player';
      end if;
    end if;
    return NEW;
  end if;

  -- UPDATE: identity + provenance + timestamps are immutable.
  if NEW.id                 is distinct from OLD.id
     or NEW.casino_id       is distinct from OLD.casino_id
     or NEW.player_id       is distinct from OLD.player_id
     or NEW.alert_id        is distinct from OLD.alert_id
     or NEW.intervention_id is distinct from OLD.intervention_id
     or NEW.linked_at       is distinct from OLD.linked_at
     or NEW.linked_by       is distinct from OLD.linked_by
     or NEW.created_at      is distinct from OLD.created_at
     or NEW.supersedes_link_id is distinct from OLD.supersedes_link_id then
    raise exception 'B6: immutable link column changed on %', OLD.id;
  end if;

  if OLD.superseded_at is not null then
    -- Already superseded ⇒ fully immutable (no re-supersede, no un-supersede).
    if NEW.superseded_at is distinct from OLD.superseded_at
       or NEW.superseded_by is distinct from OLD.superseded_by then
      raise exception 'B6: a superseded link is immutable';
    end if;
    return NEW;
  end if;

  -- OLD is active. The only legal change is a null→value supersession (both set together),
  -- AND it must be backed by a real successor row (defeats a manual UPDATE with no
  -- replacement). A true no-op (still null) is permitted.
  if NEW.superseded_at is null and NEW.superseded_by is null then
    return NEW;
  elsif NEW.superseded_at is not null and NEW.superseded_by is not null then
    if not exists (
      select 1 from public.alert_intervention_links s
       where s.supersedes_link_id = NEW.id
         and s.linked_by  = NEW.superseded_by
         and s.linked_at  = NEW.superseded_at
         and s.alert_id   = NEW.alert_id
         and s.casino_id  = NEW.casino_id
         and s.player_id  = NEW.player_id
    ) then
      raise exception 'B6: supersession requires a matching successor link';
    end if;
    return NEW;
  else
    raise exception 'B6: superseded_at and superseded_by must be set together';
  end if;
end $$;


ALTER FUNCTION public.sbiq_b6_link_guard() OWNER TO postgres;

--
-- Name: sbiq_b8_set_follow_up(uuid, uuid, uuid, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_b8_set_follow_up(p_intervention_id uuid, p_casino_id uuid, p_actor_id uuid, p_action text, p_follow_up_date date) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_iv           public.player_protection_interventions%rowtype;
  v_role         text;
  v_actor_casino uuid;
  v_old          date;
  v_new          date;
  v_event        text;
begin
  if p_action not in ('SCHEDULE','RESCHEDULE','UNSCHEDULE') then
    raise exception 'B8: invalid action %', p_action;
  end if;

  -- Actor (defence-in-depth; the server API has already authorised the principal). Role
  -- is derived from the authoritative users row, never trusted from the caller.
  select u.role::text, u.casino_id into v_role, v_actor_casino
    from public.users u where u.id = p_actor_id;
  if v_role is null then raise exception 'B8: actor not found'; end if;
  if v_role not in ('casino_admin','compliance_officer','super_admin') then
    raise exception 'B8: actor role % not permitted', v_role;
  end if;
  if v_role in ('casino_admin','compliance_officer')
     and v_actor_casino is distinct from p_casino_id then
    raise exception 'B8: actor not governed for casino';
  end if;

  -- Lock the intervention within the governed casino; no cross-casino existence leak.
  select * into v_iv from public.player_protection_interventions
    where id = p_intervention_id and casino_id = p_casino_id
    for update;
  if not found then return 'NOT_FOUND'; end if;

  -- Requirement precedence (takes priority over idempotency).
  if v_iv.follow_up_required is not true then return 'INVALID_STATE'; end if;

  v_old := v_iv.follow_up_date;

  if p_action = 'SCHEDULE' then
    if p_follow_up_date is null then raise exception 'B8: SCHEDULE requires a date'; end if;
    if v_old is not null then return 'INVALID_STATE'; end if;
    v_new := p_follow_up_date; v_event := 'intervention.follow_up_scheduled';
  elsif p_action = 'RESCHEDULE' then
    if p_follow_up_date is null then raise exception 'B8: RESCHEDULE requires a date'; end if;
    if v_old is null then return 'INVALID_STATE'; end if;
    if p_follow_up_date = v_old then return 'NOOP'; end if;
    v_new := p_follow_up_date; v_event := 'intervention.follow_up_rescheduled';
  else  -- UNSCHEDULE
    if p_follow_up_date is not null then raise exception 'B8: UNSCHEDULE must not supply a date'; end if;
    if v_old is null then return 'NOOP'; end if;
    v_new := null; v_event := 'intervention.follow_up_unscheduled';
  end if;

  -- Only follow_up_date changes; identity/other fields are untouched.
  update public.player_protection_interventions
     set follow_up_date = v_new
   where id = p_intervention_id and casino_id = p_casino_id;

  -- Same-transaction audit into the existing chain (trg_audit_chain hashes it; failure
  -- rolls the whole statement back). Safe metadata only — no PII.
  insert into public.audit_events (
    event_id, event_type, event_category, action,
    resource_type, resource_id, user_id, user_role, casino_id, severity, outcome, metadata)
  values (
    'b8:' || v_event || ':' || p_intervention_id::text || ':' || gen_random_uuid()::text,
    v_event, 'responsible_gambling', v_event,
    'player_protection_intervention', p_intervention_id::text, p_actor_id, v_role, p_casino_id,
    'info', 'success',
    jsonb_build_object('old_follow_up_date', v_old, 'new_follow_up_date', v_new, 'operation', p_action));

  return 'APPLIED';
end $$;


ALTER FUNCTION public.sbiq_b8_set_follow_up(p_intervention_id uuid, p_casino_id uuid, p_actor_id uuid, p_action text, p_follow_up_date date) OWNER TO postgres;

--
-- Name: sbiq_b9_record_alert_intervention(uuid, uuid, uuid, uuid, text, text, boolean, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_b9_record_alert_intervention(p_alert_id uuid, p_casino_id uuid, p_actor_id uuid, p_idempotency_key uuid, p_intervention_type text, p_outcome text, p_follow_up_required boolean, p_follow_up_date date) RETURNS TABLE(status text, intervention_id uuid, link_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_role     text;
  v_actor_casino uuid;
  v_player   uuid;
  v_fp       text;
  v_iv       uuid;
  v_link     uuid;
  v_existing public.player_protection_interventions%rowtype;
begin
  -- Input validation (operator subset EXCLUDES ai_alert; never widens the table CHECK).
  if p_idempotency_key is null then raise exception 'B9: idempotency key required'; end if;
  if p_intervention_type not in
     ('manual_review','limit_setting','timeout','self_exclusion_referral','helpline_referral','counseling_referral') then
    raise exception 'B9: intervention_type % not permitted', p_intervention_type;
  end if;
  if p_outcome is not null and p_outcome not in ('accepted','declined','pending','successful','unsuccessful') then
    raise exception 'B9: invalid outcome %', p_outcome;
  end if;
  if p_follow_up_required is null then raise exception 'B9: follow_up_required is required'; end if;
  if p_follow_up_required is not true and p_follow_up_date is not null then
    raise exception 'B9: follow_up_date requires follow_up_required=true';
  end if;

  -- Actor (defence-in-depth; server already authorised). Role from authoritative users.
  select u.role::text, u.casino_id into v_role, v_actor_casino from public.users u where u.id = p_actor_id;
  if v_role is null then raise exception 'B9: actor not found'; end if;
  if v_role not in ('casino_admin','compliance_officer','super_admin') then
    raise exception 'B9: actor role % not permitted', v_role;
  end if;
  if v_role in ('casino_admin','compliance_officer') and v_actor_casino is distinct from p_casino_id then
    raise exception 'B9: actor not governed for casino';
  end if;

  -- Authoritative casino/player from the scoped alert (no caller player_id; no status gate).
  select a.player_id into v_player
    from public.player_protection_alerts a
    where a.id = p_alert_id and a.casino_id = p_casino_id
    for share;
  if not found then
    return query select 'NOT_FOUND'::text, null::uuid, null::uuid; return;
  end if;

  -- Immutable canonical fingerprint of the ORIGINAL logical request (DB-computed; never a
  -- caller argument). Null markers distinguish NULL outcome/date from real values.
  v_fp := encode(extensions.digest(convert_to(
    'b9v1' || chr(31) || p_casino_id::text || chr(31) || p_alert_id::text || chr(31) || p_actor_id::text
          || chr(31) || p_intervention_type
          || chr(31) || coalesce(p_outcome, chr(1) || 'NULL')
          || chr(31) || p_follow_up_required::text
          || chr(31) || coalesce(p_follow_up_date::text, chr(1) || 'NULL'),
    'UTF8'), 'sha256'), 'hex');

  -- Race-safe first-writer INSERT with the explicit HONEST column list (no simulator defaults).
  insert into public.player_protection_interventions (
    casino_id, player_id, intervention_date, intervention_type, risk_score, trigger_reason, action_taken,
    outcome, follow_up_required, follow_up_date, staff_id, notes, created_at, dispatch_status, triggered_at,
    risk_score_at_trigger, intervention_successful, auto_triggered, channel, message_content, delivered_at,
    delivery_attempts, delivery_error, acknowledged_at, acknowledged_by, risk_score_after, nrgp_reported,
    nrgp_reported_at, compliance_ref, source, b9_idempotency_key, b9_request_fingerprint)
  values (
    p_casino_id, v_player, now(), p_intervention_type, null, null, null,
    p_outcome, p_follow_up_required, p_follow_up_date, null, null, now(), null, null,
    null, null, false, 'manual', null, null,
    0, null, null, null, null, false,
    null, null, 'manual', p_idempotency_key, v_fp)
  on conflict (casino_id, b9_idempotency_key) do nothing
  returning id into v_iv;

  if v_iv is not null then
    -- Creation audit (same transaction; trg_audit_chain hashes it).
    insert into public.audit_events (
      event_id, event_type, event_category, action, resource_type, resource_id,
      user_id, user_role, casino_id, severity, outcome, metadata)
    values (
      'b9:intervention.recorded:' || v_iv::text,
      'intervention.recorded', 'responsible_gambling', 'intervention.recorded',
      'player_protection_intervention', v_iv::text, p_actor_id, v_role, p_casino_id, 'info', 'success',
      jsonb_build_object(
        'intervention_type', p_intervention_type,
        'follow_up_required', p_follow_up_required,
        'follow_up_date_present', (p_follow_up_date is not null),
        'origin', 'alert', 'alert_id', p_alert_id));

    -- ONE active initial B6 link (reuses B6 table/guards/triggers; emits its own link audit).
    insert into public.alert_intervention_links (casino_id, alert_id, intervention_id, player_id, linked_by)
    values (p_casino_id, p_alert_id, v_iv, v_player, p_actor_id)
    returning id into v_link;

    return query select 'CREATED'::text, v_iv, v_link; return;
  end if;

  -- Conflict: a row already owns (casino_id, idempotency_key). Durable replay equality by the
  -- IMMUTABLE fingerprint — NOT by current mutable fields (so later B8 reschedule / B6
  -- supersession cannot break a genuine retry).
  select * into v_existing
    from public.player_protection_interventions
    where casino_id = p_casino_id and b9_idempotency_key = p_idempotency_key;
  if not found then raise exception 'B9: idempotency conflict resolution failed'; end if;

  if v_existing.b9_request_fingerprint is distinct from v_fp then
    return query select 'IDEMPOTENCY_CONFLICT'::text, null::uuid, null::uuid; return;
  end if;

  -- REPLAYED: return the ORIGINAL (earliest) historical B9 link for this alert+intervention,
  -- regardless of later supersession. Never manufacture a new link on replay.
  select l.id into v_link
    from public.alert_intervention_links l
    where l.alert_id = p_alert_id and l.intervention_id = v_existing.id and l.casino_id = p_casino_id
    order by l.linked_at asc, l.id asc
    limit 1;
  if v_link is null then raise exception 'B9: replay integrity — original link missing'; end if;

  return query select 'REPLAYED'::text, v_existing.id, v_link; return;
end $$;


ALTER FUNCTION public.sbiq_b9_record_alert_intervention(p_alert_id uuid, p_casino_id uuid, p_actor_id uuid, p_idempotency_key uuid, p_intervention_type text, p_outcome text, p_follow_up_required boolean, p_follow_up_date date) OWNER TO postgres;

--
-- Name: sbiq_canonical_json(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_canonical_json(v jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare k text; parts text[] := array[]::text[]; e jsonb;
begin
  if v is null or v = 'null'::jsonb then return 'null'; end if;
  if jsonb_typeof(v) = 'object' then
    for k in select key from jsonb_object_keys(v) as t(key) order by key loop
      parts := parts || ('"'||replace(k,'"','\"')||'":'||sbiq_canonical_json(v->k));
    end loop;
    return '{'||array_to_string(parts,',')||'}';
  elsif jsonb_typeof(v) = 'array' then
    for e in select value from jsonb_array_elements(v) as t(value) loop
      parts := parts || sbiq_canonical_json(e);
    end loop;
    return '['||array_to_string(parts,',')||']';
  else
    return '"'||replace(replace(v #>> '{}', '\', '\\'), '"', '\"')||'"';
  end if;
end $$;


ALTER FUNCTION public.sbiq_canonical_json(v jsonb) OWNER TO postgres;

