--
-- Name: TABLE casinos; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.casinos IS 'Root tenant table. Every table in SafeBet IQ carries casino_id as a FK to this table. Multi-tenant isolation is enforced at three layers: RLS policies on this table, application-level JWT validation, and api-ingest Edge Function header enforcement.';


--
-- Name: COLUMN casinos.id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.casinos.id IS 'Tenant identifier. Used as casino_id FK across all tables. UUIDs for three known seed casinos are fixed (11111111-..., 22222222-..., 33333333-...) for deterministic seeds.';


--
-- Name: COLUMN casinos.simulation_mode; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.casinos.simulation_mode IS 'When true, the casino-simulator Edge Function injects synthetic events for this casino. Used for demo environments. Production casinos must have simulation_mode = false.';


--
-- Name: COLUMN casinos.updated_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.casinos.updated_at IS 'Automatically maintained by trg_casinos_updated_at trigger.';


--
-- Name: COLUMN casinos.hmac_secret; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.casinos.hmac_secret IS 'Shared HMAC-SHA256 secret for api-ingest webhook signature verification. NULL = casino uses legacy API key auth. Must be 32+ bytes of random data. REVOKED from anon and authenticated roles — service role only.';


--
-- Name: COLUMN casinos.environment; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.casinos.environment IS 'demo | production | staging. Controls whether casino-simulator runs for this tenant.';


--
-- Name: COLUMN casinos.api_enabled; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.casinos.api_enabled IS 'Master switch for api-ingest webhook processing for this casino. Set to false to block all inbound webhook traffic without deleting tokens.';


--
-- Name: COLUMN casinos.jurisdiction; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.casinos.jurisdiction IS 'Regulatory territory of this casino (policy pack selector). Registry source of truth — never a caller claim.';


--
-- Name: financial_shift_policy; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.financial_shift_policy (
    scope text NOT NULL,
    casino_id uuid,
    timezone text DEFAULT 'Africa/Johannesburg'::text NOT NULL,
    currency text DEFAULT 'ZAR'::text NOT NULL,
    day_shift_start time without time zone DEFAULT '06:00:00'::time without time zone NOT NULL,
    night_shift_start time without time zone DEFAULT '18:00:00'::time without time zone NOT NULL,
    effective_from date DEFAULT '2000-01-01'::date NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT financial_shift_policy_scope_check CHECK ((scope = ANY (ARRAY['platform'::text, 'casino'::text])))
);


ALTER TABLE public.financial_shift_policy OWNER TO postgres;

--
-- Name: projection_financial_posture; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.projection_financial_posture WITH (security_invoker='true') AS
 WITH cfg AS (
         SELECT c.id AS casino_id,
            COALESCE(fp.timezone, plat.timezone, 'Africa/Johannesburg'::text) AS tz,
            COALESCE(fp.currency, plat.currency, 'ZAR'::text) AS currency,
            COALESCE(fp.day_shift_start, plat.day_shift_start, '06:00:00'::time without time zone) AS day_start,
            COALESCE(fp.night_shift_start, plat.night_shift_start, '18:00:00'::time without time zone) AS night_start
           FROM ((public.casinos c
             LEFT JOIN public.financial_shift_policy fp ON (((fp.scope = 'casino'::text) AND (fp.casino_id = c.id))))
             LEFT JOIN LATERAL ( SELECT financial_shift_policy.scope,
                    financial_shift_policy.casino_id,
                    financial_shift_policy.timezone,
                    financial_shift_policy.currency,
                    financial_shift_policy.day_shift_start,
                    financial_shift_policy.night_shift_start,
                    financial_shift_policy.effective_from,
                    financial_shift_policy.updated_at
                   FROM public.financial_shift_policy
                  WHERE ((financial_shift_policy.scope = 'platform'::text) AND (financial_shift_policy.casino_id IS NULL))
                 LIMIT 1) plat ON (true))
        ), bounds AS (
         SELECT cfg.casino_id,
            cfg.tz,
            cfg.currency,
            cfg.day_start,
            cfg.night_start,
            (date_trunc('day'::text, (now() AT TIME ZONE cfg.tz)) AT TIME ZONE cfg.tz) AS today_start,
            (date_trunc('month'::text, (now() AT TIME ZONE cfg.tz)) AT TIME ZONE cfg.tz) AS mtd_start,
            (now() - '24:00:00'::interval) AS h24_start,
                CASE
                    WHEN ((((now() AT TIME ZONE cfg.tz))::time without time zone >= cfg.day_start) AND (((now() AT TIME ZONE cfg.tz))::time without time zone < cfg.night_start)) THEN ((date_trunc('day'::text, (now() AT TIME ZONE cfg.tz)) + (cfg.day_start)::interval) AT TIME ZONE cfg.tz)
                    WHEN (((now() AT TIME ZONE cfg.tz))::time without time zone >= cfg.night_start) THEN ((date_trunc('day'::text, (now() AT TIME ZONE cfg.tz)) + (cfg.night_start)::interval) AT TIME ZONE cfg.tz)
                    ELSE (((date_trunc('day'::text, (now() AT TIME ZONE cfg.tz)) - '1 day'::interval) + (cfg.night_start)::interval) AT TIME ZONE cfg.tz)
                END AS shift_start
           FROM cfg
        ), agg AS (
         SELECT b.casino_id,
            b.currency,
            b.tz,
            b.shift_start,
            b.today_start,
            b.mtd_start,
            COALESCE(sum(e.stake) FILTER (WHERE (e.occurred_at >= b.shift_start)), (0)::numeric) AS stakes_current_shift,
            COALESCE(sum(e.winnings) FILTER (WHERE (e.occurred_at >= b.shift_start)), (0)::numeric) AS player_winnings_current_shift,
            COALESCE(sum((e.stake - e.winnings)) FILTER (WHERE (e.occurred_at >= b.shift_start)), (0)::numeric) AS ggr_current_shift,
            COALESCE(sum(e.stake) FILTER (WHERE (e.occurred_at >= b.today_start)), (0)::numeric) AS stakes_today,
            COALESCE(sum(e.winnings) FILTER (WHERE (e.occurred_at >= b.today_start)), (0)::numeric) AS player_winnings_today,
            COALESCE(sum((e.stake - e.winnings)) FILTER (WHERE (e.occurred_at >= b.today_start)), (0)::numeric) AS ggr_today,
            COALESCE(sum(e.stake) FILTER (WHERE (e.occurred_at >= b.h24_start)), (0)::numeric) AS stakes_last_24_hours,
            COALESCE(sum(e.winnings) FILTER (WHERE (e.occurred_at >= b.h24_start)), (0)::numeric) AS player_winnings_last_24_hours,
            COALESCE(sum((e.stake - e.winnings)) FILTER (WHERE (e.occurred_at >= b.h24_start)), (0)::numeric) AS ggr_last_24_hours,
            COALESCE(sum(e.stake) FILTER (WHERE (e.occurred_at >= b.mtd_start)), (0)::numeric) AS stakes_month_to_date,
            COALESCE(sum(e.winnings) FILTER (WHERE (e.occurred_at >= b.mtd_start)), (0)::numeric) AS player_winnings_month_to_date,
            COALESCE(sum((e.stake - e.winnings)) FILTER (WHERE (e.occurred_at >= b.mtd_start)), (0)::numeric) AS ggr_month_to_date,
            count(e.event_id) FILTER (WHERE (e.occurred_at >= b.today_start)) AS settled_bets_today,
            count(e.event_id) AS financial_events_total,
            count(e.event_id) FILTER (WHERE e.is_synthetic) AS synthetic_event_count,
            count(e.event_id) FILTER (WHERE (NOT e.is_synthetic)) AS non_synthetic_event_count
           FROM (bounds b
             LEFT JOIN LATERAL ( SELECT cel.event_id,
                    cel.occurred_at,
                    cel.event_type,
                    ((cel.payload ->> 'bet_amount'::text))::numeric AS stake,
                    COALESCE(((cel.payload ->> 'win_amount'::text))::numeric, (0)::numeric) AS winnings,
                    (COALESCE(((cel.payload ->> 'is_simulated'::text))::boolean, false) OR COALESCE(((cel.payload ->> 'synthetic'::text))::boolean, false)) AS is_synthetic
                   FROM public.casino_event_log cel
                  WHERE ((cel.casino_id = b.casino_id) AND (cel.event_type = ANY (ARRAY['BET_PLACED'::text, 'JACKPOT'::text])) AND ((cel.payload ->> 'bet_amount'::text) IS NOT NULL))) e ON (true))
          GROUP BY b.casino_id, b.currency, b.tz, b.shift_start, b.today_start, b.mtd_start
        )
 SELECT agg.casino_id,
    agg.currency AS financial_currency,
    agg.tz AS financial_timezone,
    agg.shift_start,
    agg.today_start,
    agg.mtd_start,
    agg.stakes_current_shift,
    agg.player_winnings_current_shift,
    agg.ggr_current_shift,
    agg.stakes_today,
    agg.player_winnings_today,
    agg.ggr_today,
    agg.stakes_last_24_hours,
    agg.player_winnings_last_24_hours,
    agg.ggr_last_24_hours,
    agg.stakes_month_to_date,
    agg.player_winnings_month_to_date,
    agg.ggr_month_to_date,
    agg.settled_bets_today,
        CASE
            WHEN cap.voids_supported THEN (0)::bigint
            ELSE NULL::bigint
        END AS voided_bets_today,
        CASE
            WHEN cap.reversals_supported THEN (0)::bigint
            ELSE NULL::bigint
        END AS reversed_transactions_today,
        CASE
            WHEN cap.bonus_supported THEN (0)::bigint
            ELSE NULL::bigint
        END AS bonus_wagers_today,
    cap.voids_supported,
    cap.reversals_supported,
    cap.bonus_supported,
    cap.combined_wager_settlement,
    cap.separate_settlement,
    cap.capability_version,
    agg.financial_events_total,
    agg.synthetic_event_count,
    agg.non_synthetic_event_count,
    (agg.synthetic_event_count > 0) AS contains_synthetic_data,
        CASE
            WHEN (agg.financial_events_total = 0) THEN 'unavailable'::text
            WHEN (agg.non_synthetic_event_count = 0) THEN 'synthetic'::text
            WHEN (agg.synthetic_event_count = 0) THEN 'live'::text
            ELSE 'mixed'::text
        END AS financial_data_mode,
        CASE
            WHEN (agg.financial_events_total = 0) THEN 'unavailable'::text
            WHEN (cap.voids_supported AND cap.reversals_supported) THEN 'healthy'::text
            ELSE 'partial'::text
        END AS financial_data_status,
    (0)::numeric AS financial_projection_lag_seconds,
    now() AS financial_snapshot_at
   FROM (agg
     LEFT JOIN LATERAL public.sbiq_financial_capability(agg.casino_id) cap(scope, casino_id, capability_version, combined_wager_settlement, separate_settlement, voids_supported, cancellations_supported, reversals_supported, refunds_supported, bonus_supported, jackpot_contribution_supported, jackpot_payout_supported, round_ids_supported, transaction_ids_supported, multi_currency_supported, late_correction_supported, updated_at) ON (true));


ALTER VIEW public.projection_financial_posture OWNER TO postgres;

--
-- Name: sbiq_certified_financial_posture_v2(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_certified_financial_posture_v2(p_casino uuid DEFAULT NULL::uuid, p_as_of timestamp with time zone DEFAULT now()) RETURNS SETOF public.projection_financial_posture
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with now_ref as (select p_as_of now_ts, date_trunc('hour', p_as_of) cur_hour),
  cfg as (
    select c.id casino_id,
      coalesce((select currency from financial_shift_policy where scope='casino' and casino_id=c.id limit 1),
               (select currency from financial_shift_policy where scope='platform' and casino_id is null limit 1),'ZAR') currency,
      coalesce((select timezone from financial_shift_policy where scope='casino' and casino_id=c.id limit 1),
               (select timezone from financial_shift_policy where scope='platform' and casino_id is null limit 1),'Africa/Johannesburg') tz,
      coalesce((select day_shift_start from financial_shift_policy where scope='casino' and casino_id=c.id limit 1),
               (select day_shift_start from financial_shift_policy where scope='platform' and casino_id is null limit 1),'06:00'::time) day_start,
      coalesce((select night_shift_start from financial_shift_policy where scope='casino' and casino_id=c.id limit 1),
               (select night_shift_start from financial_shift_policy where scope='platform' and casino_id is null limit 1),'18:00'::time) night_start
    from casinos c where p_casino is null or c.id = p_casino
  ),
  bounds as (
    select g.casino_id, g.currency, g.tz, n.now_ts, n.cur_hour,
      (date_trunc('day', n.now_ts at time zone g.tz) at time zone g.tz) today_start,
      (date_trunc('month', n.now_ts at time zone g.tz) at time zone g.tz) mtd_start,
      n.now_ts - interval '24 hours' h24_start,
      case when (n.now_ts at time zone g.tz)::time >= g.day_start and (n.now_ts at time zone g.tz)::time < g.night_start
             then (date_trunc('day', n.now_ts at time zone g.tz) + g.day_start::interval) at time zone g.tz
           when (n.now_ts at time zone g.tz)::time >= g.night_start
             then (date_trunc('day', n.now_ts at time zone g.tz) + g.night_start::interval) at time zone g.tz
           else (date_trunc('day', n.now_ts at time zone g.tz) - interval '1 day' + g.night_start::interval) at time zone g.tz
      end shift_start
    from cfg g cross join now_ref n
  ),
  buck as (   -- complete buckets (bucket_start < cur_hour)
    select b.casino_id,
      coalesce(sum(r.settled_stakes)  filter (where r.bucket_start >= b.shift_start),0) s_shift,
      coalesce(sum(r.player_winnings) filter (where r.bucket_start >= b.shift_start),0) w_shift,
      coalesce(sum(r.settled_stakes)  filter (where r.bucket_start >= b.today_start),0) s_today,
      coalesce(sum(r.player_winnings) filter (where r.bucket_start >= b.today_start),0) w_today,
      coalesce(sum(r.settled_stakes)  filter (where r.bucket_start >= b.mtd_start),0) s_mtd,
      coalesce(sum(r.player_winnings) filter (where r.bucket_start >= b.mtd_start),0) w_mtd,
      coalesce(sum(r.settled_stakes)  filter (where r.bucket_start >= date_trunc('hour',b.h24_start)+interval '1 hour'),0) s_h24,
      coalesce(sum(r.player_winnings) filter (where r.bucket_start >= date_trunc('hour',b.h24_start)+interval '1 hour'),0) w_h24,
      coalesce(sum(r.supported_bet_count) filter (where r.bucket_start >= b.today_start),0) cnt_today,
      coalesce(sum(r.supported_bet_count),0) cnt_total,
      coalesce(sum(r.synthetic_event_count),0) synth_total,
      coalesce(sum(r.non_synthetic_event_count),0) nonsynth_total
    from bounds b
    left join sbiq_financial_rollup_hourly r on r.casino_id=b.casino_id and r.bucket_start < b.cur_hour
    group by b.casino_id
  ),
  tail as (   -- current incomplete hour [cur_hour, now)
    select b.casino_id,
      coalesce(sum(x.stake),0) t_stake, coalesce(sum(x.win),0) t_win, count(x.*) t_cnt,
      count(x.*) filter (where x.is_synth) t_synth, count(x.*) filter (where not x.is_synth) t_nonsynth
    from bounds b left join lateral (
      select (e.payload->>'bet_amount')::numeric stake, coalesce((e.payload->>'win_amount')::numeric,0) win,
             coalesce((e.payload->>'is_simulated')::boolean,false) or coalesce((e.payload->>'synthetic')::boolean,false) is_synth
      from casino_event_log e
      where e.casino_id=b.casino_id and e.event_type in ('BET_PLACED','JACKPOT') and e.payload->>'bet_amount' is not null
        and e.occurred_at >= b.cur_hour and e.occurred_at < b.now_ts
    ) x on true group by b.casino_id
  ),
  h24b as (   -- h24 rolling-boundary partial hour [h24_start, boundary_hour+1h)
    select b.casino_id, coalesce(sum(x.stake),0) hs, coalesce(sum(x.win),0) hw
    from bounds b left join lateral (
      select (e.payload->>'bet_amount')::numeric stake, coalesce((e.payload->>'win_amount')::numeric,0) win
      from casino_event_log e
      where e.casino_id=b.casino_id and e.event_type in ('BET_PLACED','JACKPOT') and e.payload->>'bet_amount' is not null
        and e.occurred_at >= b.h24_start
        and e.occurred_at < date_trunc('hour',b.h24_start)+interval '1 hour'
        and e.occurred_at < b.cur_hour
    ) x on true group by b.casino_id
  )
  select
    b.casino_id, b.currency financial_currency, b.tz financial_timezone,
    b.shift_start, b.today_start, b.mtd_start,
    (bk.s_shift + t.t_stake) stakes_current_shift,
    (bk.w_shift + t.t_win) player_winnings_current_shift,
    ((bk.s_shift + t.t_stake) - (bk.w_shift + t.t_win)) ggr_current_shift,
    (bk.s_today + t.t_stake) stakes_today,
    (bk.w_today + t.t_win) player_winnings_today,
    ((bk.s_today + t.t_stake) - (bk.w_today + t.t_win)) ggr_today,
    (bk.s_h24 + h.hs + t.t_stake) stakes_last_24_hours,
    (bk.w_h24 + h.hw + t.t_win) player_winnings_last_24_hours,
    ((bk.s_h24 + h.hs + t.t_stake) - (bk.w_h24 + h.hw + t.t_win)) ggr_last_24_hours,
    (bk.s_mtd + t.t_stake) stakes_month_to_date,
    (bk.w_mtd + t.t_win) player_winnings_month_to_date,
    ((bk.s_mtd + t.t_stake) - (bk.w_mtd + t.t_win)) ggr_month_to_date,
    (bk.cnt_today + t.t_cnt) settled_bets_today,
    case when cap.voids_supported then 0::bigint else null::bigint end voided_bets_today,
    case when cap.reversals_supported then 0::bigint else null::bigint end reversed_transactions_today,
    case when cap.bonus_supported then 0::bigint else null::bigint end bonus_wagers_today,
    cap.voids_supported, cap.reversals_supported, cap.bonus_supported,
    cap.combined_wager_settlement, cap.separate_settlement, cap.capability_version,
    (bk.cnt_total + t.t_cnt) financial_events_total,
    (bk.synth_total + t.t_synth) synthetic_event_count,
    (bk.nonsynth_total + t.t_nonsynth) non_synthetic_event_count,
    ((bk.synth_total + t.t_synth) > 0) contains_synthetic_data,
    case when (bk.cnt_total + t.t_cnt) = 0 then 'unavailable'
         when (bk.nonsynth_total + t.t_nonsynth) = 0 then 'synthetic'
         when (bk.synth_total + t.t_synth) = 0 then 'live' else 'mixed' end financial_data_mode,
    case when (bk.cnt_total + t.t_cnt) = 0 then 'unavailable'
         when cap.voids_supported and cap.reversals_supported then 'healthy' else 'partial' end financial_data_status,
    0::numeric financial_projection_lag_seconds,
    b.now_ts financial_snapshot_at
  from bounds b
  join buck bk on bk.casino_id=b.casino_id
  join tail t on t.casino_id=b.casino_id
  join h24b h on h.casino_id=b.casino_id
  left join lateral sbiq_financial_capability(b.casino_id) cap on true;
$$;


ALTER FUNCTION public.sbiq_certified_financial_posture_v2(p_casino uuid, p_as_of timestamp with time zone) OWNER TO postgres;

--
-- Name: sbiq_connector_health(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_connector_health(p_casino uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with recent as (
    select * from connector_runs where casino_id = p_casino order by created_at desc limit 200
  )
  select jsonb_build_object(
    'casino_id', p_casino,
    'runs', (select count(*) from recent),
    'received', (select coalesce(sum(received),0) from recent),
    'submitted', (select coalesce(sum(submitted),0) from recent),
    'rejected', (select coalesce(sum(rejected),0) from recent),
    'failed', (select coalesce(sum(failed),0) from recent),
    'last_run_at', (select max(finished_at) from recent),
    'connectors', (
      select coalesce(jsonb_agg(c), '[]'::jsonb) from (
        select connector_type, connector_name, sum(received) as received, sum(submitted) as submitted,
               sum(rejected) as rejected, sum(failed) as failed, max(finished_at) as last_run_at
        from recent group by connector_type, connector_name order by max(finished_at) desc
      ) c
    ),
    'recent_diagnostics', (
      select coalesce(jsonb_agg(d), '[]'::jsonb) from (
        select connector_name, finished_at, diagnostics from recent
        where jsonb_array_length(diagnostics) > 0 order by finished_at desc limit 10
      ) d
    )
  );
$$;


ALTER FUNCTION public.sbiq_connector_health(p_casino uuid) OWNER TO postgres;

--
-- Name: sbiq_customer_success(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_customer_success() RETURNS TABLE(casino_id uuid, casino_name text, jurisdiction text, plan text, sub_status text, trial_ends_at timestamp with time zone, current_period_end timestamp with time zone, onboarding_completed jsonb, onboarding_activated boolean, pilot_status text, pilot_checklist jsonb, connector_runs bigint, connector_failed bigint, events_in_log bigint, last_event_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.id, c.name, c.jurisdiction,
    coalesce(s.plan,'none'), coalesce(s.status,'none'), s.trial_ends_at, s.current_period_end,
    coalesce(o.completed,'[]'::jsonb), (o.activated_at is not null),
    coalesce(p.status,'planned'), coalesce(p.checklist,'[]'::jsonb),
    (select count(*) from connector_runs cr where cr.casino_id = c.id),
    (select coalesce(sum(cr.failed),0) from connector_runs cr where cr.casino_id = c.id),
    (select count(*) from casino_event_log e where e.casino_id = c.id),
    (select max(e.occurred_at) from casino_event_log e where e.casino_id = c.id)
  from casinos c
  left join operator_subscriptions s on s.casino_id = c.id
  left join operator_onboarding o on o.casino_id = c.id
  left join pilot_deployments p on p.casino_id = c.id
  where c.is_active order by c.name;
$$;


ALTER FUNCTION public.sbiq_customer_success() OWNER TO postgres;

--
-- Name: sbiq_demo_activate_showcase(text, uuid, text, integer, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_demo_activate_showcase(p_scope text, p_casino uuid, p_profile text DEFAULT 'showcase'::text, p_minutes integer DEFAULT 30, p_account uuid DEFAULT NULL::uuid, p_correlation uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  is_reg boolean := (p_casino is null);
  cool_min int; max_min int; init_min int; per_hour int; act_count int; win_count int;
  v_id bigint; v_activated timestamptz; v_exp timestamptz; v_cap timestamptz;
begin
  if (select value from sbiq_demo_sim_flags where key='ENABLE_DEMO_SHOWCASE_MODE') is distinct from 'true' then
    insert into sbiq_demo_showcase_activations(scope,casino_id,profile,account_id,correlation_id,decision,requested_minutes)
      values (p_scope,p_casino,p_profile,p_account,p_correlation,'disabled',p_minutes);
    return jsonb_build_object('ok', false, 'reason', 'showcase_disabled');
  end if;

  if is_reg then
    init_min := coalesce(p_minutes, sbiq_demo_limit('REGULATOR_SHOWCASE_MINUTES'))::int;
    cool_min := sbiq_demo_limit('REGULATOR_SHOWCASE_COOLDOWN_MINUTES')::int;
    max_min  := sbiq_demo_limit('REGULATOR_SHOWCASE_MAX_MINUTES')::int;
    per_hour := sbiq_demo_limit('MAX_REGULATOR_ACTIVATIONS_PER_HOUR')::int;
  else
    init_min := coalesce(p_minutes, sbiq_demo_limit('CASINO_SHOWCASE_MINUTES'))::int;
    cool_min := sbiq_demo_limit('CASINO_SHOWCASE_COOLDOWN_MINUTES')::int;
    max_min  := sbiq_demo_limit('CASINO_SHOWCASE_MAX_MINUTES')::int;
    per_hour := sbiq_demo_limit('MAX_SHOWCASE_ACTIVATIONS_PER_HOUR')::int;
  end if;

  -- Existing active window for this scope?
  select id, activated_at, expires_at into v_id, v_activated, v_exp
    from sbiq_demo_showcase_windows where status='active' and scope=p_scope
    order by activated_at desc limit 1;

  if v_id is not null then
    -- Idempotent / cooldown: recent activation must not keep extending the window.
    if v_activated > now() - make_interval(mins => cool_min) then
      insert into sbiq_demo_showcase_activations(scope,casino_id,profile,account_id,correlation_id,decision,requested_minutes,effective_expiry)
        values (p_scope,p_casino,p_profile,p_account,p_correlation,'cooldown',init_min,v_exp);
      return jsonb_build_object('ok', true, 'reason', 'cooldown', 'window_id', v_id, 'expires_at', v_exp);
    end if;
    -- Extend, but never beyond max_min from ORIGINAL activation.
    v_cap := v_activated + make_interval(mins => max_min);
    v_exp := least(greatest(v_exp, now() + make_interval(mins => init_min)), v_cap);
    update sbiq_demo_showcase_windows set expires_at = v_exp where id = v_id;
    insert into sbiq_demo_showcase_activations(scope,casino_id,profile,account_id,correlation_id,decision,requested_minutes,effective_expiry)
      values (p_scope,p_casino,p_profile,p_account,p_correlation,'extended',init_min,v_exp);
    return jsonb_build_object('ok', true, 'reason', 'extended', 'window_id', v_id, 'expires_at', v_exp);
  end if;

  -- No active window: enforce per-hour activation rate and max concurrent windows.
  act_count := (select count(*) from sbiq_demo_showcase_activations sda
    where sda.scope=p_scope and sda.decision in ('accepted','extended') and sda.created_at > now()-interval '1 hour');
  if act_count >= per_hour then
    insert into sbiq_demo_showcase_activations(scope,casino_id,profile,account_id,correlation_id,decision,requested_minutes)
      values (p_scope,p_casino,p_profile,p_account,p_correlation,'rate_limited',init_min);
    perform sbiq_demo_raise_alert('SIMULATOR_SHOWCASE_RATE_LIMIT','warning',p_scope,p_casino,
      jsonb_build_object('activations_last_hour',act_count,'limit',per_hour), p_correlation);
    return jsonb_build_object('ok', true, 'reason', 'rate_limited');
  end if;

  win_count := (select count(*) from sbiq_demo_showcase_windows where status='active' and expires_at>now());
  if win_count >= sbiq_demo_limit('MAX_ACTIVE_SHOWCASE_WINDOWS')::int then
    insert into sbiq_demo_showcase_activations(scope,casino_id,profile,account_id,correlation_id,decision,requested_minutes)
      values (p_scope,p_casino,p_profile,p_account,p_correlation,'max_windows',init_min);
    return jsonb_build_object('ok', true, 'reason', 'max_windows');
  end if;

  v_exp := now() + make_interval(mins => init_min);
  insert into sbiq_demo_showcase_windows(scope, casino_id, profile, expires_at, correlation_id, triggered_by)
    values (p_scope, p_casino, p_profile, v_exp, p_correlation, p_account) returning id into v_id;
  insert into sbiq_demo_showcase_activations(scope,casino_id,profile,account_id,correlation_id,decision,requested_minutes,effective_expiry)
    values (p_scope,p_casino,p_profile,p_account,p_correlation,'accepted',init_min,v_exp);
  return jsonb_build_object('ok', true, 'reason', 'accepted', 'window_id', v_id, 'expires_at', v_exp);
end; $$;


ALTER FUNCTION public.sbiq_demo_activate_showcase(p_scope text, p_casino uuid, p_profile text, p_minutes integer, p_account uuid, p_correlation uuid) OWNER TO postgres;

