--
-- Name: sbiq_ppa_audit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_ppa_audit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_action text; v_actor uuid; v_role text; v_prior text;
begin
  if tg_op = 'INSERT' then
    v_action := 'protection_alert.generated';    v_actor := NEW.generated_by;    v_prior := null;
  elsif NEW.status = 'ACKNOWLEDGED' and OLD.status = 'OPEN' then
    v_action := 'protection_alert.acknowledged'; v_actor := NEW.acknowledged_by; v_prior := OLD.status;
  elsif NEW.status = 'RESOLVED' and OLD.status <> 'RESOLVED' then
    v_action := 'protection_alert.resolved';     v_actor := NEW.resolved_by;     v_prior := OLD.status;
  else
    return NEW;  -- idempotent no-op update ⇒ no audit row
  end if;

  select u.role::text into v_role from public.users u where u.id = v_actor;

  insert into public.audit_events (
    event_id, event_type, event_category, action,
    resource_type, resource_id, user_id, user_role, casino_id,
    severity, outcome, metadata)
  values (
    'ppa:' || v_action || ':' || NEW.id::text,
    v_action, 'responsible_gambling', v_action,
    'player_protection_alert', NEW.id::text, v_actor, v_role, NEW.casino_id,
    'info', 'success',
    jsonb_build_object(
      'alert_type', NEW.alert_type, 'rule_version', NEW.rule_version,
      'prior_status', v_prior, 'new_status', NEW.status,
      'self_exclusion_id', NEW.self_exclusion_id, 'intervention_id', NEW.intervention_id));
  return NEW;
end $$;


ALTER FUNCTION public.sbiq_ppa_audit() OWNER TO postgres;

--
-- Name: sbiq_ppa_validate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_ppa_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_player_casino uuid;
  v_se_status     text;
  v_se_breach     integer;
  v_fur           boolean;
  v_fud           date;
begin
  if tg_op = 'INSERT' then
    if NEW.status <> 'OPEN'
       or NEW.acknowledged_at is not null or NEW.acknowledged_by is not null
       or NEW.resolved_at is not null or NEW.resolved_by is not null then
      raise exception 'B4.1: new alert must begin OPEN with no lifecycle attribution';
    end if;
    if NEW.generated_by is null then
      raise exception 'B4.1: generated_by is required';
    end if;

    select p.casino_id into v_player_casino from public.players p where p.id = NEW.player_id;
    if v_player_casino is null or v_player_casino <> NEW.casino_id then
      raise exception 'B4.1: player % not in casino %', NEW.player_id, NEW.casino_id;
    end if;

    if NEW.alert_type = 'SELF_EXCLUSION_BREACH_REVIEW' then
      select s.status, s.breach_count into v_se_status, v_se_breach
      from public.self_exclusions s
      where s.id = NEW.self_exclusion_id
        and s.casino_id = NEW.casino_id
        and s.player_id = NEW.player_id;
      if not found or v_se_status is distinct from 'breached' then
        raise exception 'B4.1: self_exclusion % not an eligible breached row for casino %/player %',
          NEW.self_exclusion_id, NEW.casino_id, NEW.player_id;
      end if;
      -- DB-generated immutable evidence (overwrites any caller value); NULL breach_count kept honest
      NEW.evidence := jsonb_build_object(
        'rule_version', NEW.rule_version,
        'self_exclusion_status', v_se_status,
        'breach_count', v_se_breach);

    elsif NEW.alert_type = 'INTERVENTION_FOLLOW_UP_OVERDUE' then
      select i.follow_up_required, i.follow_up_date into v_fur, v_fud
      from public.player_protection_interventions i
      where i.id = NEW.intervention_id
        and i.casino_id = NEW.casino_id
        and i.player_id = NEW.player_id;
      if not found
         or v_fur is not true
         or v_fud is null
         or not (v_fud < (now() at time zone 'Africa/Johannesburg')::date) then
        raise exception 'B4.1: intervention % not an eligible overdue follow-up for casino %/player %',
          NEW.intervention_id, NEW.casino_id, NEW.player_id;
      end if;
      NEW.evidence := jsonb_build_object(
        'rule_version', NEW.rule_version,
        'follow_up_date', v_fud);
    end if;

    -- DB-authoritative timestamps (overwrite any caller-supplied values)
    NEW.generated_at := now();
    NEW.created_at   := now();
    NEW.updated_at   := now();
    return NEW;
  end if;

  -- UPDATE: id / identity / evidence / generation are immutable
  if NEW.id             is distinct from OLD.id
     or NEW.casino_id       is distinct from OLD.casino_id
     or NEW.player_id       is distinct from OLD.player_id
     or NEW.alert_type      is distinct from OLD.alert_type
     or NEW.rule_version    is distinct from OLD.rule_version
     or NEW.self_exclusion_id  is distinct from OLD.self_exclusion_id
     or NEW.intervention_id    is distinct from OLD.intervention_id
     or NEW.evidence        is distinct from OLD.evidence
     or NEW.generated_at    is distinct from OLD.generated_at
     or NEW.generated_by    is distinct from OLD.generated_by
     or NEW.created_at      is distinct from OLD.created_at then
    raise exception 'B4.1: immutable column changed on alert %', OLD.id;
  end if;

  -- legal transitions only (no reverse / no reopen)
  if not (
       (OLD.status = 'OPEN'         and NEW.status in ('OPEN','ACKNOWLEDGED','RESOLVED'))
    or (OLD.status = 'ACKNOWLEDGED' and NEW.status in ('ACKNOWLEDGED','RESOLVED'))
    or (OLD.status = 'RESOLVED'     and NEW.status =  'RESOLVED')
  ) then
    raise exception 'B4.1: illegal transition % -> % on alert %', OLD.status, NEW.status, OLD.id;
  end if;

  -- acknowledgement attribution may change ONLY on OPEN->ACKNOWLEDGED; timestamp DB-set there
  if OLD.status = 'OPEN' and NEW.status = 'ACKNOWLEDGED' then
    if NEW.acknowledged_by is null then
      raise exception 'B4.1: acknowledged_by required on OPEN->ACKNOWLEDGED';
    end if;
    NEW.acknowledged_at := now();                 -- DB-authoritative (overwrite)
  else
    if NEW.acknowledged_at is distinct from OLD.acknowledged_at
       or NEW.acknowledged_by is distinct from OLD.acknowledged_by then
      raise exception 'B4.1: acknowledgement attribution may change only on OPEN->ACKNOWLEDGED';
    end if;
  end if;

  -- resolution attribution may change ONLY on ->RESOLVED (from OPEN/ACKNOWLEDGED); timestamp DB-set
  if NEW.status = 'RESOLVED' and OLD.status in ('OPEN','ACKNOWLEDGED') then
    if NEW.resolved_by is null then
      raise exception 'B4.1: resolved_by required on ->RESOLVED';
    end if;
    NEW.resolved_at := now();                     -- DB-authoritative (overwrite)
  else
    if NEW.resolved_at is distinct from OLD.resolved_at
       or NEW.resolved_by is distinct from OLD.resolved_by then
      raise exception 'B4.1: resolution attribution may change only on ->RESOLVED';
    end if;
  end if;

  -- updated_at bumps only on a real transition; a true no-op preserves it
  if NEW.status is distinct from OLD.status then
    NEW.updated_at := now();
  else
    NEW.updated_at := OLD.updated_at;
  end if;
  return NEW;
end $$;


ALTER FUNCTION public.sbiq_ppa_validate() OWNER TO postgres;

--
-- Name: sbiq_regulator_national(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_regulator_national(p_jurisdiction text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with ops as (select * from sbiq_regulator_operators(p_jurisdiction))
  select jsonb_build_object(
    'jurisdiction', p_jurisdiction,
    'operators', (select count(*) from ops),
    'players_active_now', (select coalesce(sum(players_active_now),0) from ops),
    'observed_players', (select coalesce(sum(active_players),0) from ops),
    'active_players', (select coalesce(sum(active_players),0) from ops),  -- retained: observed (back-compat)
    'active_sessions', (select coalesce(sum(active_sessions),0) from ops),
    'active_machines', (select coalesce(sum(active_machines),0) from ops),
    'risk_critical', (select coalesce(sum(risk_critical),0) from ops),
    'risk_high', (select coalesce(sum(risk_high),0) from ops),
    'risk_medium', (select coalesce(sum(risk_medium),0) from ops),
    'risk_low', (select coalesce(sum(risk_low),0) from ops),
    'total_wagered', (select coalesce(sum(total_wagered),0) from ops),
    'ggr', (select coalesce(sum(ggr),0) from ops),
    'players_monitored', (select coalesce(sum(players_monitored),0) from ops),
    'interventions', (select coalesce(sum(interventions),0) from ops),
    'last_event_at', (select max(last_event_at) from ops),
    'operators_detail', (select coalesce(jsonb_agg(to_jsonb(o)), '[]'::jsonb) from ops o)
  );
$$;


ALTER FUNCTION public.sbiq_regulator_national(p_jurisdiction text) OWNER TO postgres;

--
-- Name: sbiq_regulator_operators(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_regulator_operators(p_jurisdiction text) RETURNS TABLE(casino_id uuid, casino_name text, province text, active_players integer, players_active_now integer, players_idle integer, players_stale integer, active_sessions integer, active_machines integer, risk_critical integer, risk_high integer, risk_medium integer, risk_low integer, total_wagered numeric, ggr numeric, players_monitored bigint, interventions bigint, last_event_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.id, c.name, c.province,
    coalesce(cs.active_players,0),        -- observed (players in the activity projection)
    coalesce(cs.players_active_now,0),    -- certified freshness-based active-now
    coalesce(cs.players_idle,0), coalesce(cs.players_stale,0),
    coalesce(cs.active_sessions,0), coalesce(cs.active_machines,0),
    coalesce(cs.risk_critical,0), coalesce(cs.risk_high,0), coalesce(cs.risk_medium,0), coalesce(cs.risk_low,0),
    coalesce(cs.total_wagered,0), coalesce(cs.ggr,0),
    (select count(*) from projection_compliance_state cp where cp.casino_id=c.id),
    (select count(*) from projection_intervention_state iv where iv.casino_id=c.id),
    cs.last_event_at
  from casinos c left join projection_casino_state cs on cs.casino_id=c.id
  where c.jurisdiction=p_jurisdiction order by c.name;
$$;


ALTER FUNCTION public.sbiq_regulator_operators(p_jurisdiction text) OWNER TO postgres;

--
-- Name: sbiq_run_audit_verification(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_run_audit_verification(p_mode text DEFAULT 'incremental'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_scope text; v_run text; v_res jsonb; v_start timestamptz; v_status text;
        v_verified int := 0; v_broken int := 0; v_total int := 0;
begin
  for v_scope in select chain_scope from audit_chain_head order by chain_scope loop
    v_total := v_total + 1; v_run := gen_random_uuid()::text; v_start := clock_timestamp();
    v_res := sbiq_verify_audit_chain(v_scope); v_status := v_res->>'status';
    insert into audit_verification_run (run_id, chain_scope, mode, last_sequence, events_checked, expected_head, actual_head, result, first_failing_sequence, failure_reason, started_at, completed_at, duration_ms)
    values (v_run, v_scope, p_mode, (v_res->>'last_sequence')::bigint, (v_res->>'events_checked')::bigint, v_res->>'expected_head', (select head_hash from audit_chain_head where chain_scope=v_scope), v_status, (v_res->>'first_failing_sequence')::bigint, v_res->>'reason', v_start, clock_timestamp(), round(extract(milliseconds from clock_timestamp()-v_start))::int);
    if v_status = 'verified' then
      v_verified := v_verified + 1;
      insert into audit_chain_checkpoint (chain_scope, verified_through_sequence, verified_head_hash, verification_run_id, result, verifier_version, verified_at)
      values (v_scope, (v_res->>'last_sequence')::bigint, v_res->>'expected_head', v_run, 'verified', 'sql-v1', now())
      on conflict (chain_scope) do update set verified_through_sequence=excluded.verified_through_sequence, verified_head_hash=excluded.verified_head_hash, verification_run_id=excluded.verification_run_id, result='verified', verified_at=now();
    else
      v_broken := v_broken + 1;
      insert into platform_integrity_alert (chain_scope, first_failing_sequence, failure_category, verification_run_id, severity)
      values (v_scope, (v_res->>'first_failing_sequence')::bigint, v_res->>'reason', v_run, 'critical');
      update audit_chain_checkpoint set result='broken', verified_at=now() where chain_scope=v_scope;
    end if;
  end loop;
  return jsonb_build_object('mode',p_mode,'chains',v_total,'verified',v_verified,'broken',v_broken,'ran_at',now());
end $$;


ALTER FUNCTION public.sbiq_run_audit_verification(p_mode text) OWNER TO postgres;

--
-- Name: sbiq_seed_demo_financials(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_seed_demo_financials(p_casino uuid, p_player text DEFAULT 'SB-PLR-859D2993145EFF36E3FC3986'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  spec record; n int := 0;
begin
  for spec in
    select * from (values
      ('10 minutes'::interval, 250::numeric, 0::numeric,   'shift-1'),
      ('35 minutes'::interval, 500::numeric, 180::numeric, 'shift-2'),
      ('90 minutes'::interval, 300::numeric, 300::numeric, 'today-1'),
      ('6 hours'::interval,    750::numeric, 200::numeric, 'today-2'),
      ('3 days'::interval,     400::numeric, 0::numeric,   'mtd-1'),
      ('12 days'::interval,    600::numeric, 950::numeric, 'mtd-2')
    ) as t(off_ago, stake, win, tag)
  loop
    insert into casino_event_log (event_id, correlation_id, trace_id, tenant_id, casino_id, jurisdiction,
      safebet_player_id, session_id, machine_id, producer, schema_version, event_type,
      occurred_at, received_at, processed_at, replay_number, dedupe_key, payload)
    values (
      md5('sbiq-fin-demo:'||p_casino::text||':'||spec.tag)::uuid,
      'fin-demo', '11111111-1111-4111-8111-111111111111', p_casino, p_casino, 'ZA',
      p_player, 'fin-demo-session', 'M-001', 'sbiq-demo-fin-sim', 1, 'BET_PLACED',
      now() - spec.off_ago, now(), now(), 0,
      'fin-demo:'||p_casino::text||':'||spec.tag,
      jsonb_build_object('bet_amount', spec.stake, 'win_amount', spec.win,
        'currency','ZAR','game_type','slots','is_simulated', true, 'synthetic', true))
    on conflict do nothing;
    n := n + 1;
  end loop;
  insert into audit_events (event_id, event_type, event_category, action, resource_type, resource_id,
    casino_id, description, severity, outcome, metadata)
  values ('seed:'||p_casino::text||':'||gen_random_uuid()::text, 'SYNTHETIC_FINANCIAL_SEED', 'governance',
    'seed', 'financial.synthetic', p_casino::text, p_casino,
    'synthetic financial events seeded (demo)', 'notice', 'success',
    jsonb_build_object('events', n, 'player', p_player));
  return n;
end $$;


ALTER FUNCTION public.sbiq_seed_demo_financials(p_casino uuid, p_player text) OWNER TO postgres;

--
-- Name: sbiq_session_policy(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_session_policy(p_casino uuid) RETURNS TABLE(idle_after_minutes integer, stale_after_minutes integer, concurrency_limit integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select idle_after_minutes, stale_after_minutes, concurrency_limit
  from (
    select 1 as pref, idle_after_minutes, stale_after_minutes, concurrency_limit
      from session_lifecycle_policy where scope='casino' and casino_id = p_casino
    union all
    select 2 as pref, idle_after_minutes, stale_after_minutes, concurrency_limit
      from session_lifecycle_policy where scope='platform' and casino_id is null
  ) t order by pref limit 1;
$$;


ALTER FUNCTION public.sbiq_session_policy(p_casino uuid) OWNER TO postgres;

--
-- Name: sbiq_supersede_prior_sessions(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_supersede_prior_sessions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update projection_session_state prior
     set status = 'ended',
         ended_at = coalesce(NEW.started_at, now()),
         ended_reason = 'superseded',
         updated_at = now()
   where prior.casino_id = NEW.casino_id
     and prior.safebet_player_id = NEW.safebet_player_id
     and prior.session_id <> NEW.session_id
     and prior.status = 'active'
     and coalesce(prior.started_at, 'epoch'::timestamptz) <= coalesce(NEW.started_at, now());
  return NEW;
end $$;


ALTER FUNCTION public.sbiq_supersede_prior_sessions() OWNER TO postgres;

--
-- Name: sbiq_verify_audit_chain(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_verify_audit_chain(p_scope text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare r record; v_prev text := repeat('0',64); v_seq bigint := 0; v_expected text; n bigint := 0;
begin
  if auth.uid() is not null and not sbiq_may_access_chain_scope(p_scope) then
    return jsonb_build_object('scope',p_scope,'status','unavailable','reason','not authorised for this chain scope','verified_at',now()); end if;
  for r in select * from audit_events where chain_scope = p_scope order by chain_sequence asc loop
    v_seq := v_seq + 1; n := n + 1;
    if r.chain_sequence <> v_seq then return jsonb_build_object('scope',p_scope,'status','broken','events_checked',n,'first_failing_sequence',r.chain_sequence,'reason','sequence gap or duplicate','verified_at',now()); end if;
    if r.previous_hash <> v_prev then return jsonb_build_object('scope',p_scope,'status','broken','events_checked',n,'first_failing_sequence',r.chain_sequence,'reason','previous_hash linkage broken','verified_at',now()); end if;
    v_expected := sbiq_audit_event_hash('v1',p_scope,r.chain_sequence,r.previous_hash,r.event_id,r.event_type,r.user_id::text,r.user_role,r.casino_id::text,r.resource_type,r.resource_id,r.outcome,r.created_at,r.correlation_id,r.metadata);
    if r.hash <> v_expected then return jsonb_build_object('scope',p_scope,'status','broken','events_checked',n,'first_failing_sequence',r.chain_sequence,'reason','recomputed hash mismatch','verified_at',now()); end if;
    v_prev := r.hash;
  end loop;
  if exists (select 1 from audit_chain_head h where h.chain_scope=p_scope and h.head_hash <> v_prev) then
    return jsonb_build_object('scope',p_scope,'status','broken','events_checked',n,'reason','chain head mismatch','verified_at',now()); end if;
  return jsonb_build_object('scope',p_scope,'status','verified','events_checked',n,'last_sequence',v_seq,'expected_head',v_prev,'verified_at',now());
end $$;


ALTER FUNCTION public.sbiq_verify_audit_chain(p_scope text) OWNER TO postgres;

--
-- Name: sbiq_verify_audit_chain_range(text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_verify_audit_chain_range(p_scope text, p_from bigint DEFAULT NULL::bigint, p_to bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare r record; v_prev text := repeat('0',64); v_seq bigint := 0; v_expected text; n bigint := 0; v_first bigint; v_last bigint;
begin
  if auth.uid() is not null and not sbiq_may_access_chain_scope(p_scope) then
    return jsonb_build_object('scope',p_scope,'status','unavailable','reason','not authorised for this chain scope'); end if;
  for r in select * from audit_events where chain_scope = p_scope order by chain_sequence asc loop
    v_seq := v_seq + 1;
    if r.chain_sequence <> v_seq then return jsonb_build_object('scope',p_scope,'status','broken','events_checked',n,'first_failing_sequence',r.chain_sequence,'reason','sequence gap or duplicate'); end if;
    if r.previous_hash <> v_prev then return jsonb_build_object('scope',p_scope,'status','broken','events_checked',n,'first_failing_sequence',r.chain_sequence,'reason','previous_hash linkage broken'); end if;
    v_expected := sbiq_audit_event_hash('v1',p_scope,r.chain_sequence,r.previous_hash,r.event_id,r.event_type,r.user_id::text,r.user_role,r.casino_id::text,r.resource_type,r.resource_id,r.outcome,r.created_at,r.correlation_id,r.metadata);
    if r.hash <> v_expected then return jsonb_build_object('scope',p_scope,'status','broken','events_checked',n,'first_failing_sequence',r.chain_sequence,'reason','recomputed hash mismatch'); end if;
    if (p_from is null or r.chain_sequence >= p_from) and (p_to is null or r.chain_sequence <= p_to) then
      n := n + 1; if v_first is null then v_first := r.chain_sequence; end if; v_last := r.chain_sequence; end if;
    v_prev := r.hash;
  end loop;
  return jsonb_build_object('scope',p_scope,'status','verified','events_checked',n,'requested_from',p_from,'requested_to',p_to,'verified_from',v_first,'verified_to',v_last,'expected_head',v_prev,'verified_at',now());
end $$;


ALTER FUNCTION public.sbiq_verify_audit_chain_range(p_scope text, p_from bigint, p_to bigint) OWNER TO postgres;

--
-- Name: sbiq_workflow_operations(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_workflow_operations(p_casino uuid DEFAULT NULL::uuid, p_jurisdiction text DEFAULT NULL::text) RETURNS TABLE(casino_id uuid, casino_name text, jurisdiction text, open_cases bigint, overdue_cases bigint, resolved_cases bigint, investigations_open bigint, compliance_tasks bigint, compliance_completed bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    c.id, c.name, c.jurisdiction,
    (select count(*) from workflow_cases w where w.casino_id = c.id
       and w.status not in ('resolved','closed','rejected')),
    (select count(*) from workflow_cases w where w.casino_id = c.id
       and w.due_at is not null and w.due_at < now()
       and w.status not in ('resolved','closed','rejected')),
    (select count(*) from workflow_cases w where w.casino_id = c.id
       and w.status in ('resolved','closed')),
    (select count(*) from workflow_cases w where w.casino_id = c.id
       and w.case_type = 'regulatory-investigation'
       and w.status not in ('resolved','closed','rejected')),
    (select count(*) from workflow_tasks t where t.casino_id = c.id and t.task_type = 'compliance-action'),
    (select count(*) from workflow_tasks t where t.casino_id = c.id and t.task_type = 'compliance-action' and t.status = 'completed')
  from casinos c
  where c.is_active
    and (p_casino is null or c.id = p_casino)
    and (p_jurisdiction is null or c.jurisdiction = p_jurisdiction)
  order by c.name;
$$;


ALTER FUNCTION public.sbiq_workflow_operations(p_casino uuid, p_jurisdiction text) OWNER TO postgres;

--
-- Name: sbiq_write_projection_states(uuid, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sbiq_write_projection_states(p_casino uuid, p_players jsonb DEFAULT '[]'::jsonb, p_sessions jsonb DEFAULT '[]'::jsonb, p_machines jsonb DEFAULT '[]'::jsonb) RETURNS TABLE(ok boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  elem   jsonb;
  prec   projection_player_state%rowtype;
  srec   projection_session_state%rowtype;
  mrec   projection_machine_state%rowtype;
  cur    bigint;
begin
  perform pg_advisory_xact_lock(hashtext(p_casino::text));

  for elem in select * from jsonb_array_elements(p_players) loop
    prec := jsonb_populate_record(null::projection_player_state, elem);
    select row_version into cur from projection_player_state
      where casino_id = prec.casino_id and safebet_player_id = prec.safebet_player_id;
    if found then
      if cur <> prec.row_version then ok := false; return next; return; end if;
    elsif prec.row_version <> 0 then ok := false; return next; return;
    end if;
  end loop;

  for elem in select * from jsonb_array_elements(p_sessions) loop
    srec := jsonb_populate_record(null::projection_session_state, elem);
    select row_version into cur from projection_session_state where session_id = srec.session_id;
    if found then
      if cur <> srec.row_version then ok := false; return next; return; end if;
    elsif srec.row_version <> 0 then ok := false; return next; return;
    end if;
  end loop;

  for elem in select * from jsonb_array_elements(p_machines) loop
    mrec := jsonb_populate_record(null::projection_machine_state, elem);
    select row_version into cur from projection_machine_state
      where casino_id = mrec.casino_id and machine_id = mrec.machine_id;
    if found then
      if cur <> mrec.row_version then ok := false; return next; return; end if;
    elsif mrec.row_version <> 0 then ok := false; return next; return;
    end if;
  end loop;

  for elem in select * from jsonb_array_elements(p_players) loop
    prec := jsonb_populate_record(null::projection_player_state, elem);
    prec.row_version := prec.row_version + 1;
    insert into projection_player_state values (prec.*)
      on conflict (casino_id, safebet_player_id) do update set
        status = excluded.status, current_session_id = excluded.current_session_id,
        current_machine_id = excluded.current_machine_id, risk_score = excluded.risk_score,
        risk_flags = excluded.risk_flags, total_wagered = excluded.total_wagered,
        total_won = excluded.total_won, bet_count = excluded.bet_count,
        session_count = excluded.session_count, intervention_count = excluded.intervention_count,
        last_intervention_at = excluded.last_intervention_at, last_event_id = excluded.last_event_id,
        last_event_at = excluded.last_event_at, projection_version = excluded.projection_version,
        row_version = excluded.row_version, updated_at = excluded.updated_at;
  end loop;

  for elem in select * from jsonb_array_elements(p_sessions) loop
    srec := jsonb_populate_record(null::projection_session_state, elem);
    srec.row_version := srec.row_version + 1;
    insert into projection_session_state values (srec.*)
      on conflict (session_id) do update set
        casino_id = excluded.casino_id, safebet_player_id = excluded.safebet_player_id,
        machine_id = excluded.machine_id, status = excluded.status, game_type = excluded.game_type,
        started_at = excluded.started_at, ended_at = excluded.ended_at,
        total_wagered = excluded.total_wagered, total_won = excluded.total_won,
        bet_count = excluded.bet_count, risk_score = excluded.risk_score,
        last_event_id = excluded.last_event_id, last_event_at = excluded.last_event_at,
        projection_version = excluded.projection_version, row_version = excluded.row_version,
        updated_at = excluded.updated_at;
  end loop;

  for elem in select * from jsonb_array_elements(p_machines) loop
    mrec := jsonb_populate_record(null::projection_machine_state, elem);
    mrec.row_version := mrec.row_version + 1;
    insert into projection_machine_state values (mrec.*)
      on conflict (casino_id, machine_id) do update set
        machine_type = excluded.machine_type, floor_location = excluded.floor_location,
        status = excluded.status, current_player_id = excluded.current_player_id,
        current_session_id = excluded.current_session_id, current_risk_score = excluded.current_risk_score,
        session_wagered = excluded.session_wagered, last_event_id = excluded.last_event_id,
        last_event_at = excluded.last_event_at, projection_version = excluded.projection_version,
        row_version = excluded.row_version, updated_at = excluded.updated_at;
  end loop;

  ok := true; return next;
end;
$$;


ALTER FUNCTION public.sbiq_write_projection_states(p_casino uuid, p_players jsonb, p_sessions jsonb, p_machines jsonb) OWNER TO postgres;

--
-- Name: set_assessment_number(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_assessment_number() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.assessment_number := (
    SELECT COALESCE(MAX(assessment_number), 0) + 1
    FROM wellbeing_assessments
    WHERE player_id = NEW.player_id
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.set_assessment_number() OWNER TO postgres;

--
-- Name: simulate_live_feed(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.simulate_live_feed() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
v_ended   int := 0;
v_started int := 0;
v_events  int := 0;

v_edges     jsonb := '{"slots":0.055,"blackjack":0.005,"roulette":0.027,"poker":0.030,"baccarat":0.012}'::jsonb;
v_bet_rates jsonb := '{"slots":12,"blackjack":4,"roulette":3,"poker":2,"baccarat":5}'::jsonb;
v_bet_sizes jsonb := '{"slots":50,"blackjack":300,"roulette":175,"poker":400,"baccarat":225}'::jsonb;
v_machine_types text[] := ARRAY['slot','slot','slot','table','rng','live_dealer'];
BEGIN

-- 1. End sessions running > 3 hours
UPDATE gaming_sessions
SET is_active = false, end_time = NOW(),
duration  = EXTRACT(EPOCH FROM (NOW() - start_time))::int / 60
WHERE is_active = true AND start_time < NOW() - INTERVAL '3 hours';
GET DIAGNOSTICS v_ended = ROW_COUNT;

-- 2. Natural churn ~3%
UPDATE gaming_sessions
SET is_active = false, end_time = NOW(),
duration  = EXTRACT(EPOCH FROM (NOW() - start_time))::int / 60
WHERE id IN (
SELECT id FROM gaming_sessions WHERE is_active = true AND random() < 0.03 LIMIT 50
);

-- 3. Start new sessions for casinos with fewer than 25 active
INSERT INTO gaming_sessions (
id, player_id, casino_id, game_type,
start_time, end_time, duration,
total_bets, total_wagered, total_won, net_result,
risk_score_change, is_active, created_at
)
SELECT
gen_random_uuid(), p.id, p.casino_id,
(ARRAY['slots','blackjack','roulette','poker','baccarat'])[1 + floor(random()*5)::int],
NOW() - (random() * INTERVAL '20 minutes'),
NULL, 0, 0, 0, 0, 0, 0, true, NOW()
FROM players p
WHERE p.status = 'active'
AND p.is_active = true
AND p.casino_id IN (
SELECT casino_id FROM gaming_sessions
WHERE is_active = true
GROUP BY casino_id HAVING COUNT(*) < 25
UNION
SELECT id FROM casinos
WHERE id NOT IN (SELECT DISTINCT casino_id FROM gaming_sessions WHERE is_active = true)
)
AND p.id NOT IN (
SELECT player_id FROM gaming_sessions WHERE is_active = true
)
ORDER BY p.casino_id, random()
LIMIT 50;
GET DIAGNOSTICS v_started = ROW_COUNT;

-- 4. Emit live_events for up to 200 active sessions
WITH active_sample AS (
SELECT gs.id AS sess_id, gs.player_id, gs.casino_id, gs.game_type,
gs.total_wagered AS sess_wagered, gs.total_won AS sess_won,
gs.total_bets AS sess_bets, gs.start_time,
p.first_name || ' ' || p.last_name AS player_name,
p.risk_score AS player_risk
FROM gaming_sessions gs
JOIN players p ON p.id = gs.player_id
WHERE gs.is_active = true
LIMIT 200
),
calc AS (
SELECT s.*,
'M-' || LPAD((ABS(hashtext(s.player_id::text || s.casino_id::text)) % 80 + 1)::text, 3, '0') AS machine_id,
GREATEST(1, ROUND((v_bet_sizes->>s.game_type)::numeric * (0.8 + random()*0.4)))::numeric AS bet_amt,
(random() > (v_edges->>s.game_type)::numeric * 3) AS is_win,
(s.sess_wagered > 3000 AND s.sess_won < s.sess_wagered * 0.4) AS flag_loss,
(s.sess_bets > 50 AND s.sess_wagered > 5000) AS flag_esc,
LEAST(100, GREATEST(0, s.player_risk + floor(random()*15)::int)) AS risk_val
FROM active_sample s
)
INSERT INTO live_events (
id, event_id, event_type, casino_id, player_id, session_id,
game_id, machine_id, bet_amount, win_amount, balance_after,
duration_seconds, risk_score, risk_flags, outcome,
game_type, is_simulated, metadata, created_at
)
SELECT
gen_random_uuid(), gen_random_uuid(), 'BET_PLACED',
c.casino_id, c.player_id::text, c.sess_id::text,
'GAME-' || upper(c.game_type) || '-' || (floor(random()*100+1)::int)::text,
c.machine_id, c.bet_amt,
CASE WHEN c.is_win THEN ROUND(c.bet_amt * (1.5 + random()*1.5)) ELSE 0 END,
NULL,
EXTRACT(EPOCH FROM NOW() - c.start_time)::int,
c.risk_val,
CASE WHEN c.flag_loss AND c.flag_esc THEN '["loss_chasing","bet_escalation"]'::jsonb
WHEN c.flag_loss THEN '["loss_chasing"]'::jsonb
WHEN c.flag_esc  THEN '["bet_escalation"]'::jsonb
ELSE '[]'::jsonb END,
CASE WHEN c.is_win THEN 'win' ELSE 'loss' END,
c.game_type, true,
jsonb_build_object('player_name', c.player_name),
NOW() - (random() * INTERVAL '30 seconds')
FROM calc c;
GET DIAGNOSTICS v_events = ROW_COUNT;

-- 5. Update session totals
UPDATE gaming_sessions
SET total_bets    = total_bets + act.nb,
total_wagered = total_wagered + act.nw,
total_won     = total_won + act.nwo,
net_result    = (total_won + act.nwo) - (total_wagered + act.nw),
duration      = EXTRACT(EPOCH FROM (NOW() - start_time))::int / 60
FROM (
SELECT id,
GREATEST(1, ROUND((v_bet_rates->>game_type)::numeric * (0.5 + random())))::int AS nb,
GREATEST(1, ROUND((v_bet_sizes->>game_type)::numeric * (0.8 + random()*0.4)))::numeric AS nw,
GREATEST(0, ROUND((v_bet_sizes->>game_type)::numeric * (0.6 + random()*0.8) *
(1.0 - (v_edges->>game_type)::numeric)))::numeric AS nwo
FROM gaming_sessions WHERE is_active = true LIMIT 200
) act
WHERE gaming_sessions.id = act.id;

-- 6. Upsert machine_activity
INSERT INTO machine_activity (
id, casino_id, machine_id, machine_type,
current_player_id, session_start, status,
spins_per_minute, current_risk_score, total_wagered_session,
is_simulated, updated_at, created_at
)
SELECT
gen_random_uuid(), gs.casino_id,
'M-' || LPAD((ABS(hashtext(gs.player_id::text || gs.casino_id::text)) % 80 + 1)::text, 3, '0'),
v_machine_types[1 + (ABS(hashtext(gs.player_id::text)) % array_length(v_machine_types, 1))],
gs.player_id::text, gs.start_time, 'active',
ROUND(((v_bet_rates->>gs.game_type)::numeric * (0.7 + random()*0.6))::numeric, 1),
LEAST(100, GREATEST(0, p.risk_score + floor(random()*15)::int)),
gs.total_wagered, true, NOW(), NOW()
FROM gaming_sessions gs
JOIN players p ON p.id = gs.player_id
WHERE gs.is_active = true LIMIT 100
ON CONFLICT (casino_id, machine_id) DO UPDATE SET
current_player_id     = EXCLUDED.current_player_id,
status                = 'active',
spins_per_minute      = EXCLUDED.spins_per_minute,
current_risk_score    = EXCLUDED.current_risk_score,
total_wagered_session = EXCLUDED.total_wagered_session,
updated_at            = NOW();

-- 7. KPI snapshot
INSERT INTO live_kpi_snapshots (
id, casino_id, snapshot_at, active_players, events_per_min,
total_wagered, total_won, ggr, avg_bet_size,
risk_critical, risk_high, risk_medium, risk_low,
active_machines, is_simulated, created_at
)
SELECT gen_random_uuid(), le.casino_id, NOW(),
COUNT(DISTINCT le.player_id), COUNT(*),
COALESCE(SUM(le.bet_amount),0), COALESCE(SUM(le.win_amount),0),
COALESCE(SUM(le.bet_amount)-SUM(le.win_amount),0), COALESCE(AVG(le.bet_amount),0),
COUNT(*) FILTER (WHERE le.risk_score >= 80),
COUNT(*) FILTER (WHERE le.risk_score >= 60 AND le.risk_score < 80),
COUNT(*) FILTER (WHERE le.risk_score >= 40 AND le.risk_score < 60),
COUNT(*) FILTER (WHERE le.risk_score < 40),
(SELECT COUNT(*) FROM machine_activity ma WHERE ma.casino_id = le.casino_id AND ma.status = 'active'),
true, NOW()
FROM live_events le
WHERE le.created_at >= NOW() - INTERVAL '2 minutes'
GROUP BY le.casino_id;

-- 8. Cleanup
DELETE FROM live_events        WHERE created_at  < NOW() - INTERVAL '2 hours';
DELETE FROM live_kpi_snapshots WHERE snapshot_at < NOW() - INTERVAL '24 hours';

RETURN jsonb_build_object(
'tick_at', NOW(), 'ended', v_ended,
'started', v_started, 'events', v_events
);
END;
$$;


ALTER FUNCTION public.simulate_live_feed() OWNER TO postgres;

--
-- Name: sync_casino_id_from_player(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_casino_id_from_player() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
player_casino_id uuid;
BEGIN
SELECT casino_id INTO player_casino_id
FROM players
WHERE id = NEW.player_id;

IF player_casino_id IS NOT NULL AND (NEW.casino_id IS NULL OR NEW.casino_id != player_casino_id) THEN
NEW.casino_id := player_casino_id;
END IF;

RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_casino_id_from_player() OWNER TO postgres;

