--
-- Name: update_enrollment_progress(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_enrollment_progress() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE total_lessons int; completed_lessons int; new_progress decimal;
BEGIN SELECT COUNT(*) INTO total_lessons FROM training_lessons WHERE module_id = (SELECT module_id FROM training_enrollments WHERE id = NEW.enrollment_id);
SELECT COUNT(*) INTO completed_lessons FROM training_lesson_progress WHERE enrollment_id = NEW.enrollment_id AND completed = true;
IF total_lessons > 0 THEN new_progress := (completed_lessons::decimal / total_lessons::decimal) * 100;
UPDATE training_enrollments SET progress_percentage = new_progress::integer, 
status = CASE WHEN new_progress >= 100 THEN 'completed' WHEN new_progress > 0 THEN 'in_progress' ELSE status END,
completed_at = CASE WHEN new_progress >= 100 AND completed_at IS NULL THEN NOW() ELSE completed_at END WHERE id = NEW.enrollment_id; END IF;
RETURN NEW; END; $$;


ALTER FUNCTION public.update_enrollment_progress() OWNER TO postgres;

--
-- Name: update_global_player_metrics(uuid, numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_global_player_metrics(p_global_identity_id uuid, p_deposit_delta numeric DEFAULT 0, p_loss_delta numeric DEFAULT 0, p_bet_delta integer DEFAULT 0) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO global_player_metrics (
    global_identity_id,
    total_deposits,
    total_losses,
    total_bets,
    last_activity_at
  )
  VALUES (
    p_global_identity_id,
    p_deposit_delta,
    p_loss_delta,
    p_bet_delta,
    now()
  )
  ON CONFLICT (global_identity_id)
    DO UPDATE SET
      total_deposits   = global_player_metrics.total_deposits   + excluded.total_deposits,
      total_losses     = global_player_metrics.total_losses     + excluded.total_losses,
      total_bets       = global_player_metrics.total_bets       + excluded.total_bets,
      last_activity_at = now();

  PERFORM recalculate_grpi_risk_score(p_global_identity_id);
END;
$$;


ALTER FUNCTION public.update_global_player_metrics(p_global_identity_id uuid, p_deposit_delta numeric, p_loss_delta numeric, p_bet_delta integer) OWNER TO postgres;

