--
-- Name: update_revenue_protection_monthly(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_revenue_protection_monthly() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
INSERT INTO revenue_protection_monthly (
casino_id,
month_start,
total_protected_revenue,
intervention_count,
average_intervention_value,
roi_percentage
)
SELECT
NEW.casino_id,
date_trunc('month', NEW.event_date),
NEW.protected_revenue,
1,
NEW.protected_revenue,
CASE 
WHEN NEW.intervention_cost > 0 
THEN ((NEW.protected_revenue - NEW.intervention_cost) / NEW.intervention_cost * 100)
ELSE 0
END
ON CONFLICT (casino_id, month_start)
DO UPDATE SET
total_protected_revenue = revenue_protection_monthly.total_protected_revenue + NEW.protected_revenue,
intervention_count = revenue_protection_monthly.intervention_count + 1,
average_intervention_value = (revenue_protection_monthly.total_protected_revenue + NEW.protected_revenue) / (revenue_protection_monthly.intervention_count + 1),
roi_percentage = CASE 
WHEN (revenue_protection_monthly.total_protected_revenue + NEW.protected_revenue) > 0
THEN ((revenue_protection_monthly.total_protected_revenue + NEW.protected_revenue) / NULLIF((revenue_protection_monthly.intervention_count + 1) * 100, 0) * 100)
ELSE 0
END,
updated_at = now();

RETURN NEW;
END;
$$;


ALTER FUNCTION public.update_revenue_protection_monthly() OWNER TO postgres;

