    last_used_at timestamp with time zone,
    expires_at timestamp with time zone,
    revoked_at timestamp with time zone,
    revoked_by uuid,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    rotation_count integer DEFAULT 0,
    deprecated_at timestamp with time zone,
    deprecation_notice text,
    hard_cutoff_at timestamp with time zone DEFAULT (now() + '90 days'::interval),
    auth_method text DEFAULT 'api_key'::text NOT NULL,
    use_count bigint DEFAULT 0 NOT NULL,
    deprecated_use_count bigint DEFAULT 0 NOT NULL,
    last_deprecation_warning_at timestamp with time zone,
    CONSTRAINT api_tokens_auth_method_check CHECK ((auth_method = ANY (ARRAY['api_key'::text, 'hmac'::text])))
);


ALTER TABLE public.api_tokens OWNER TO postgres;

--
-- Name: COLUMN api_tokens.deprecated_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.api_tokens.deprecated_at IS 'When this token was flagged as deprecated. NULL = still supported fully.';


--
-- Name: COLUMN api_tokens.hard_cutoff_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.api_tokens.hard_cutoff_at IS 'After this date, api-ingest will reject this token with 401. Migrate to HMAC before then.';


--
-- Name: COLUMN api_tokens.auth_method; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.api_tokens.auth_method IS 'api_key = legacy SHA-256 hash lookup. hmac = HMAC-SHA256 per-request signing.';


--
-- Name: COLUMN api_tokens.deprecated_use_count; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.api_tokens.deprecated_use_count IS 'Number of requests made after deprecated_at. Used to track migration urgency per casino.';


