    CONSTRAINT audit_logs_environment_check CHECK ((environment = ANY (ARRAY['demo'::text, 'production'::text, 'staging'::text]))),
    CONSTRAINT audit_logs_log_type_check CHECK ((log_type = ANY (ARRAY['intervention'::text, 'risk_alert'::text, 'compliance_action'::text, 'session'::text, 'violation'::text, 'auth'::text, 'system'::text]))),
    CONSTRAINT audit_logs_resolution_status_check CHECK ((resolution_status = ANY (ARRAY['pending'::text, 'resolved'::text, 'escalated'::text, 'dismissed'::text]))),
    CONSTRAINT audit_logs_severity_check CHECK ((severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text])))
);


ALTER TABLE public.audit_logs OWNER TO postgres;

