--
-- Name: behavioral_risk_profiles; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.behavioral_risk_profiles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    player_id uuid NOT NULL,
    session_id uuid,
    casino_id uuid NOT NULL,
    risk_score integer DEFAULT 0 NOT NULL,
    risk_level text DEFAULT 'low'::text NOT NULL,
    impulse_level numeric(5,2) DEFAULT 0.00,
    betting_velocity numeric(10,2) DEFAULT 0.00,
    session_duration_minutes integer DEFAULT 0,
    reaction_time_ms integer DEFAULT 0,
    fatigue_index numeric(5,2) DEFAULT 0.00,
    personality_shift_score numeric(5,2) DEFAULT 0.00,
    emotional_state text DEFAULT 'neutral'::text,
    advised_break boolean DEFAULT false,
    intervention_triggered boolean DEFAULT false,
    intervention_accepted boolean DEFAULT false,
    analyzed_at timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    session_duration_score integer DEFAULT 0,
    deposit_frequency_score integer DEFAULT 0,
    loss_escalation_score integer DEFAULT 0,
    bet_intensity_score integer DEFAULT 0,
    cross_operator_score integer DEFAULT 0,
    signal_weights jsonb DEFAULT '{}'::jsonb,
    risk_rationale text DEFAULT ''::text,
    previous_risk_score integer DEFAULT 0,
    score_delta integer DEFAULT 0,
    sessions_analyzed integer DEFAULT 0,
    deposits_analyzed integer DEFAULT 0,
    cross_operator_flags integer DEFAULT 0,
    model_version text DEFAULT 'rule-based-v1'::text NOT NULL,
    model_confidence numeric(5,4),
    feature_vector jsonb,
    next_review_at timestamp with time zone,
    review_priority text DEFAULT 'normal'::text NOT NULL,
    flagged_for_review boolean DEFAULT false NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    review_notes text,
    CONSTRAINT behavioral_risk_profiles_fatigue_index_check CHECK (((fatigue_index >= (0)::numeric) AND (fatigue_index <= (100)::numeric))),
    CONSTRAINT behavioral_risk_profiles_impulse_level_check CHECK (((impulse_level >= (0)::numeric) AND (impulse_level <= (100)::numeric))),
    CONSTRAINT behavioral_risk_profiles_personality_shift_score_check CHECK (((personality_shift_score >= (0)::numeric) AND (personality_shift_score <= (100)::numeric))),
    CONSTRAINT behavioral_risk_profiles_review_priority_check CHECK ((review_priority = ANY (ARRAY['urgent'::text, 'high'::text, 'normal'::text, 'low'::text]))),
    CONSTRAINT behavioral_risk_profiles_risk_level_check CHECK ((risk_level = ANY (ARRAY['low'::text, 'moderate'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT behavioral_risk_profiles_risk_score_check CHECK (((risk_score >= 0) AND (risk_score <= 100))),
    CONSTRAINT bri_bet_intensity_score_range CHECK (((bet_intensity_score >= 0) AND (bet_intensity_score <= 100))),
    CONSTRAINT bri_cross_operator_score_range CHECK (((cross_operator_score >= 0) AND (cross_operator_score <= 100))),
    CONSTRAINT bri_deposit_frequency_score_range CHECK (((deposit_frequency_score >= 0) AND (deposit_frequency_score <= 100))),
    CONSTRAINT bri_loss_escalation_score_range CHECK (((loss_escalation_score >= 0) AND (loss_escalation_score <= 100))),
    CONSTRAINT bri_session_duration_score_range CHECK (((session_duration_score >= 0) AND (session_duration_score <= 100)))
);

ALTER TABLE ONLY public.behavioral_risk_profiles REPLICA IDENTITY FULL;


ALTER TABLE public.behavioral_risk_profiles OWNER TO postgres;

