-- Name: COLUMN behavioral_risk_profiles.model_version; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.behavioral_risk_profiles.model_version IS 'Version of the risk engine that produced this score. Enables A/B testing and auditability.';


--
