--
-- Name: intervention_player_communications; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.intervention_player_communications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    casino_id uuid NOT NULL,
    intervention_id uuid NOT NULL,
    communication_type text NOT NULL,
    purpose text NOT NULL,
    template_key text NOT NULL,
    template_version integer NOT NULL,
    delivery_mode text NOT NULL,
    channel_class text NOT NULL,
    sequence integer NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    requested_by uuid NOT NULL,
    request_idempotency_key uuid NOT NULL,
    request_fingerprint text NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    send_idempotency_key uuid,
    send_fingerprint text,
    send_requested_by uuid,
    send_requested_at timestamp with time zone,
    provider_reference text,
    submitted_at timestamp with time zone,
    delivered_at timestamp with time zone,
    failed_at timestamp with time zone,
    failure_class text,
    CONSTRAINT iplc_channel_class_chk CHECK ((channel_class = 'OPERATOR_MANAGED'::text)),
    CONSTRAINT iplc_communication_type_chk CHECK ((communication_type = ANY (ARRAY['LIMIT_CONFIRMATION'::text, 'TIMEOUT_CONFIRMATION'::text, 'SELF_EXCLUSION_SUPPORT'::text, 'HELPLINE_SUPPORT'::text, 'COUNSELLING_SUPPORT'::text]))),
    CONSTRAINT iplc_delivery_mode_chk CHECK ((delivery_mode = 'SANDBOX'::text)),
    CONSTRAINT iplc_failure_class_chk CHECK (((failure_class IS NULL) OR (failure_class = ANY (ARRAY['RECIPIENT_UNAVAILABLE'::text, 'CHANNEL_NOT_AVAILABLE'::text, 'PROVIDER_REJECTED'::text, 'TEMPORARY_FAILURE'::text, 'PERMANENT_FAILURE'::text, 'POLICY_BLOCKED'::text])))),
    CONSTRAINT iplc_lifecycle_chk CHECK (
CASE status
    WHEN 'PENDING'::text THEN ((send_idempotency_key IS NULL) AND (send_fingerprint IS NULL) AND (send_requested_by IS NULL) AND (send_requested_at IS NULL) AND (provider_reference IS NULL) AND (submitted_at IS NULL) AND (delivered_at IS NULL) AND (failed_at IS NULL) AND (failure_class IS NULL))
    WHEN 'SUBMITTING'::text THEN ((send_idempotency_key IS NOT NULL) AND (send_fingerprint IS NOT NULL) AND (send_requested_by IS NOT NULL) AND (send_requested_at IS NOT NULL) AND (submitted_at IS NULL) AND (delivered_at IS NULL) AND (failed_at IS NULL) AND (failure_class IS NULL))
    WHEN 'SUBMITTED'::text THEN ((send_idempotency_key IS NOT NULL) AND (send_fingerprint IS NOT NULL) AND (send_requested_by IS NOT NULL) AND (send_requested_at IS NOT NULL) AND (provider_reference IS NOT NULL) AND (submitted_at IS NOT NULL) AND (delivered_at IS NULL) AND (failed_at IS NULL) AND (failure_class IS NULL))
    WHEN 'DELIVERED'::text THEN ((send_idempotency_key IS NOT NULL) AND (send_fingerprint IS NOT NULL) AND (send_requested_by IS NOT NULL) AND (send_requested_at IS NOT NULL) AND (provider_reference IS NOT NULL) AND (submitted_at IS NOT NULL) AND (delivered_at IS NOT NULL) AND (failed_at IS NULL) AND (failure_class IS NULL))
    WHEN 'FAILED'::text THEN ((send_idempotency_key IS NOT NULL) AND (send_fingerprint IS NOT NULL) AND (send_requested_by IS NOT NULL) AND (send_requested_at IS NOT NULL) AND (failed_at IS NOT NULL) AND (failure_class IS NOT NULL) AND (delivered_at IS NULL) AND (((submitted_at IS NULL) AND (provider_reference IS NULL)) OR ((submitted_at IS NOT NULL) AND (provider_reference IS NOT NULL))))
    ELSE false
END),
    CONSTRAINT iplc_provider_ref_len_chk CHECK (((provider_reference IS NULL) OR (char_length(provider_reference) <= 200))),
    CONSTRAINT iplc_purpose_chk CHECK ((purpose = 'RESPONSIBLE_GAMBLING'::text)),
    CONSTRAINT iplc_request_fp_chk CHECK ((request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT iplc_send_fp_chk CHECK (((send_fingerprint IS NULL) OR (send_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT iplc_sequence_chk CHECK ((sequence > 0)),
    CONSTRAINT iplc_status_chk CHECK ((status = ANY (ARRAY['PENDING'::text, 'SUBMITTING'::text, 'SUBMITTED'::text, 'DELIVERED'::text, 'FAILED'::text]))),
    CONSTRAINT iplc_template_key_chk CHECK ((template_key = ANY (ARRAY['rg.limit_confirmation'::text, 'rg.timeout_confirmation'::text, 'rg.self_exclusion_support'::text, 'rg.helpline_support'::text, 'rg.counselling_support'::text]))),
    CONSTRAINT iplc_template_version_chk CHECK ((template_version > 0))
);

