    processed_at timestamp with time zone,
    ingest_version text DEFAULT 'v1'::text NOT NULL,
    raw_payload jsonb,
    CONSTRAINT live_events_amounts_positive CHECK (((bet_amount >= (0)::numeric) AND (win_amount >= (0)::numeric))),
    CONSTRAINT live_events_event_type_check CHECK ((event_type = ANY (ARRAY['BET_PLACED'::text, 'BET_RESULT'::text, 'SESSION_START'::text, 'SESSION_END'::text, 'GAME_SPIN'::text, 'HAND_PLAYED'::text, 'DEPOSIT'::text, 'WITHDRAWAL'::text, 'TIME_SPENT_UPDATE'::text, 'MACHINE_ACTIVITY'::text, 'RISK_FLAG'::text, 'CARD_INSERT'::text, 'MACHINE_ALLOCATED'::text, 'CASH_OUT'::text, 'CARD_REMOVED'::text, 'MACHINE_IDLE'::text, 'RISK_ALERT'::text, 'INTERVENTION_TRIGGERED'::text, 'JACKPOT'::text, 'MACHINE_FAULT'::text, 'VIP_ACTIVITY'::text, 'SELF_EXCLUSION'::text, 'SECURITY_EVENT'::text]))),
    CONSTRAINT live_events_outcome_check CHECK ((outcome = ANY (ARRAY['win'::text, 'loss'::text, 'push'::text, 'active'::text, NULL::text]))),
