    CONSTRAINT live_events_risk_score_range CHECK (((risk_score >= 0) AND (risk_score <= 100))),
    CONSTRAINT live_events_source_check CHECK ((source = ANY (ARRAY['simulator'::text, 'api_ingest'::text, 'realtime_webhook'::text, 'manual'::text])))
);

