--
-- Name: mv_api_traffic_hourly; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_api_traffic_hourly AS
 SELECT date_trunc('hour'::text, created_at) AS hour_bucket,
    endpoint,
    count(*) AS total_requests,
    count(*) FILTER (WHERE (status_code >= 400)) AS error_requests,
    count(*) FILTER (WHERE (is_rate_limited = true)) AS rate_limited_requests,
    count(DISTINCT casino_id) AS unique_casinos,
    avg(response_ms) AS avg_response_ms,
    max(response_ms) AS max_response_ms,
    round((((count(*) FILTER (WHERE (status_code >= 400)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 2) AS error_rate
   FROM public.api_activity aa
  WHERE (created_at >= (now() - '7 days'::interval))
  GROUP BY (date_trunc('hour'::text, created_at)), endpoint
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_api_traffic_hourly OWNER TO postgres;

