--
-- Name: mv_casino_daily_stats; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_casino_daily_stats AS
 SELECT s.casino_id,
    c.name AS casino_name,
    (date_trunc('day'::text, s.started_at))::date AS stat_date,
    count(DISTINCT s.id) AS total_sessions,
    count(DISTINCT s.player_id) AS unique_players,
    COALESCE(sum(s.total_wagered), (0)::numeric) AS total_wagered,
    COALESCE(sum(s.total_won), (0)::numeric) AS total_won,
    COALESCE(sum((s.total_wagered - s.total_won)), (0)::numeric) AS gross_gaming_revenue,
    count(DISTINCT
        CASE
            WHEN (s.is_flagged = true) THEN s.id
            ELSE NULL::uuid
        END) AS flagged_sessions,
    avg(s.duration_seconds) AS avg_session_duration_secs,
    count(DISTINCT
        CASE
            WHEN (s.game_type = 'slots'::text) THEN s.id
            ELSE NULL::uuid
        END) AS slots_sessions,
    count(DISTINCT
        CASE
            WHEN (s.game_type = 'table'::text) THEN s.id
            ELSE NULL::uuid
        END) AS table_sessions,
    count(DISTINCT
        CASE
            WHEN (s.device_type = 'mobile'::text) THEN s.id
            ELSE NULL::uuid
        END) AS mobile_sessions
   FROM (public.sessions s
     LEFT JOIN public.casinos c ON ((c.id = s.casino_id)))
  WHERE (s.started_at >= (now() - '90 days'::interval))
  GROUP BY s.casino_id, c.name, ((date_trunc('day'::text, s.started_at))::date)
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_casino_daily_stats OWNER TO postgres;

