--
-- Name: mv_casino_risk_distribution; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_casino_risk_distribution AS
 SELECT p.casino_id,
    c.name AS casino_name,
    count(*) FILTER (WHERE (p.risk_level = 'critical'::text)) AS critical_count,
    count(*) FILTER (WHERE (p.risk_level = 'high'::text)) AS high_count,
    count(*) FILTER (WHERE (p.risk_level = 'medium'::text)) AS medium_count,
    count(*) FILTER (WHERE (p.risk_level = 'low'::text)) AS low_count,
    count(*) FILTER (WHERE (p.is_active = true)) AS active_players,
    count(*) AS total_players,
    round((((count(*) FILTER (WHERE (p.risk_level = ANY (ARRAY['critical'::text, 'high'::text]))))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 2) AS high_risk_percentage
   FROM (public.players p
     LEFT JOIN public.casinos c ON ((c.id = p.casino_id)))
  GROUP BY p.casino_id, c.name
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_casino_risk_distribution OWNER TO postgres;

--
-- Name: mv_intervention_effectiveness; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_intervention_effectiveness AS
 SELECT casino_id,
    intervention_type,
    count(*) AS total_interventions,
    count(*) FILTER (WHERE (intervention_successful = true)) AS successful_count,
    count(*) FILTER (WHERE (intervention_successful = false)) AS unsuccessful_count,
    round((((count(*) FILTER (WHERE (intervention_successful = true)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 2) AS success_rate,
    min(triggered_at) AS first_intervention,
    max(triggered_at) AS last_intervention
   FROM public.intervention_history ih
  GROUP BY casino_id, intervention_type
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_intervention_effectiveness OWNER TO postgres;

--
-- Name: mv_player_risk_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_player_risk_summary AS
 SELECT casino_id,
    risk_level,
    count(*) AS player_count,
    round(avg(risk_score), 1) AS avg_risk_score,
    max(risk_score) AS max_risk_score
   FROM public.players p
  WHERE (is_active = true)
  GROUP BY casino_id, risk_level
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_player_risk_summary OWNER TO postgres;

