CREATE TABLE public.player_bets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    session_id uuid,
    player_id uuid,
    game_type text NOT NULL,
    bet_amount numeric NOT NULL,
    win_amount numeric DEFAULT 0,
    outcome text NOT NULL,
    "timestamp" timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now(),
    casino_id uuid NOT NULL,
    session_id_uuid uuid,
    machine_id text,
    game_round_id text,
    currency text DEFAULT 'ZAR'::text NOT NULL,
    risk_score integer DEFAULT 0 NOT NULL,
    is_simulated boolean DEFAULT false NOT NULL,
    source text DEFAULT 'simulator'::text NOT NULL,
    CONSTRAINT player_bets_amounts_positive CHECK (((bet_amount >= (0)::numeric) AND (win_amount >= (0)::numeric))),
    CONSTRAINT player_bets_source_check CHECK ((source = ANY (ARRAY['simulator'::text, 'api_ingest'::text, 'manual'::text]))),
    CONSTRAINT valid_outcome CHECK ((outcome = ANY (ARRAY['win'::text, 'loss'::text, 'push'::text])))
);


ALTER TABLE public.player_bets OWNER TO postgres;

