--
-- Name: player_protection_alerts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.player_protection_alerts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    casino_id uuid NOT NULL,
    player_id uuid NOT NULL,
    alert_type text NOT NULL,
    rule_version text NOT NULL,
    self_exclusion_id uuid,
    intervention_id uuid,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'OPEN'::text NOT NULL,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    generated_by uuid NOT NULL,
    acknowledged_at timestamp with time zone,
    acknowledged_by uuid,
    resolved_at timestamp with time zone,
    resolved_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT player_protection_alerts_alert_type_check CHECK ((alert_type = ANY (ARRAY['SELF_EXCLUSION_BREACH_REVIEW'::text, 'INTERVENTION_FOLLOW_UP_OVERDUE'::text]))),
    CONSTRAINT player_protection_alerts_rule_version_check CHECK ((length(btrim(rule_version)) > 0)),
    CONSTRAINT player_protection_alerts_status_check CHECK ((status = ANY (ARRAY['OPEN'::text, 'ACKNOWLEDGED'::text, 'RESOLVED'::text]))),
    CONSTRAINT ppa_ack_coherent CHECK (((status <> 'ACKNOWLEDGED'::text) OR ((acknowledged_at IS NOT NULL) AND (acknowledged_by IS NOT NULL) AND (resolved_at IS NULL) AND (resolved_by IS NULL)))),
    CONSTRAINT ppa_ack_pairing CHECK (((acknowledged_at IS NULL) = (acknowledged_by IS NULL))),
    CONSTRAINT ppa_open_coherent CHECK (((status <> 'OPEN'::text) OR ((acknowledged_at IS NULL) AND (acknowledged_by IS NULL) AND (resolved_at IS NULL) AND (resolved_by IS NULL)))),
    CONSTRAINT ppa_resolved_coherent CHECK (((status <> 'RESOLVED'::text) OR ((resolved_at IS NOT NULL) AND (resolved_by IS NOT NULL)))),
    CONSTRAINT ppa_resolved_pairing CHECK (((resolved_at IS NULL) = (resolved_by IS NULL))),
    CONSTRAINT ppa_source_shape CHECK ((((alert_type = 'SELF_EXCLUSION_BREACH_REVIEW'::text) AND (self_exclusion_id IS NOT NULL) AND (intervention_id IS NULL)) OR ((alert_type = 'INTERVENTION_FOLLOW_UP_OVERDUE'::text) AND (intervention_id IS NOT NULL) AND (self_exclusion_id IS NULL))))
);

ALTER TABLE ONLY public.player_protection_alerts FORCE ROW LEVEL SECURITY;


ALTER TABLE public.player_protection_alerts OWNER TO postgres;

--
-- Name: player_protection_interventions; Type: TABLE; Schema: public; Owner: postgres
--

