    outcome text,
    follow_up_required boolean DEFAULT false,
    follow_up_date date,
    staff_id uuid,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    dispatch_status text DEFAULT 'sent'::text,
    triggered_at timestamp with time zone DEFAULT now(),
    risk_score_at_trigger numeric,
    intervention_successful boolean DEFAULT true,
    auto_triggered boolean DEFAULT true,
    channel text DEFAULT 'system'::text NOT NULL,
    message_content text,
    delivered_at timestamp with time zone,
    delivery_attempts integer DEFAULT 0 NOT NULL,
    delivery_error text,
    acknowledged_at timestamp with time zone,
    acknowledged_by text,
    risk_score_after integer,
    nrgp_reported boolean DEFAULT false NOT NULL,
    nrgp_reported_at timestamp with time zone,
    compliance_ref text,
    source text DEFAULT 'auto'::text NOT NULL,
    b9_idempotency_key uuid,
    b9_request_fingerprint text,
    CONSTRAINT player_protection_interventions_channel_check CHECK ((channel = ANY (ARRAY['whatsapp'::text, 'sms'::text, 'email'::text, 'in_app'::text, 'system'::text, 'manual'::text]))),
    CONSTRAINT player_protection_interventions_dispatch_status_check CHECK ((dispatch_status = ANY (ARRAY['pending'::text, 'sent'::text, 'delivered'::text, 'failed'::text]))),
    CONSTRAINT player_protection_interventions_intervention_type_check CHECK ((intervention_type = ANY (ARRAY['ai_alert'::text, 'manual_review'::text, 'limit_setting'::text, 'timeout'::text, 'self_exclusion_referral'::text, 'helpline_referral'::text, 'counseling_referral'::text]))),
    CONSTRAINT player_protection_interventions_outcome_check CHECK ((outcome = ANY (ARRAY['accepted'::text, 'declined'::text, 'pending'::text, 'successful'::text, 'unsuccessful'::text]))),
    CONSTRAINT player_protection_interventions_risk_score_check CHECK (((risk_score >= 0) AND (risk_score <= 100))),
    CONSTRAINT player_protection_interventions_source_check CHECK ((source = ANY (ARRAY['auto'::text, 'manual'::text, 'regulator_mandated'::text]))),
    CONSTRAINT ppi_b9_idempotency_pairing CHECK (((b9_idempotency_key IS NULL) = (b9_request_fingerprint IS NULL))),
    CONSTRAINT ppi_follow_up_consistency CHECK (((follow_up_required IS TRUE) OR (follow_up_date IS NULL)))
);

ALTER TABLE ONLY public.player_protection_interventions FORCE ROW LEVEL SECURITY;


ALTER TABLE public.player_protection_interventions OWNER TO postgres;

