--
-- Name: projection_audit_verification_health; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.projection_audit_verification_health WITH (security_invoker='true') AS
 SELECT h.chain_scope,
        CASE
            WHEN (h.chain_scope = 'platform'::text) THEN 'platform'::text
            ELSE 'casino'::text
        END AS boundary_type,
    h.chain_sequence AS head_sequence,
    h.head_hash,
    cp.verified_through_sequence,
    cp.verified_head_hash,
    cp.result AS checkpoint_result,
    cp.verified_at,
    ( SELECT max(r.started_at) AS max
           FROM public.audit_verification_run r
          WHERE ((r.chain_scope = h.chain_scope) AND (r.mode = 'full'::text) AND (r.result = 'verified'::text))) AS last_full_verified_at,
    ( SELECT max(r.started_at) AS max
           FROM public.audit_verification_run r
          WHERE ((r.chain_scope = h.chain_scope) AND (r.result = 'verified'::text))) AS last_verified_at,
        CASE
            WHEN (cp.chain_scope IS NULL) THEN 'unavailable'::text
            WHEN (cp.result = 'broken'::text) THEN 'broken'::text
            WHEN ((cp.result = 'verified'::text) AND (cp.verified_through_sequence = h.chain_sequence) AND (cp.verified_at > (now() - '1 day'::interval))) THEN 'healthy'::text
            WHEN (cp.result = 'verified'::text) THEN 'warning'::text
            ELSE 'degraded'::text
        END AS integrity_status
   FROM (public.audit_chain_head h
     LEFT JOIN public.audit_chain_checkpoint cp ON ((cp.chain_scope = h.chain_scope)));


ALTER VIEW public.projection_audit_verification_health OWNER TO postgres;

