--
-- Name: projection_session_posture; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.projection_session_posture WITH (security_invoker='true') AS
 SELECT s.session_id,
    s.casino_id,
    s.safebet_player_id,
    s.machine_id,
    s.status,
    s.started_at,
    s.last_event_at,
    s.ended_at,
    s.ended_reason,
    round((EXTRACT(epoch FROM (now() - COALESCE(s.last_event_at, s.started_at))) / 60.0), 1) AS idle_minutes,
        CASE
            WHEN (s.status = 'ended'::text) THEN 'closed'::text
            WHEN (COALESCE(s.last_event_at, s.started_at) >= (now() - make_interval(mins => pol.idle_after_minutes))) THEN 'active'::text
            WHEN (COALESCE(s.last_event_at, s.started_at) >= (now() - make_interval(mins => pol.stale_after_minutes))) THEN 'idle'::text
            ELSE 'stale'::text
        END AS posture
   FROM (public.projection_session_state s
     CROSS JOIN LATERAL ( SELECT sbiq_session_policy.idle_after_minutes,
            sbiq_session_policy.stale_after_minutes,
            sbiq_session_policy.concurrency_limit
           FROM public.sbiq_session_policy(s.casino_id) sbiq_session_policy(idle_after_minutes, stale_after_minutes, concurrency_limit)) pol);


ALTER VIEW public.projection_session_posture OWNER TO postgres;

--
-- Name: projection_casino_state; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.projection_casino_state WITH (security_invoker='true') AS
 SELECT casino_id,
    count(*) FILTER (WHERE (status = 'active'::text)) AS active_players,
    ( SELECT count(*) AS count
           FROM public.projection_session_posture sp
          WHERE ((sp.casino_id = p.casino_id) AND (sp.posture = 'active'::text))) AS active_sessions,
    ( SELECT count(*) AS count
           FROM public.projection_machine_state m
          WHERE ((m.casino_id = p.casino_id) AND (m.status = 'active'::text))) AS active_machines,
    COALESCE(sum(total_wagered), (0)::numeric) AS total_wagered,
    COALESCE(sum(total_won), (0)::numeric) AS total_won,
    COALESCE(sum((total_wagered - total_won)), (0)::numeric) AS ggr,
    count(*) FILTER (WHERE ((status = 'active'::text) AND (risk_score >= (80)::numeric))) AS risk_critical,
    count(*) FILTER (WHERE ((status = 'active'::text) AND (risk_score >= (60)::numeric) AND (risk_score < (80)::numeric))) AS risk_high,
    count(*) FILTER (WHERE ((status = 'active'::text) AND (risk_score >= (40)::numeric) AND (risk_score < (60)::numeric))) AS risk_medium,
    count(*) FILTER (WHERE ((status = 'active'::text) AND (risk_score < (40)::numeric) AND (NOT ((risk_score = (0)::numeric) AND (bet_count = 0) AND (risk_flags = '[]'::jsonb))))) AS risk_low,
    max(last_event_at) AS last_event_at,
    count(*) FILTER (WHERE ((status = 'active'::text) AND (risk_score = (0)::numeric) AND (bet_count = 0) AND (risk_flags = '[]'::jsonb))) AS risk_unclassified,
    ( SELECT count(*) AS count
           FROM public.projection_session_posture sp
          WHERE ((sp.casino_id = p.casino_id) AND (sp.posture = 'idle'::text))) AS idle_sessions,
    ( SELECT count(*) AS count
           FROM public.projection_session_posture sp
          WHERE ((sp.casino_id = p.casino_id) AND (sp.posture = 'stale'::text))) AS stale_sessions,
    ( SELECT count(*) AS count
           FROM public.projection_session_state s
          WHERE ((s.casino_id = p.casino_id) AND (s.status = 'active'::text))) AS open_sessions,
    count(*) FILTER (WHERE ((status = 'active'::text) AND (last_event_at >= (now() - make_interval(mins => ( SELECT sbiq_session_policy.idle_after_minutes
           FROM public.sbiq_session_policy(p.casino_id) sbiq_session_policy(idle_after_minutes, stale_after_minutes, concurrency_limit))))))) AS players_active_now,
    count(*) FILTER (WHERE ((status = 'active'::text) AND (last_event_at < (now() - make_interval(mins => ( SELECT sbiq_session_policy.idle_after_minutes
           FROM public.sbiq_session_policy(p.casino_id) sbiq_session_policy(idle_after_minutes, stale_after_minutes, concurrency_limit))))) AND (last_event_at >= (now() - make_interval(mins => ( SELECT sbiq_session_policy.stale_after_minutes
           FROM public.sbiq_session_policy(p.casino_id) sbiq_session_policy(idle_after_minutes, stale_after_minutes, concurrency_limit))))))) AS players_idle,
    count(*) FILTER (WHERE ((status = 'active'::text) AND ((last_event_at IS NULL) OR (last_event_at < (now() - make_interval(mins => ( SELECT sbiq_session_policy.stale_after_minutes
           FROM public.sbiq_session_policy(p.casino_id) sbiq_session_policy(idle_after_minutes, stale_after_minutes, concurrency_limit)))))))) AS players_stale,
    ( SELECT count(*) AS count
           FROM public.projection_machine_state m
          WHERE ((m.casino_id = p.casino_id) AND (m.status = 'active'::text) AND (m.last_event_at >= (now() - make_interval(mins => ( SELECT sbiq_session_policy.idle_after_minutes
                   FROM public.sbiq_session_policy(p.casino_id) sbiq_session_policy(idle_after_minutes, stale_after_minutes, concurrency_limit))))))) AS machines_in_play,
    ( SELECT count(*) AS count
           FROM public.projection_machine_state m
          WHERE ((m.casino_id = p.casino_id) AND (m.status = 'active'::text) AND ((m.last_event_at IS NULL) OR (m.last_event_at < (now() - make_interval(mins => ( SELECT sbiq_session_policy.idle_after_minutes
                   FROM public.sbiq_session_policy(p.casino_id) sbiq_session_policy(idle_after_minutes, stale_after_minutes, concurrency_limit)))))))) AS machines_stale,
    ( SELECT count(*) AS count
           FROM public.projection_machine_state m
          WHERE (m.casino_id = p.casino_id)) AS registered_machines
   FROM public.projection_player_state p
  GROUP BY casino_id;


ALTER VIEW public.projection_casino_state OWNER TO postgres;

--
-- Name: projection_compliance_state; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.projection_compliance_state WITH (security_invoker='true') AS
 SELECT casino_id,
    safebet_player_id,
    risk_score,
    risk_flags,
    intervention_count,
    last_intervention_at,
    last_event_at
   FROM public.projection_player_state
  WHERE ((risk_score >= (60)::numeric) OR (intervention_count > 0));


