 SELECT casino_id,
    active_players,
    active_sessions,
    active_machines,
    total_wagered,
    total_won,
    ggr,
    risk_critical,
    risk_high,
    risk_medium,
    risk_low,
    last_event_at,
    risk_unclassified
   FROM public.projection_casino_state;


ALTER VIEW public.projection_executive_state OWNER TO postgres;

--
-- Name: projection_intervention_outcome_state; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.projection_intervention_outcome_state WITH (security_invoker='true') AS
 SELECT casino_id,
    count(*) AS interventions_recorded,
    count(DISTINCT player_id) AS distinct_players,
    count(*) FILTER (WHERE (outcome = 'accepted'::text)) AS outcome_accepted,
    count(*) FILTER (WHERE (outcome = 'declined'::text)) AS outcome_declined,
    count(*) FILTER (WHERE (outcome = 'pending'::text)) AS outcome_pending,
    count(*) FILTER (WHERE (outcome = 'successful'::text)) AS outcome_successful,
    count(*) FILTER (WHERE (outcome = 'unsuccessful'::text)) AS outcome_unsuccessful,
    count(*) FILTER (WHERE (dispatch_status = 'sent'::text)) AS status_sent,
    count(*) FILTER (WHERE (dispatch_status = 'delivered'::text)) AS status_delivered,
    count(*) FILTER (WHERE (follow_up_required IS TRUE)) AS follow_up_required,
    count(*) FILTER (WHERE (nrgp_reported IS TRUE)) AS nrgp_reported,
    count(*) FILTER (WHERE (outcome IS NOT NULL)) AS with_outcome,
    count(*) FILTER (WHERE (delivered_at IS NOT NULL)) AS with_delivered_at,
    count(*) FILTER (WHERE (acknowledged_at IS NOT NULL)) AS with_acknowledged_at,
    count(*) FILTER (WHERE (risk_score_after IS NOT NULL)) AS with_risk_score_after,
    max(COALESCE(intervention_date, triggered_at, created_at)) AS last_intervention_at
   FROM public.player_protection_interventions ppi
  GROUP BY casino_id;


ALTER VIEW public.projection_intervention_outcome_state OWNER TO postgres;

--
-- Name: VIEW projection_intervention_outcome_state; Type: COMMENT; Schema: public; Owner: postgres
