--
-- Name: sbiq_event_log_partition_security; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.sbiq_event_log_partition_security AS
 SELECT c.relname AS partition,
    pg_get_expr(c.relpartbound, c.oid) AS partition_bound,
    c.relrowsecurity AS rls_enabled,
    pg_get_userbyid(c.relowner) AS owner,
    (NOT (EXISTS ( SELECT 1
           FROM information_schema.role_table_grants g
          WHERE (((g.table_schema)::name = 'public'::name) AND ((g.table_name)::name = c.relname) AND ((g.grantee)::name = ANY (ARRAY['anon'::name, 'authenticated'::name])))))) AS no_client_grants,
    (c.relrowsecurity AND (NOT (EXISTS ( SELECT 1
           FROM information_schema.role_table_grants g
          WHERE (((g.table_schema)::name = 'public'::name) AND ((g.table_name)::name = c.relname) AND ((g.grantee)::name = ANY (ARRAY['anon'::name, 'authenticated'::name]))))))) AS is_secure
   FROM (((pg_inherits i
     JOIN pg_class c ON ((c.oid = i.inhrelid)))
     JOIN pg_class parent ON ((parent.oid = i.inhparent)))
     JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
  WHERE ((parent.relname = 'casino_event_log'::name) AND (n.nspname = 'public'::name) AND (c.relkind = 'r'::"char"));


ALTER VIEW public.sbiq_event_log_partition_security OWNER TO postgres;

--
-- Name: VIEW sbiq_event_log_partition_security; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.sbiq_event_log_partition_security IS 'Security posture of every casino_event_log partition (RLS + client grants). is_secure=false indicates an exposed partition. Consumed by Platform Health / admin integrity checks.';


