--
-- Name: sen_exclusion_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.sen_exclusion_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    submitting_casino_id uuid NOT NULL,
    submitted_by uuid,
    player_id uuid,
    pseudonym_token text NOT NULL,
    exclusion_type text NOT NULL,
    exclusion_reason text DEFAULT ''::text,
    duration_months integer DEFAULT 6 NOT NULL,
    exclusion_start_date date DEFAULT CURRENT_DATE NOT NULL,
    exclusion_end_date date NOT NULL,
    is_permanent boolean DEFAULT false NOT NULL,
    risk_score_at_exclusion integer DEFAULT 0,
    trigger_event text DEFAULT ''::text,
    cross_operator_history boolean DEFAULT false,
    previous_exclusions integer DEFAULT 0,
    status text DEFAULT 'pending'::text NOT NULL,
    validated_at timestamp with time zone,
    broadcast_at timestamp with time zone,
    expires_at timestamp with time zone,
    reported_to_nrgp boolean DEFAULT false,
    nrgp_reference text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sen_exclusion_events_duration_months_check CHECK (((duration_months >= 1) AND (duration_months <= 120))),
    CONSTRAINT sen_exclusion_events_exclusion_type_check CHECK ((exclusion_type = ANY (ARRAY['voluntary_self_exclusion'::text, 'operator_initiated'::text, 'regulatory_order'::text, 'family_requested'::text, 'national_register'::text]))),
    CONSTRAINT sen_exclusion_events_risk_score_at_exclusion_check CHECK (((risk_score_at_exclusion >= 0) AND (risk_score_at_exclusion <= 100))),
    CONSTRAINT sen_exclusion_events_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'validated'::text, 'broadcast'::text, 'expired'::text, 'revoked'::text])))
);


ALTER TABLE public.sen_exclusion_events OWNER TO postgres;

