--
-- Name: transactions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    casino_id uuid NOT NULL,
    session_id uuid,
    player_id uuid,
    player_token text NOT NULL,
    transaction_type text NOT NULL,
    amount numeric(14,2) DEFAULT 0 NOT NULL,
    currency text DEFAULT 'ZAR'::text NOT NULL,
    game_type text,
    risk_flag boolean DEFAULT false,
    risk_reason text,
    processed_at timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT transactions_transaction_type_check CHECK ((transaction_type = ANY (ARRAY['deposit'::text, 'withdrawal'::text, 'wager'::text, 'win'::text, 'bonus'::text, 'refund'::text])))
);


ALTER TABLE public.transactions OWNER TO postgres;

--
-- Name: transactions_archive; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.transactions_archive (
    id uuid NOT NULL,
    casino_id uuid,
    session_id uuid,
    player_id uuid,
    player_token text,
    transaction_type text,
    amount numeric(12,2),
    balance_before numeric(12,2),
    balance_after numeric(12,2),
    currency text DEFAULT 'ZAR'::text,
    processed_at timestamp with time zone NOT NULL,
    risk_flag boolean DEFAULT false,
    risk_reason text,
    reference_id text,
    created_at timestamp with time zone DEFAULT now()
)
PARTITION BY RANGE (processed_at);


ALTER TABLE public.transactions_archive OWNER TO postgres;

