--
-- Name: v_partition_info; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_partition_info AS
 SELECT parent.relname AS parent_table,
    child.relname AS partition_name,
    pg_get_expr(child.relpartbound, child.oid) AS partition_range,
    pg_size_pretty(pg_total_relation_size((child.oid)::regclass)) AS total_size,
    pg_total_relation_size((child.oid)::regclass) AS total_bytes,
    ( SELECT (pg_class.reltuples)::bigint AS reltuples
           FROM pg_class
          WHERE (pg_class.oid = child.oid)) AS estimated_rows
   FROM (((pg_inherits
     JOIN pg_class parent ON ((pg_inherits.inhparent = parent.oid)))
     JOIN pg_class child ON ((pg_inherits.inhrelid = child.oid)))
     JOIN pg_namespace ns ON ((parent.relnamespace = ns.oid)))
  WHERE ((ns.nspname = 'public'::name) AND (parent.relname = ANY (ARRAY['sessions_archive'::name, 'transactions_archive'::name, 'behaviour_events_archive'::name])))
  ORDER BY parent.relname, child.relname;


ALTER VIEW public.v_partition_info OWNER TO postgres;

