--
-- Name: v_table_size_stats; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_table_size_stats AS
 SELECT tablename,
    pg_size_pretty(pg_total_relation_size((('public.'::text || tablename))::regclass)) AS total_size,
    pg_size_pretty(pg_relation_size((('public.'::text || tablename))::regclass)) AS table_size,
    pg_size_pretty(pg_indexes_size((('public.'::text || tablename))::regclass)) AS indexes_size,
    pg_total_relation_size((('public.'::text || tablename))::regclass) AS total_bytes,
    ( SELECT (pg_class.reltuples)::bigint AS reltuples
           FROM pg_class
          WHERE ((pg_class.relname = t.tablename) AND (pg_class.relnamespace = ('public'::regnamespace)::oid))) AS estimated_rows
   FROM ( VALUES ('sessions'::text), ('transactions'::text), ('behaviour_events'::text), ('players'::text), ('behavioral_risk_profiles'::text), ('interventions'::text), ('intervention_history'::text), ('intervention_delivery_queue'::text), ('security_events'::text), ('api_activity'::text), ('api_rate_limits'::text), ('sessions_archive'::text), ('transactions_archive'::text), ('behaviour_events_archive'::text)) t(tablename)
  ORDER BY (pg_total_relation_size((('public.'::text || tablename))::regclass)) DESC;


ALTER VIEW public.v_table_size_stats OWNER TO postgres;

--
-- Name: v_tenant_health; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_tenant_health WITH (security_invoker='true') AS
 SELECT c.id,
    c.name,
    c.environment,
    c.tier,
    c.is_active,
    c.simulation_mode,
    count(DISTINCT p.id) AS total_players,
    count(DISTINCT gs.id) FILTER (WHERE gs.is_active) AS active_sessions,
    count(DISTINCT oi.id) FILTER (WHERE (oi.health_status = 'healthy'::text)) AS healthy_integrations,
    count(DISTINCT oi.id) FILTER (WHERE (oi.health_status = ANY (ARRAY['error'::text, 'degraded'::text]))) AS degraded_integrations,
    max(le.created_at) AS last_event_at,
    c.created_at AS onboarded_at
   FROM ((((public.casinos c
     LEFT JOIN public.players p ON ((p.casino_id = c.id)))
     LEFT JOIN public.gaming_sessions gs ON ((gs.casino_id = c.id)))
     LEFT JOIN public.operator_integrations oi ON ((oi.casino_id = c.id)))
     LEFT JOIN public.live_events le ON ((le.casino_id = c.id)))
  GROUP BY c.id, c.name, c.environment, c.tier, c.is_active, c.simulation_mode, c.created_at;


ALTER VIEW public.v_tenant_health OWNER TO postgres;

--
-- Name: VIEW v_tenant_health; Type: COMMENT; Schema: public; Owner: postgres
