    CONSTRAINT wellbeing_risk_scores_behaviour_risk_index_check CHECK (((behaviour_risk_index >= (0)::numeric) AND (behaviour_risk_index <= (100)::numeric))),
    CONSTRAINT wellbeing_risk_scores_impulsivity_score_check CHECK (((impulsivity_score >= (0)::numeric) AND (impulsivity_score <= (100)::numeric))),
    CONSTRAINT wellbeing_risk_scores_patience_score_check CHECK (((patience_score >= (0)::numeric) AND (patience_score <= (100)::numeric))),
    CONSTRAINT wellbeing_risk_scores_recovery_response_score_check CHECK (((recovery_response_score >= (0)::numeric) AND (recovery_response_score <= (100)::numeric))),
    CONSTRAINT wellbeing_risk_scores_risk_escalation_score_check CHECK (((risk_escalation_score >= (0)::numeric) AND (risk_escalation_score <= (100)::numeric)))
);


ALTER TABLE public.wellbeing_risk_scores OWNER TO postgres;

--
-- Name: workflow_audit; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.workflow_audit (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    case_id uuid NOT NULL,
    casino_id uuid NOT NULL,
    at timestamp with time zone DEFAULT now() NOT NULL,
    actor text NOT NULL,
    action text NOT NULL,
    from_status text,
    to_status text,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL
);


ALTER TABLE public.workflow_audit OWNER TO postgres;

--
-- Name: workflow_case_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.workflow_case_seq
    START WITH 1000
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE public.workflow_case_seq OWNER TO postgres;

--
-- Name: workflow_cases; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.workflow_cases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    case_number text NOT NULL,
    casino_id uuid NOT NULL,
    case_type text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    priority text DEFAULT 'medium'::text NOT NULL,
    title text NOT NULL,
    summary text,
    subject_kind text DEFAULT 'player'::text NOT NULL,
    subject_ref text,
    assigned_to text,
    due_at timestamp with time zone,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_at timestamp with time zone,
    resolution text,
    evidence_refs jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_by text DEFAULT 'system'::text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workflow_cases_case_type_check CHECK ((case_type = ANY (ARRAY['high-risk-player'::text, 'rg-recommendation'::text, 'compliance-finding'::text, 'regulatory-investigation'::text, 'manual'::text]))),
    CONSTRAINT workflow_cases_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT workflow_cases_status_check CHECK ((status = ANY (ARRAY['open'::text, 'in-review'::text, 'accepted'::text, 'rejected'::text, 'action-recorded'::text, 'outcome-recorded'::text, 'resolved'::text, 'closed'::text])))
);


ALTER TABLE public.workflow_cases OWNER TO postgres;

--
-- Name: workflow_notifications; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.workflow_notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    casino_id uuid NOT NULL,
    case_id uuid,
    recipient text NOT NULL,
    kind text NOT NULL,
    message text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    read_at timestamp with time zone
);


ALTER TABLE public.workflow_notifications OWNER TO postgres;

--
-- Name: workflow_tasks; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.workflow_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    case_id uuid NOT NULL,
    casino_id uuid NOT NULL,
    task_type text DEFAULT 'compliance-action'::text NOT NULL,
    description text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    assigned_to text,
    due_at timestamp with time zone,
    completed_at timestamp with time zone,
    notes text,
    evidence_ref text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workflow_tasks_status_check CHECK ((status = ANY (ARRAY['open'::text, 'in-progress'::text, 'completed'::text, 'escalated'::text])))
);


ALTER TABLE public.workflow_tasks OWNER TO postgres;

