--
-- Name: wellbeing_game_concepts Admins can manage game concepts; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can manage game concepts" ON public.wellbeing_game_concepts TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.users
  WHERE ((users.id = ( SELECT auth.uid() AS uid)) AND (users.role = 'super_admin'::public.user_role))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.users
  WHERE ((users.id = ( SELECT auth.uid() AS uid)) AND (users.role = 'super_admin'::public.user_role)))));


--
-- Name: training_certificates Admins can view all certificates; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can view all certificates" ON public.training_certificates FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.staff
  WHERE ((staff.auth_user_id = ( SELECT auth.uid() AS uid)) AND ((staff.role = ANY (ARRAY['manager'::public.staff_role, 'compliance_officer'::public.staff_role])) OR (staff.user_role = ANY (ARRAY['EXECUTIVE'::public.user_role_type, 'COMPLIANCE'::public.user_role_type]))) AND public.can_user_view_staff(staff.casino_id)))));


--
-- Name: player_consents Admins insert consents; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins insert consents" ON public.player_consents FOR INSERT TO authenticated WITH CHECK ((public.get_my_role() = ANY (ARRAY['super_admin'::text, 'casino_admin'::text])));


--
-- Name: operator_integrations Admins insert integrations; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins insert integrations" ON public.operator_integrations FOR INSERT TO authenticated WITH CHECK (((EXISTS ( SELECT 1
   FROM public.users
  WHERE ((users.id = auth.uid()) AND (users.role = 'super_admin'::public.user_role)))) OR (casino_id = ( SELECT users.casino_id
   FROM public.users
  WHERE (users.id = auth.uid())
 LIMIT 1))));


--
-- Name: ai_decision_log Admins read ai decisions; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins read ai decisions" ON public.ai_decision_log FOR SELECT TO authenticated USING (((public.get_my_role() = ANY (ARRAY['super_admin'::text, 'regulator'::text])) OR ((public.get_my_role() = 'casino_admin'::text) AND (casino_id = ( SELECT u.casino_id
   FROM public.users u
  WHERE (u.id = auth.uid())
 LIMIT 1)))));


