-- Name: training_enrollments Staff and managers can create enrollments; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Staff and managers can create enrollments" ON public.training_enrollments FOR INSERT TO authenticated WITH CHECK (((EXISTS ( SELECT 1
   FROM public.staff
  WHERE ((staff.id = training_enrollments.staff_id) AND (staff.auth_user_id = auth.uid())))) OR (EXISTS ( SELECT 1
   FROM (public.staff s
     JOIN public.staff s2 ON ((s.casino_id = s2.casino_id)))
  WHERE ((s.auth_user_id = auth.uid()) AND (s2.id = training_enrollments.staff_id) AND (s.role = ANY (ARRAY['manager'::public.staff_role, 'compliance_officer'::public.staff_role])))))));


