--
-- Name: casinos casinos_read; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY casinos_read ON public.casinos FOR SELECT USING (
CASE public.fn_my_role()
    WHEN 'super_admin'::text THEN true
    WHEN 'national_regulator'::text THEN true
    WHEN 'provincial_regulator'::text THEN (province = public.fn_my_province())
    WHEN 'casino_admin'::text THEN (id = public.fn_my_casino_id())
    WHEN 'compliance_officer'::text THEN (id = public.fn_my_casino_id())
    ELSE false
END);


--
-- Name: casinos casinos_write; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY casinos_write ON public.casinos USING ((public.fn_my_role() = 'super_admin'::text));


