--
-- Name: gaming_sessions sessions_tenant_isolation; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY sessions_tenant_isolation ON public.gaming_sessions FOR SELECT USING (
CASE public.fn_my_role()
    WHEN 'super_admin'::text THEN true
    WHEN 'national_regulator'::text THEN true
    WHEN 'provincial_regulator'::text THEN (casino_id IN ( SELECT casinos.id
       FROM public.casinos
      WHERE (casinos.province = public.fn_my_province())))
    WHEN 'casino_admin'::text THEN (casino_id = public.fn_my_casino_id())
    WHEN 'compliance_officer'::text THEN (casino_id = public.fn_my_casino_id())
    ELSE false
END);


