--
-- Name: users users_read_own; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY users_read_own ON public.users FOR SELECT USING (((id = auth.uid()) OR (public.fn_my_role() = 'super_admin'::text) OR ((public.fn_my_role() = 'casino_admin'::text) AND (casino_id = public.fn_my_casino_id()))));


--
-- Name: users users_select_casino_isolation; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY users_select_casino_isolation ON public.users FOR SELECT TO authenticated USING (((casino_id = public.get_user_casino_id()) OR public.is_super_admin() OR public.is_regulator() OR (id = auth.uid())));


--
-- Name: users users_write_own; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY users_write_own ON public.users FOR UPDATE USING (((id = auth.uid()) OR (public.fn_my_role() = 'super_admin'::text)));


